	["tid#BountyQuestText1001"]="在巡山时捡到一封信，落款是“张九龄亲启”，张九龄是慕容名仕，可能有什么急事，需要速速送过去",
	["tid#BountyQuestText1002"]="帮姑苏慕容收罗的制琴材料已经集齐，火速送去姑苏慕容",
	["tid#BountyQuestText1003"]="最近朝廷征收鹿茸，听说姑苏慕容周围鹿很多，前往捕捉鹿取一些回来",
	["tid#BountyQuestText1004"]="朝廷急招前往姑苏慕容集合",
	["tid#BountyQuestText1005"]="制作琴的木料已经收集的差不多，速速送去姑苏慕容",
	["tid#BountyQuestText1006"]="在江湖游历时发现一本旧书残页，落款有“太白”字样，速速送还给姑苏慕容人",
	["tid#BountyQuestText1007"]="姑苏慕容主邀请各大势力前往商议大事",
	["tid#BountyQuestText1008"]="在江湖中散落了很多门人字画，被心怀叵测之人恶意篡改，速度送回避免节外生枝",
	["tid#BountyQuestText1009"]="天下纸张价格暴涨，从仓中取出往年纸张送去慕容",
	["tid#BountyQuestText1010"]="江湖中传说有六指琴魔在江中弹琴，在他演奏的地方遗落的一张琴谱，拿到姑苏慕容看看是否是门中遗落之物",
	["tid#BountyQuestText1011"]="武夷山下的强盗被招安了，遗留了很多物资需要运往扬州，需要派遣人手前去帮忙",
	["tid#BountyQuestText1012"]="山庄建设需要很多木材，需要前去武夷山砍伐",
	["tid#BountyQuestText1013"]="山庄建设需要很多木材，需要前去武夷山搬运",
	["tid#BountyQuestText1014"]="又到了武夷山花茶收获的季节，山民有花茶相赠可以前去取来",
	["tid#BountyQuestText1015"]="最近大雨连绵，上山桥被冲垮，需要前去修复",
	["tid#BountyQuestText1016"]="最近大雨连绵，山洪爆发，村民家园被摧毁，出现很多流民，需要派人前去安置",
	["tid#BountyQuestText1017"]="山上寺庙的经书在前几天失窃，派人前去调查始末",
	["tid#BountyQuestText1018"]="武夷山下有猛虎出现，村民非常恐惧，需要派人前去制虎",
	["tid#BountyQuestText1019"]="武夷山下有疫情爆发，派人前往治病",
	["tid#BountyQuestText1020"]="最近大雨连绵，山洪爆发，村民家园被摧毁，需要派人前去帮助村民重建家园",
	["tid#BountyQuestText1021"]="浩气盟有一批军备需要搬运，派侠客前往搬运",
	["tid#BountyQuestText1022"]="有一封书信需要送到盟主手上",
	["tid#BountyQuestText1023"]="浩气盟有紧急调令需要发往前线，十万火急，需派人前往协助",
	["tid#BountyQuestText1024"]="浩气盟有战报需要送往京城，需派人前往协助",
	["tid#BountyQuestText1025"]="浩气盟囤积大量物资需要搬运，请你派人前往协助",
	["tid#BountyQuestText1026"]="浩气盟已派遣众人前往前线，内部非常空虚，当前有恶徒作乱，请你派人协助",
	["tid#BountyQuestText1027"]="浩气盟盟主有大事希望你派人前往商议",
	["tid#BountyQuestText1028"]="浩气盟请你派人深入恶人谷打探消息",
	["tid#BountyQuestText1029"]="浩气盟发现有很多周围的村民被魔教蛊惑，请你派人前往挽救",
	["tid#BountyQuestText1030"]="浩气盟盟主邀请你前往一起绘制江湖地图",
	["tid#BountyQuestText2001"]="神刀门为天下英雄制作刀具，在江湖中发布收购精铁公告，现已获得一些速速送去山庄",
	["tid#BountyQuestText2002"]="神刀门出产兵器，排人去进货贩卖到其他地方",
	["tid#BountyQuestText2003"]="在游历途中寻到一页秘籍疑似是神刀门早年遗失刀谱中其中一页，速速送去",
	["tid#BountyQuestText2004"]="在游历途中一神秘老人让人带信送到山庄给庄主",
	["tid#BountyQuestText2005"]="神刀门拿出在仓库中陈放多年的兵器号召周围武林人来前来磨刀",
	["tid#BountyQuestText2006"]="给玄甲军送酒",
	["tid#BountyQuestText2007"]="带上烈酒去祭奠逝去的玄甲军人",
	["tid#BountyQuestText2008"]="为玄甲军修复损坏的武器",
	["tid#BountyQuestText2009"]="给玄甲军送去村民补贴的军饷",
	["tid#BountyQuestText2010"]="给玄甲军送去神刀门为他们赶制的兵器",
	["tid#BountyQuestText2011"]="悬空寺最近因常年失修最近大雨，寺院东墙塌了，派人前去维修",
	["tid#BountyQuestText2012"]="游历途中寻到一页残片，像是悬空寺早年遗失的经书，派人送去",
	["tid#BountyQuestText2013"]="恒山起雾，去悬空寺进香的香客在下山路上走失，派人前往巡人",
	["tid#BountyQuestText2014"]="太极想要出发再探不归山，邀你助拳。",
	["tid#BountyQuestText2015"]="最近大雨连绵，上山路被冲垮，需要前去修复",
	["tid#BountyQuestText2016"]="雁门关城墙被蛮族破坏，应朝廷号召前去抢修",
	["tid#BountyQuestText2017"]="雁门关被蛮族偷袭，众多边关士兵受伤，派人前去救治",
	["tid#BountyQuestText2018"]="路过一个村庄时有位老人送了你一副铠甲让送到雁门关",
	["tid#BountyQuestText2019"]="路过一个村庄时有位老人递给你一封信让你送去雁门关",
	["tid#BountyQuestText2020"]="为雁门关士兵息修复破损的兵器",
	["tid#BountyQuestText3001"]="崆峒想要出发再探不归山，邀你助拳。你的徒弟在修炼时遇到了瓶颈，想要请你帮忙突破瓶颈。",
	["tid#BountyQuestText3002"]="星宿想要出发再探不归山，邀你助拳。你的徒弟在在修炼时产生了一些疑惑，像请你帮忙答疑。",
	["tid#BountyQuestText3003"]="唐门想要出发再探不归山，邀你助拳。你的徒弟在外边受到了欺负，想请你出手报仇。",
	["tid#BountyQuestText3004"]="桃花想要出发再探不归山，邀你助拳。你的徒弟最近贪图玩乐，武学进境缓慢，必须适当敲打一下了。",
	["tid#BountyQuestText3005"]="花王想要出发再探不归山，邀你助拳。你的徒弟想要快速提升自身的实力，恳请你教授新的功法。",
	["tid#BountyQuestText3006"]="明教想要出发再探不归山，邀你助拳。你的徒弟想要外出历练，但又害怕危险，想请你陪同前去。",
	["tid#BountyQuestText3007"]="天策听闻你的门派实力大增，向你提出了一个考验。你的徒弟在外历练时不小心打坏了村民的房子，被衙门抓走了，衙门要你出面赎人。",
	["tid#BountyQuestText3008"]="红衣听闻你的门派实力大增，向你提出了一个考验。你的徒弟在外历练时发现了一处宝窟，想邀请你一起前往探索。",
	["tid#BountyQuestText3009"]="六扇听闻你的门派实力大增，向你提出了一个考验。你的徒弟在最近的修炼中有了一些感悟，想要和你交流一番。",
	["tid#BountyQuestText3010"]="锦衣听闻你的门派实力大增，向你提出了一个考验。你的徒弟在一场比试中出手太重，击伤了对手，对手的师傅找上门来讨公道了。",
	["tid#BountyQuestText3011"]="少林听闻你的门派实力大增，向你提出了一个考验。你的徒弟最近武学进境神速，想要和你切磋一番。",
	["tid#BountyQuestText3012"]="八卦听闻你的门派实力大增，向你提出了一个考验。你的徒弟在一场比武大赛挺进了决赛，邀请你前往观看。",
	["tid#BountyQuestText3013"]="玄甲听闻你的门派实力大增，向你提出了一个考验。你的师傅刚传授给了你新的武功，要你抓紧时间练习一下。",
	["tid#BountyQuestText3014"]="慕容听闻你的门派实力大增，向你提出了一个考验。你的师傅要考验你最近的功课，给予了你一个小考验。",
	["tid#BountyQuestText3015"]="绝张听闻你的门派实力大增，向你提出了一个考验。你的师傅不太满意你最近的武学进境，要你闭关修炼几天。",
	["tid#BountyQuestText3016"]="霹雳堂听闻你的门派实力大增，向你提出了一个考验。你的师傅准备出门历练一趟，要你一起随行张一张见识。",
