	["tid#BountyEventDes_101"]="没有什么波折顺利到达途中驿站",
	["tid#BountyEventDes_102"]="发现一伙山贼，把山贼头目掉在树上一顿吊打",
	["tid#BountyEventDes_103"]="看到一个疯子在弹琴，疯跑过程中掉落一张破，顺手捡了起来",
	["tid#BountyEventDes_104"]="在路边小店和一个胖子比试吃包子，差点被噎死",
	["tid#BountyEventDes_105"]="抓到一个惯偷，顺便把他扭送官府",
	["tid#BountyEventDes_106"]="被山上一块巨石砸中，居然打通任督二脉，导致怒发冲冠获得新发型",
	["tid#BountyEventDes_107"]="在树林边发现一只可爱的小兔子把它做成了烤乳兔吃了",
	["tid#BountyEventDes_108"]="睡觉的时候被山贼奶奶抓去当压寨夫人，醒来一阵折腾把山寨给烧了",
	["tid#BountyEventDes_109"]="看到路上有一位貌美村姑，目不转睛得看，不小心撞在树上",
	["tid#BountyEventDes_110"]="看到一个位大笑的道长被飞天靴子插在头上，倒地不起也不知道还活着没",
	["tid#BountyEventDes_111"]="被一个俊美无比的印度人问是不是他的真心人，感觉自己微微有点脸红",
	["tid#BountyEventDes_112"]="看到一个一直在毒人跳的妇人后面追着一众家丁，妇人被石头绊了一下蹦进了井里，于是帮忙下井捞人",
	["tid#BountyEventDes_113"]="看到一名红衣美人在水中喝酒，过去跟他过了几招，被其雄厚的内力振飞",
	["tid#BountyEventDes_114"]="路过山岗的时候看到一个漫山遍野唱“我爱你，我爱你，爱老虎油爱老虎油”的疯乞丐，偷偷拿了他丢在烧鸡",
	["tid#BountyEventDes_115"]="碰到一个香肠嘴大耳朵的人，他说自己是小鸭子，然后跳起了小鸭子“我是一只小鸭子咿呀咿呀哟”",
	["tid#BountyEventDes_116"]="看到一个道长在山上大喊“三花聚顶”并且放了三个巨响的屁，把自己真晕了过去，好心把他送到医馆",
	["tid#BountyEventDes_117"]="发现了一伙人正在鬼鬼岁岁的挖洞，疑似盗墓贼，于是把他们扭送官府",
	["tid#BountyEventDes_118"]="进入一个黑点，黑点里卖的包子味道太过奇怪，不能吃，大家只能吐了",
	["tid#BountyEventDes_119"]="遇见一个姑苏慕容人在广场弹琴，一众大妈在旁边跳广场舞，从中间走过时被抓进跳舞队伍陪大妈跳了一段",
	["tid#BountyEventDes_120"]="来到山间泉水变，饮了一口泉水，整个人都神清气爽",
