	["tid#RegionalText_1"]="见过九龄公",
	["tid#RegionalText_2"]="少侠免礼，找老朽有何事",
	["tid#RegionalText_3"]="素来听闻九龄公德高望重，琴艺无双特地前来拜见",
	["tid#RegionalText_4"]="少侠过奖，演奏本事一件娱人身心的事，若演奏之人真心俱正，那么曲子即可驱百祟、荡奸邪",
	["tid#RegionalText_5"]="九龄公果然一身正气，在下顿悟了",
	["tid#RegionalText_6"]="甚好，你我一见如故，不如今日在客房歇息，明日再来我这，自有安排",
	["tid#RegionalText_7"]="在下多谢九龄抬爱",
	["tid#RegionalText_8"]="门人已在门外候着了，会为少侠带路，请",
	["tid#RegionalText_9"]="少侠请随我来",
	["tid#RegionalText_10"]="辛苦师兄带路",
	["tid#RegionalText_11"]="见过九龄公",
	["tid#RegionalText_12"]="你来了，现为你队伍中慕容赠琴一把，此琴为我年少时自己所造，现赠与你",
	["tid#RegionalText_13"]="在下受宠若惊",
	["tid#RegionalText_14"]="大可不必，都是爱乐之人，现邀请慕容跟我合奏一曲",
	["tid#RegionalText_15"]="遵命",
	["tid#RegionalText_16"]="慕容与张九龄合奏一曲",
	["tid#RegionalText_17"]="现在是早课时间，请各位同学跟我一起读....",
	["tid#RegionalText_18"]="夫子读的好，但是我好困ZZZZZZ",
	["tid#RegionalText_19"]="今天的课业结束了，院中来了几位文人墨客，都是当世名人，可前往调教一二",
	["tid#RegionalText_20"]="昔人已乘黄鹤去，此地空余黄鹤楼。黄鹤一去不复返，白云千载空悠悠。",
	["tid#RegionalText_21"]="月落乌啼霜满天，江枫渔火对愁眠。姑苏城外寒山寺，夜半钟声到客船。",
	["tid#RegionalText_22"]="千里黄云白日曛，北风吹雁雪纷纷。莫愁前路无知己，天下谁人不识君。",
	["tid#RegionalText_23"]="秦时明月汉时关，万里长征人未还。但使龙城飞将在，不教胡马度阴山。",
	["tid#RegionalText_24"]="名人都在吟诗啊，都是能流传千古的绝世好句...",
	["tid#RegionalText_25"]="少侠回来上音律课了",
	["tid#RegionalText_26"]="来了来了",
	["tid#RegionalText_27"]="欲修妙音，必先修妙指尖，修指之到，从有而无，因多而寡...",
	["tid#RegionalText_28"]="老师的琴声真好听，ZZZZZZ",
	["tid#RegionalText_29"]="不知不觉今日的课程已经完成了",
	["tid#RegionalText_30"]="早课都进行一半了，现在才来，去院里罚站",
	["tid#RegionalText_31"]="夫子教训的是",
	["tid#RegionalText_32"]="门外传来嘈杂声，去外面看看",
	["tid#RegionalText_33"]="赵宫商你出来，为什么不肯见我，我抱竹是有哪儿对不起你了",
	["tid#RegionalText_34"]="抱竹姑娘，你还是请回吧，赵师兄自苗疆回来之后闭门谢客不见外人，望姑娘不要为难于我",
	["tid#RegionalText_35"]="呜呜呜……赵宫商，你真这么狠心，连我亲自上门都肯见我以免",
	["tid#RegionalText_36"]="我自小在红衣教中长大，那里人都与外间不同，我本以为我会跟他们一样孤独一生，不知何时因药物死去，可我却遇见了赵宫商",
	["tid#RegionalText_37"]="姑娘别哭，你慢慢与我讲",
	["tid#RegionalText_38"]="十一岁那年执行任务时重伤，赵宫商救了我，我从那时起就对教义生疑，与他相处的日子短暂快乐，之后再很难遇",
	["tid#RegionalText_39"]="教中女子地位远远高于男子，教中界面很多憎恨男子，我又是教主亲传，不会有人容忍我的背叛",
	["tid#RegionalText_40"]="虽然师父有所察觉派人监视我，但我还是跑了出来，我现在躲到何处都可能被教中高手抓到，在这之前我想见他一面",
	["tid#RegionalText_41"]="音未落，一枚飞箭划过抱竹应声倒地",
	["tid#RegionalText_42"]="咳……咳……",
	["tid#RegionalText_43"]="抱竹，叛徒，你可知按照教规当如何处置你，虽然你是教主最爱徒弟之一，但是教法无情，你可知罪",
	["tid#RegionalText_44"]="沙利亚武功太高，在场众人无一是其对手，只能眼睁睁看着她带走抱竹",
	["tid#RegionalText_45"]="此人武功太高，刚刚在她威压之下我竟无法动弹",
	["tid#RegionalText_46"]="钟师姐我也是，可怜了那抱竹姑娘",
	["tid#RegionalText_47"]="夫子说桌上有给你留的字条",
	["tid#RegionalText_48"]="字条内容：错过早课，速来书斋一趟",
	["tid#RegionalText_49"]="你来啦，夫子现有事出去了一会儿就回来，叫你过来之后把这些书搬到外面去晒晒",
	["tid#RegionalText_50"]="弟子遵命",
	["tid#RegionalText_51"]="窗外，一个小小身影一闪而过，脚步声向外跑去",
	["tid#RegionalText_52"]="谁在哪里鬼鬼祟祟",
	["tid#RegionalText_53"]="脚步声明显加快，向门外而去，你飞身向前抓住那个黑影，经验是个小童",
	["tid#RegionalText_54"]="你是何人，为何在此鬼鬼祟祟",
	["tid#RegionalText_55"]="你放开我，我什么也没干",
	["tid#RegionalText_56"]="没做亏心事为什么要跑",
	["tid#RegionalText_57"]="因为你追我，我才跑的",
	["tid#RegionalText_58"]="胡搅蛮缠，一定有鬼，跟我去见夫子",
	["tid#RegionalText_59"]="挣扎过程中从小童怀里掉出一本书",
	["tid#RegionalText_60"]="人赃并获，你还有什么好说的",
	["tid#RegionalText_61"]="读书人的事，哪能算偷，最多是借来看看！",
	["tid#RegionalText_62"]="你倒是个辩才，我且听你一辨",
	["tid#RegionalText_63"]="哼，书就是我拿的，每次也都还回去了，有和不妥，何况早有人说过读书人窃书，能算是拿，拿书",
	["tid#RegionalText_64"]="小小年级居然这般才思敏捷，既然这样就放过你吧",
	["tid#RegionalText_65"]="狡辩，走去一起去见夫子",
	["tid#RegionalText_66"]="见就见，哼！",
	["tid#RegionalText_67"]="见过夫子，刚在院内晒书抓到一个小贼",
	["tid#RegionalText_68"]="小童向前紧走两步，对夫子深深一躬",
	["tid#RegionalText_69"]="小子见过夫子",
	["tid#RegionalText_70"]="哦~哈哈哈，原来是你小子啊",
	["tid#RegionalText_71"]="夫子见过我？",
	["tid#RegionalText_72"]="老夫自然见过，只是每次你都来也匆匆去也匆匆，老朽我想叫你一声都来不及",
	["tid#RegionalText_73"]="小童脸上微微一红",
	["tid#RegionalText_74"]="哈哈，你的事我也是知晓的，你之后再也不用偷偷来了，有什么要看的只管跟老朽说，老朽找给你",
	["tid#RegionalText_75"]="多谢夫子",
	["tid#RegionalText_76"]="刚刚在院内打扫发现一个首饰盒，不知是谁的",
	["tid#RegionalText_77"]="打开盒子，里面有一只玉簪和一封信，信上写着赵宫商亲启",
	["tid#RegionalText_78"]="看来是给赵师兄的",
	["tid#RegionalText_79"]="这里我还未打扫完，请少侠代劳把这信送过去吧",
	["tid#RegionalText_80"]="见过赵师兄",
	["tid#RegionalText_81"]="不必多礼，听说门内最近来了一个青年才俊，今日一见果然名不虚传",
	["tid#RegionalText_82"]="赵师兄过奖了，本次来是受人之托前来送信的",
	["tid#RegionalText_83"]="赵宫商接过首饰盒，将其打开，把首饰盒递给旁边门人，轻轻拆开里面的信看了起来……",
	["tid#RegionalText_84"]="良久赵宫商把信收了起来",
	["tid#RegionalText_85"]="抱竹……想不到，九年前一别，如今却……我本无心害人，她却因我遭此大难，不知她被带到哪去了，红衣教进入我姑苏慕容中抓人，决不能让其一走了之，此时必与红衣教有个了断",
	["tid#RegionalText_86"]="赵宫商坐下轻轻抚琴，抚琴一曲离殇悠悠传来",
	["tid#RegionalText_87"]="此时传来一人大声呵斥",
	["tid#RegionalText_88"]="哼，真是愧对姑苏慕容第一才子之名，你方才第三局的廷音稍长，第四节曲谷音微高，结尾处转折未至圆融",
	["tid#RegionalText_89"]="你，哼，我今日不与你争论",
	["tid#RegionalText_90"]="韩非池，你为何整日寻赵师兄麻烦，实在无聊",
	["tid#RegionalText_91"]="他必是自己不精音律，才嫉妒师兄，师兄不必理他",
	["tid#RegionalText_92"]="呵！风流才子，古脉弦歌，竟要师妹帮忙说话么？可惜他心中惦记是个苗疆女子，不是本门女子",
	["tid#RegionalText_93"]="韩非池你住口",
	["tid#RegionalText_94"]="赵宫商愤而起身，一曲音波横扫而出，韩非池不紧不慢将手中笛子横在嘴边，轻轻吹奏，身体周围竟然出现一个音域形成的领域",
	["tid#RegionalText_95"]="两个人都是姑苏慕容中武功高明的人物，短时间内竟分不出胜负，但是产生的巨大音域将院里景物破坏殆尽",
	["tid#RegionalText_96"]="正在此时一到寒芒从树上射下，瞬间将两人摊开，竟然是传说中呆子杨青月",
	["tid#RegionalText_97"]="……",
	["tid#RegionalText_98"]="哼，我废了这么多口舌才激他出手",
	["tid#RegionalText_99"]="今日便到此为止吧",
	["tid#RegionalText_100"]="也罢",
	["tid#RegionalText_101"]="韩非池转身离开",
	["tid#RegionalText_102"]="师兄刚在庭院中拾到此玉佩",
	["tid#RegionalText_103"]="此物是韩非池之物，今日我不想见他，劳烦少侠将此物送去给他吧，他现在在花月别院",
	["tid#RegionalText_104"]="婆婆好~",
	["tid#RegionalText_105"]="少侠免礼，难得有门外人来看我这个老太婆，哎，我老太婆最近也是有些烦心事，但这事又不能跟门人说，只能跟你讲了",
	["tid#RegionalText_106"]="婆婆请讲，在下洗耳恭听",
	["tid#RegionalText_107"]="俊鸿这孩子，我这个当娘的是管不住他了，唉……当前我夫君为叛军所杀，青月也在我怀里受伤，因为愧对老门主，我便对青月多有关照",
	["tid#RegionalText_108"]="却不想冷落的俊鸿，这几年俊鸿爱恋九龄公的女儿婉玉，便托人提亲，谁知婉玉和青月早已情投意合，咳咳……",
	["tid#RegionalText_109"]="婆婆莫急，且慢慢说",
	["tid#RegionalText_110"]="自那以后俊鸿的性子就越来越乖僻，有时竟拿门中弟子出气，你帮我去劝劝他，如不听就替老身教训他",
	["tid#RegionalText_111"]="婆婆莫急，此事交于我吧",
	["tid#RegionalText_112"]="俊鸿在翠湄居，由我来为少侠带路吧",
	["tid#RegionalText_113"]="辛苦这位师兄了",
	["tid#RegionalText_114"]="俊鸿年少时不是现在这样，竹先生去世后虽然很长一段时间俊鸿都不和旁人讲话，但是跟我关系很好练武读书也很用功",
	["tid#RegionalText_115"]="那现在这样是为何",
	["tid#RegionalText_116"]="哎，自从和婉玉学武之后，俊鸿越发勤奋，跟婉玉师姐走的很近，性格也逐渐开朗起来，没想到自从婉玉跟青月师兄的事让他知晓后，性格便变得乖张",
	["tid#RegionalText_117"]="在下了解了，多谢师兄",
	["tid#RegionalText_118"]="前面就是翠湄居，按照平日里的习惯俊鸿此时应该在里面休息，我就不进去了，少侠请自便，告辞",
	["tid#RegionalText_119"]="多谢师兄",
	["tid#RegionalText_120"]="见过师兄",
	["tid#RegionalText_121"]="哪来的小子，我这正在练剑，正好悟出几招新的招式，来来来咱们切磋一下",
	["tid#RegionalText_122"]="少侠莫急,我这有一坛好酒，喝酒解愁，要不要试试",
	["tid#RegionalText_123"]="真有这么神奇?我自幼在姑苏慕容长大，从未接触过酒，拿来我尝尝",
	["tid#RegionalText_124"]="好酒非常甘甜，堪比山间清泉，必让你欲仙欲死，你可知剑仙李白每日酒不离身的",
	["tid#RegionalText_125"]="世间竟有如此神奇的之物？好我且信你",
	["tid#RegionalText_126"]="来来来，竹兄我为你倒上一杯",
	["tid#RegionalText_127"]="此水喝下去，有一股辛辣只意，细品之后却有些甘甜，果然有趣",
	["tid#RegionalText_128"]="竹兄既然喜欢可多饮几杯",
	["tid#RegionalText_129"]="好~既然少侠如此慷慨，我就恭谨不如从命了",
	["tid#RegionalText_130"]="好说好说，来竹兄我为你满上",
	["tid#RegionalText_131"]="嗯~感觉甚秒，我怎得感觉身体有些许发热",
	["tid#RegionalText_132"]="竹兄不必慌张，饮酒之后自然跟练剑之后的发热感觉一样",
	["tid#RegionalText_133"]="感觉确实有些相似",
	["tid#RegionalText_134"]="竹俊鸿面露潮色，似有些不胜酒力",
	["tid#RegionalText_135"]="我看竹兄面露愁苦，今日可有烦心事，不如讲于再下听听",
	["tid#RegionalText_136"]="我愁苦原因说来话长，哎，只因婉玉心中之人不是我，我竹俊鸿居然不如一个呆子，胸中意难平啊",
	["tid#RegionalText_137"]="竹兄所言甚是，但那杨青月必然也有过人之处不然婉玉师姐也不会钟情于他",
	["tid#RegionalText_138"]="竹俊鸿放下杯子，举起酒坛将酒倒入嘴中",
	["tid#RegionalText_139"]="竹兄，慢些饮",
	["tid#RegionalText_140"]="哎，论起武功造诣我也不输杨青月，只因我实战经验太少，每每切磋都输于他，让人非常不甘心",
	["tid#RegionalText_141"]="竹兄想必还没出过姑苏慕容吧",
	["tid#RegionalText_142"]="我自幼在姑苏慕容从未出去过，也没有机会",
	["tid#RegionalText_143"]="据在下所知浩气盟正在招贤，不知竹兄是否愿意前往，即增加实战经验，也不必看这",
	["tid#RegionalText_144"]="说的极是，当初我父亲竹先生琴技天下皆知，传到了我这里虽然只剩半本，但也不能坠了他老人家威名，我欲前往浩气盟，只怕我母亲那边不好交代",
	["tid#RegionalText_145"]="此事交于我吧，我必不辱使命",
	["tid#RegionalText_146"]="多谢兄台",
	["tid#RegionalText_147"]="少侠回来了，可否教训我那不孝子？",
	["tid#RegionalText_148"]="吉婆婆言重了，我已劝说俊鸿，俊鸿愿出门历练，现浩气盟正广纳贤士，婆婆可愿让竹兄前往",
	["tid#RegionalText_149"]="哎，俊鸿经历此事之后想必也长大了，出门历练也好，只是江湖险恶",
	["tid#RegionalText_150"]="如去浩气盟历练，谢盟主自有轻重，给竹兄的任务必循序渐进，只是希望婆婆去门主那求来推荐信之后前去行事比较方便",
	["tid#RegionalText_151"]="还是少侠想的周到，老身这就去求",
	["tid#RegionalText_152"]="辛苦婆婆",
	["tid#RegionalText_153"]="婆婆让我把这封推荐信给你，俊鸿少爷在姑苏慕容大门等您，请您前往",
	["tid#RegionalText_154"]="多谢",
	["tid#RegionalText_155"]="少侠你来了",
	["tid#RegionalText_156"]="竹兄，这是姑苏慕容的推荐信，把信交给谢盟主即可，",
	["tid#RegionalText_157"]="少侠费心了，我这就前往浩气盟，江湖路远，后会有期",
	["tid#RegionalText_158"]="后会有期",
	["tid#RegionalText_159"]="想不到俊鸿竟去浩气盟了，我原来是姑苏慕容的武学教官，竹俊鸿开始习武时也是从我这学武，因朱先生早年与我有治病之恩，甚是感激，因此对竹俊鸿也特别关照，没想到俊鸿他竟对我这般痴，哎也好",
	["tid#RegionalText_160"]="师姐不必太多愧疚，男儿志在四方，待俊鸿兄在江湖中声名远播，自会有他的良缘",
	["tid#RegionalText_161"]="说的极是，是我多虑了",
	["tid#RegionalText_162"]="我和青月婚事将近，请帖还没给剑仙，最近剑仙行踪不定，希望少侠帮我去请帖",
	["tid#RegionalText_163"]="交给在下吧",
	["tid#RegionalText_164"]="听说剑仙在挽音阁，我派门下弟子带少侠过去",
	["tid#RegionalText_165"]="多谢婉玉师姐",
	["tid#RegionalText_166"]="少侠这边请",
	["tid#RegionalText_167"]="多谢，大婚将至，不知婉玉师姐为何面有愁容",
	["tid#RegionalText_168"]="哎，少侠有所不知，我们少门主子小中“阴雨针”，虽用杨家秘术《天音知脉》控制，但是经常陷入梦境",
	["tid#RegionalText_169"]="哦？这就是传闻中的呆病？",
	["tid#RegionalText_170"]="少侠说笑了，被梦境所困，在外人看来就是在发呆了，只怕到时大婚中间又发起病来",
	["tid#RegionalText_171"]="难怪了",
	["tid#RegionalText_172"]="前面就是挽音阁，少侠请在里面等待",
	["tid#RegionalText_173"]="辛苦了",
	["tid#RegionalText_174"]="这位师弟，请问剑仙所在何处啊",
	["tid#RegionalText_175"]="家师被请去怀仁斋了",
	["tid#RegionalText_176"]="多谢师弟",
	["tid#RegionalText_177"]="见过剑仙",
	["tid#RegionalText_178"]="少侠特地来找老夫所谓何事啊",
	["tid#RegionalText_179"]="在下是为送九龄公之女婉玉师妹和少门主青月师兄的喜帖而来",
	["tid#RegionalText_180"]="哈哈，好老夫到时一定准时前往主持婚礼",
	["tid#RegionalText_181"]="既然事已经办妥，小子告退",
	["tid#RegionalText_182"]="你来到落雁峰，将天歌道长的介绍信交给浩气盟盟主谢渊。我有个贵重的礼物，被人抢走，不知道大侠能否帮我夺回来？",
	["tid#RegionalText_183"]="我已听天歌道长多次提及你，中原武林内纷争不断、犹如散沙，外有恶人谷强敌压境，危机四伏。浩气盟欲力挽狂澜，正需要你这等年轻有为的义士。小生先行谢过大侠，强人往城西去了。",
	["tid#RegionalText_184"]="为了考验你的实力，你需要完成浩气七星阵的试炼，此阵由天玑星翟军师所布，你可去找他了解一二。大侠真是身手不凡！居然这么快就打败了贼人！",
	["tid#RegionalText_185"]="是谢盟主让你来的吧？翟某想不到竟是如此年轻有为之人，先容我为你介绍七星阵。的确是我的玉佩，大侠真是信人！不过……我还有一个不情之请……",
	["tid#RegionalText_186"]="有劳翟军师了！这个东西，我想送给我的心上人，又怕太过唐突，不知道大侠能否代劳？",
	["tid#RegionalText_187"]="这七星阵法乃是我依据四象八卦、星象演变而布之阵。可聚天地之气，纳四时之华。又是那位公子……唉……",
	["tid#RegionalText_188"]="七星阵分为内阵和外阵，其中外阵有天枢、天玑、天权、天璇，内阵有玉衡、开阳、摇光，七星试炼先于外阵进行。辛苦这位侠士，不过如此重礼我无法收下，还请还给那位公子。唉，如果那个人也可以如此对我……",
	["tid#RegionalText_189"]="翟军师，如何能前往外阵？果然她还是不肯收下我的心意……窈窕淑女君子好逑，我不会轻易放弃的，明天还请大侠继续帮我！",
	["tid#RegionalText_190"]="整个外阵遍布七座七星岩，目前可选天枢、天璇、天玑、天权四岩进行挑战。我也有个想要交给心上人的礼物，奈何不知道掉在哪里了，是一个我亲手做的香囊……",
	["tid#RegionalText_191"]="你终于来了？我已接到谢盟主与翟军师的口令，这个挑战不简单，切莫大意。大侠您找谁？我爹爹出去喝酒了……",
	["tid#RegionalText_192"]="你终于来了？我已接到谢盟主与翟军师的口令，这个挑战不简单，切莫大意。香囊？我爹爹好像提到捡到一个香囊，我看了一下绣工虽然不大好，但是用的是上好湖稠和金丝……他好像说要拿去换酒钱",
	["tid#RegionalText_193"]="你终于来了？我已接到谢盟主与翟军师的口令，这个挑战不简单，切莫大意。啊？你是什么人？这是我的香囊！",
	["tid#RegionalText_194"]="你终于来了？我已接到谢盟主与翟军师的口令，这个挑战不简单，切莫大意。我就不能用绸子香囊了？你是不是瞧不起本地人啊！",
	["tid#RegionalText_195"]="比我预想的要快很多，恭喜，你已经勘破七星外阵！来人啊！外地人欺负人了！三子！狗剩！快来帮帮大叔我！",
	["tid#RegionalText_196"]="翟军师过奖，破外阵属实困难重重。不知七星内阵又有多少玄机？哎呦……我这老胳膊老腿！拿走拿走！什么破玩意！真是晦气！",
	["tid#RegionalText_197"]="内阵繁复，你前往一探便知。感谢这位侠士……奈何被庸人弄脏的东西配不上那个人了……我再准备一个新的吧……",
	["tid#RegionalText_198"]="外阵已过，不足为奇！内阵能过，才是好汉！这位施主，小僧有礼，不知道施主有没有兴趣和小僧打打机锋？",
	["tid#RegionalText_199"]="你终于来了？我已接到谢盟主与翟军师的口令，这个挑战不简单，切莫大意。小僧有三个佛经的问题，不知施主可以答对几个？",
	["tid#RegionalText_200"]="你终于来了？我已接到谢盟主与翟军师的口令，这个挑战不简单，切莫大意。若菩萨有我相、人相、众生相、寿者相……后面应为？",
	["tid#RegionalText_201"]="你终于来了？我已接到谢盟主与翟军师的口令，这个挑战不简单，切莫大意。所谓佛法者……",
	["tid#RegionalText_202"]="我是浩气盟中负责暗杀和审问的影，既然你已获盟主信任，那也是浩气盟人了，现在我有个任务交给你。'是法平等，无有高下',是哪部经书所言？",
	["tid#RegionalText_203"]="什么任务？所谓般若是指？",
	["tid#RegionalText_204"]="半年前，陶寒亭的大弟子凌之柏被我等捉拿，囚于元风禁狱中，如今他已趁乱逃脱。般若心经开篇是？",
	["tid#RegionalText_205"]="凌之柏在狱中与邹政隆、宋俎得、成关西三大恶人关系甚密，你速用刑具拷问清楚那三人，看能不能逼问出凌之柏的下落。世人皆知“色不异空，空不异色，色即是空，空即是色”，之前一句是？",
	["tid#RegionalText_206"]="这三人分别有什么弱点？「一切有为法，如梦幻泡影，如露亦如电，应作如是观」来自哪部佛经？",
	["tid#RegionalText_207"]="你将荆条、刑杖、烙铁这三件刑具拿去，我会在一旁指点你如何施刑，莫要紧张，只需按照我所说的来，他们定然招架不了。 施主真是博学多才！小僧佩服！请明天也来和小僧研习佛法！不见不散！",
	["tid#RegionalText_208"]="宋俎德下股无力，气息虚浮。施主也是很有佛性了！",
	["tid#RegionalText_209"]="邹政隆修炼硬派气功，以柔克刚是最好的破解方法附近有山贼滋扰相邻，贫僧有心降妖伏魔，又自觉功力不足难以以德服人……",
	["tid#RegionalText_210"]="成关西修炼至阴武学，不惧寒冻。如果施主有心，和小僧一同前往如何？你我联手，应当可以不伤人命化解事端。",
	["tid#RegionalText_211"]="哦？原来那凌之柏和柳初雪经常在冶剑庐北面亭子里幽会……多谢施主相助，小僧之后将对他们讲法一个时辰，然后将他们送交官服，施主若是不忙？不如一起？",
	["tid#RegionalText_212"]="那柳初雪也真够胆大的，我浩气盟内下竟然出了这等败类，当真该杀无赦。施主一看就是好勇斗狠之辈，还请施主听小僧一言，放下屠刀立地成佛……",
	["tid#RegionalText_213"]="我去那里探查一下，看是否口供属实。明日还请施主来此和小僧说法，小僧愿为施主化解戾气",
	["tid#RegionalText_214"]="有劳，若是凌之柏确是在那儿，就将其就地正法。柳初雪也不可放过，应逮捕回来听候盟内发落。这里贴的都是江洋大盗的通缉令，每个人都不好对付哦！",
	["tid#RegionalText_215"]="你、你是何人？如果你想要赏钱，也要量力而为，不要阴沟里翻船了！",
	["tid#RegionalText_216"]="你是浩气盟派来捉我的人？对不对？我……这个是有名的飞贼，来无影去无踪，在本地已经做了很多案子",
	["tid#RegionalText_217"]="怎么就你一人，凌之柏呢？有人在城外看到过他，不过可别想着和他比轻功，你最好准备点暗器绳索之类的。",
	["tid#RegionalText_218"]="终于还是追来了吗？看来终究是逃不过。只愿之柏他……罢了，是谁派你来的？坛里又发生了什么事？能告诉我吗？ 哈哈！想追上我？别开玩笑了！",
	["tid#RegionalText_219"]="你当真不知？凌之柏在浩气盟内离间名剑、神刀，鼓动被囚恶人逃离元风禁狱，叶如海身死，叶梓山重伤…什么东西……你这家伙居然不讲江湖规矩！放开我！！！！",
	["tid#RegionalText_220"]="竟、竟是这样的结局！叶世伯他……死得好惨！哈哈哈！就凭你也想追上老子？再练十年吧……吧……吧……",
	["tid#RegionalText_221"]="我本与之柏约好，等他顺利从狱中逃出，便再也不管什么浩气盟、恶人谷，只愿一同浪迹天涯，去过普通人的生活，再不踏入江湖半步。我……我已在此地等了他整整一天……呵……哦！这家伙的确是林中鹿，你居然能抓住？厉害厉害！",
	["tid#RegionalText_222"]="原来一直都是我一厢情愿…罢了，罢了！这最坏的结局，我早已料到。这个混蛋是人人喊打的采花贼",
	["tid#RegionalText_223"]="你将我的这封书信带回去，就说…是初雪对不住叶伯父、对不住浩气盟。这个人善用各种迷药，没人知道他长什么样",
	["tid#RegionalText_224"]="柳初雪将一封褶皱的书信交给你后，她不知从哪里掏出一柄短匕，竟然自刎在你的面前！恩？有事儿？这狗是干嘛的？",
	["tid#RegionalText_225"]="你回来了，事情进行的可还顺利？啊！这破狗居然咬人！快阻止它！啊！我的手！",
	["tid#RegionalText_226"]="你将柳初雪的遗书交给了他，并告诉了他前因后果。你在闹市转悠了3天，茫茫人海，根本不知道谁是金毛鼠……",
	["tid#RegionalText_227"]="凌之柏这个十恶不赦之徒，害死了多少条人命！是我错怪了柳初雪……这家伙就是采花贼？哦！这是他用的迷药！你就是让狗追着气味……厉害厉害！！",
	["tid#RegionalText_228"]="柳初雪的信，你就交给月弄痕吧。这对叔侄感情深厚，柳初雪之死必不能瞒着月弄痕。这个人在山里啸聚，大兵赶到就逃跑，人少就聚众围攻，很难搞",
	["tid#RegionalText_229"]="哦？你说那三人被拷问之后，招供说凌之柏在五灵原出现，并偕同五毒残害我浩气盟弟子？我不是和你说过这个人连相貌都不知道吗，人海茫茫，你到哪里找去？想清楚方法再来吧！",
	["tid#RegionalText_230"]="笑话。先不说凌之柏与五毒有无干系，五毒行事向来诡异，若真要和浩气对着干，怎么会这么明目张胆？让他们这些喽啰都知道？这个人在山里啸聚，大兵赶到就逃跑，人少就聚众围攻，很难搞",
	["tid#RegionalText_231"]="我也这么认为，不过那三人已经昏死过去，恐怕短时间内很难清醒过来。出动官兵肯定不行了，你要是自己前往，做好对方人多势众的准备",
	["tid#RegionalText_232"]="噗，这倒是有趣，你不妨去一趟栖霞幻境五灵原，找到正诀堂主唐羽。问问他，现在那边是什么情况。你是哪儿来的小子？也敢管老子的闲事？小的们给我上！",
	["tid#RegionalText_233"]="龟儿子的五毒，拉屎拉到老子头上咯。要不是他们的五毒阵厉害，老子早就领着人把蟾仙村荡平咯！有两手啊？再上去一拨人！这次别怕出人命！",
	["tid#RegionalText_234"]="唐堂主，你可有在看到凌之柏？这么多人都对付不了？一帮废物！看我的！！",
	["tid#RegionalText_235"]="什么柏？没听过。你来的正好，先帮老子解决这帮霍霍。看到面前的五毒阵了没？你一个人就拿下了黑斧王？！厉害厉害！！！",
	["tid#RegionalText_236"]="这五毒阵是由五种毒虫组成的，巴实的狠哟。我都差点被咬得翘辫子咯！我这里有点东西想托人带给表哥，不知道您能不能帮忙？",
	["tid#RegionalText_237"]="这阵法……恕晚辈也一时半会研究不透啊……我这里有点东西想托人带给表哥，不知道您能不能帮忙？",
	["tid#RegionalText_238"]="哪个直接求你了哟！你不是飞得快嘛？回去帮我问问翟军师，看有没得办法破阵撒。唉，说来就愁……这是给我爹准备的酒。",
	["tid#RegionalText_239"]="翟军师，唐羽委托我来问你五毒阵的破解之法。但是他一天到晚就知道在外面喝酒，我劝也不听，我真想不管他了……",
	["tid#RegionalText_240"]="唐羽这莽汉，想必是被五毒阵困住了，所以才不得让你来找我了。呵呵。他应该在村里的酒馆喝酒，能不能请您帮我交给他？",
	["tid#RegionalText_241"]="这五毒阵暗含五行相生相克之道，毒性若相互克制，碰到一起便会消解，反之，毒性若相生，则变本加厉。你明白了吗？对，就是这个，能不能麻烦您交给隔壁镇的捕快？他就在大门当值！他是我表哥，叫东柱。",
	["tid#RegionalText_242"]="五行相克是说金克木，木克土，土克水，水克火，火克金。五行相生是说金生水，水生木，木生火，火生土，土生金。这个……是之前一位公子在我这里讨水喝时掉下的。",
	["tid#RegionalText_243"]="然也。你已成竹在胸，不如就去五灵原中央的那座五灵山，试着破一破阵。不知道他人在哪儿，我也没法还给他",
	["tid#RegionalText_244"]="这下好咯，五阵俱破，五毒教也没得啥子招数咯。我倒要看看他们如今咋个办？不知道您能不能帮我留意一下？",
	["tid#RegionalText_245"]="我有个贵重的礼物，被人抢走，不知道大侠能否帮我夺回来？哦？这是我家闺女给我带的酒！一闻就知道，16年的女儿红！",
	["tid#RegionalText_246"]="小生先行谢过大侠，强人往城西去了。#REF!",
	["tid#RegionalText_247"]="大侠真是身手不凡！居然这么快就打败了贼人！幸亏当年我多酿了些，要不然早被我自己喝完啦！",
	["tid#RegionalText_248"]="的确是我的玉佩，大侠真是信人！不过……我还有一个不情之请……你问我醸了多少？100坛！哈哈哈！",
	["tid#RegionalText_249"]="这个东西，我想送给我的心上人，又怕太过唐突，不知道大侠能否代劳？这丫头就是手巧！也不知道以后便宜哪个小子。",
	["tid#RegionalText_250"]="又是那位公子……唉……嗯？这个香囊的确是我的……",
	["tid#RegionalText_251"]="辛苦这位侠士，不过如此重礼我无法收下，还请还给那位公子。唉，如果那个人也可以如此对我……但是因为被泥水弄脏，我已经不要了。",
	["tid#RegionalText_252"]="果然她还是不肯收下我的心意……窈窕淑女君子好逑，我不会轻易放弃的，明天还请大侠继续帮我！真是乡下村姑，香囊这东西，难道是可以洗的吗？",
	["tid#RegionalText_253"]="我也有个想要交给心上人的礼物，奈何不知道掉在哪里了，是一个我亲手做的香囊……不过乡村野花也别有一番风味，不如你我……",
	["tid#RegionalText_254"]="大侠您找谁？我爹爹出去喝酒了……你剥光了世家公子的一身行头并且把他绑在树上，扬长而去……",
	["tid#RegionalText_255"]="香囊？我爹爹好像提到捡到一个香囊，我看了一下绣工虽然不大好，但是用的是上好湖稠和金丝……他好像说要拿去换酒钱你觉得话不投机，挥手告辞。",
	["tid#RegionalText_256"]="啊？你是什么人？这是我的香囊！来了您呐？小店今天新上的货！您看看有没有中意的？",
	["tid#RegionalText_257"]="我就不能用绸子香囊了？你是不是瞧不起本地人啊！好嘞！您收好！",
	["tid#RegionalText_258"]="来人啊！外地人欺负人了！三子！狗剩！快来帮帮大叔我！没有您中意的？您有空常来！",
	["tid#RegionalText_259"]="哎呦……我这老胳膊老腿！拿走拿走！什么破玩意！真是晦气！我在村外设了陷阱，可以捕获小动物。如果有兴趣，你可以去看看试试运气。",
	["tid#RegionalText_260"]="感谢这位侠士……奈何被庸人弄脏的东西配不上那个人了……我再准备一个新的吧……据说这里有老虎出没，如果看到踪迹，我觉得你还是跑远点比较好。",
	["tid#RegionalText_261"]="这位施主，小僧有礼，不知道施主有没有兴趣和小僧打打机锋？我的陷阱好用吧？",
	["tid#RegionalText_262"]="小僧有三个佛经的问题，不知施主可以答对几个？怎么样？你要不要来一个？",
	["tid#RegionalText_263"]="若菩萨有我相、人相、众生相、寿者相……后面应为？好准头！这个彩头不错！它的鹿茸是你的了，剩下的你也带不走，我就处理了吧！",
	["tid#RegionalText_264"]="所谓佛法者……你顺着足迹查探，结果腥风扑面，迎面出现了一只老虎！",
	["tid#RegionalText_265"]="'是法平等，无有高下',是哪部经书所言？你错手不及，只好仓皇逃跑",
	["tid#RegionalText_266"]="所谓般若是指？你遇到老虎了？这畜生可不能力敌！最好结交一些擅长使用弓箭的朋友一起前往才有把握！",
	["tid#RegionalText_267"]="般若心经开篇是？你擅长弓箭的朋友先发制人，抬手一箭正中老虎眼窝，老虎应声倒地……",
	["tid#RegionalText_268"]="世人皆知“色不异空，空不异色，色即是空，空即是色”，之前一句是？喂！这老虎是我们先看到了！识相的就留下老虎赶快滚！",
	["tid#RegionalText_269"]="「一切有为法，如梦幻泡影，如露亦如电，应作如是观」来自哪部佛经？什么？你还想抵抗？兄弟们上啊！！",
	["tid#RegionalText_270"]="施主真是博学多才！小僧佩服！请明天也来和小僧研习佛法！不见不散！你居然能打到老虎！实在太厉害了！我来帮你加工一下，这个虎骨可以入药！",
	["tid#RegionalText_271"]="施主也是很有佛性了！对了，醉仙乡的大叔喜欢喝药酒，你把这个交给他女儿二丫，她最擅长处理这个！",
	["tid#RegionalText_272"]="附近有山贼滋扰相邻，贫僧有心降妖伏魔，又自觉功力不足难以以德服人……这是给我爹的？",
	["tid#RegionalText_273"]="如果施主有心，和小僧一同前往如何？你我联手，应当可以不伤人命化解事端。唉……我不想他喝酒，不过比起喝一些乱七八糟的，还不如喝点补身体的",
	["tid#RegionalText_274"]="多谢施主相助，小僧之后将对他们讲法一个时辰，然后将他们送交官服，施主若是不忙？不如一起？好了，请您拿好，如果我爹想喝了，您可以陪他喝几口。",
	["tid#RegionalText_275"]="施主一看就是好勇斗狠之辈，还请施主听小僧一言，放下屠刀立地成佛……这位同道请了。",
	["tid#RegionalText_276"]="明日还请施主来此和小僧说法，小僧愿为施主化解戾气我奉师命到此游历，但是这里江洋大盗云集……",
	["tid#RegionalText_277"]="这里贴的都是江洋大盗的通缉令，每个人都不好对付哦！有心杀贼，奈何势单力孤，不只能否看在同为江湖一脉助我一臂之力？",
	["tid#RegionalText_278"]="如果你想要赏钱，也要量力而为，不要阴沟里翻船了！甚好！那你我二人就前往南安镇看一看官服的悬赏吧！",
	["tid#RegionalText_279"]="这个是有名的飞贼，来无影去无踪，在本地已经做了很多案子这里贴的都是江洋大盗的通缉令，每个人都不好对付哦！",
	["tid#RegionalText_280"]="有人在城外看到过他，不过可别想着和他比轻功，你最好准备点暗器绳索之类的。如果你想要赏钱，也要量力而为，不要阴沟里翻船了！",
	["tid#RegionalText_281"]="哈哈！想追上我？别开玩笑了！这个是有名的飞贼，来无影去无踪，在本地已经做了很多案子",
	["tid#RegionalText_282"]="什么东西……你这家伙居然不讲江湖规矩！放开我！！！！有人在城外看到过他，不过可别想着和他比轻功，你最好准备点暗器绳索之类的。",
	["tid#RegionalText_283"]="哈哈哈！就凭你也想追上老子？再练十年吧……吧……吧……哈哈！想追上我？别开玩笑了！",
	["tid#RegionalText_284"]="哦！这家伙的确是草上飞，你居然能抓住？厉害厉害！什么东西……你这家伙居然不讲江湖规矩！放开我！！！！",
	["tid#RegionalText_285"]="这个混蛋是人人喊打的采花贼哈哈哈！就凭你也想追上老子？再练十年吧……吧……吧……",
	["tid#RegionalText_286"]="这个人善用各种迷药，没人知道他长什么样多亏这位同道准备充分，才没让他跑掉，我不敢居功！",
	["tid#RegionalText_287"]="恩？有事儿？这狗是干嘛的？我就和你说过了，这家伙轻功好，不要想着追得上他，下次做好准备再来吧！",
	["tid#RegionalText_288"]="啊！这破狗居然咬人！快阻止它！啊！我的手！这个混蛋是人人喊打的采花贼",
	["tid#RegionalText_289"]="你在闹市转悠了3天，茫茫人海，根本不知道谁是金毛鼠……这个人善用各种迷药，没人知道他长什么样",
	["tid#RegionalText_290"]="这家伙就是采花贼？哦！这是他用的迷药！你就是让狗追着气味……厉害厉害！！恩？有事儿？这狗是干嘛的？",
	["tid#RegionalText_291"]="这个人在山里啸聚，大兵赶到就逃跑，人少就聚众围攻，很难搞啊！这破狗居然咬人！快阻止它！啊！我的手！",
	["tid#RegionalText_292"]="我不是和你说过这个人连相貌都不知道吗，人海茫茫，你到哪里找去？想清楚方法再来吧！你在闹市转悠了3天，茫茫人海，根本不知道谁是金毛鼠……",
	["tid#RegionalText_293"]="这个人在山里啸聚，大兵赶到就逃跑，人少就聚众围攻，很难搞这家伙就是采花贼？哦！这是他用的迷药！你就是让狗追着气味……厉害厉害！！",
	["tid#RegionalText_294"]="出动官兵肯定不行了，你要是自己前往，做好对方人多势众的准备我不是和你说过这个人连相貌都不知道吗，人海茫茫，你到哪里找去？想清楚方法再来吧！",
	["tid#RegionalText_295"]="你是哪儿来的小子？也敢管老子的闲事？小的们给我上！这个人在山里啸聚，大兵赶到就逃跑，人少就聚众围攻，很难搞",
	["tid#RegionalText_296"]="有两手啊？再上去一拨人！这次别怕出人命！出动官兵肯定不行了，你要是自己前往，做好对方人多势众的准备",
	["tid#RegionalText_297"]="这么多人都对付不了？一帮废物！看我的！！你是哪儿来的小子？也敢管老子的闲事？小的们给我上！",
	["tid#RegionalText_298"]="你一个人就拿下了黑斧王？！厉害厉害！！！有两手啊？再上去一拨人！这次别怕出人命！",
	["tid#RegionalText_299"]="我这里有点东西想托人带给表哥，不知道您能不能帮忙？这么多人都对付不了？一帮废物！看我的！！",
	["tid#RegionalText_300"]="我这里有点东西想托人带给表哥，不知道您能不能帮忙？你们俩就拿下了黑斧王？！厉害厉害！！！",
	["tid#RegionalText_301"]="唉，说来就愁……这是给我爹准备的酒。哈哈！不过区区蟊贼，不足挂齿！",
	["tid#RegionalText_302"]="但是他一天到晚就知道在外面喝酒，我劝也不听，我真想不管他了……请问姑娘……（捡起一片红色丝巾）",
	["tid#RegionalText_303"]="他应该在村里的酒馆喝酒，能不能请您帮我交给他？你是怎么进来的？门口的……",
	["tid#RegionalText_304"]="对，就是这个，能不能麻烦您交给隔壁镇的捕快？他就在大门当值！他是我表哥，叫东柱。守卫吗？",
	["tid#RegionalText_305"]="这个……是之前一位公子在我这里讨水喝时掉下的。这里是武夷宫，我们在商量一件很重要的事情……",
	["tid#RegionalText_306"]="不知道他人在哪儿，我也没法还给他姑娘你的丝巾……",
	["tid#RegionalText_307"]="不知道您能不能帮我留意一下？诶？你是哪个门派派来的？",
	["tid#RegionalText_308"]="哦？这是我家闺女给我带的酒！一闻就知道，16年的女儿红！在下（玩家名），从蓬莱岛来，此番前来……",
	["tid#RegionalText_309"]="幸亏当年我多酿了些，要不然早被我自己喝完啦！蓬莱？就是那个武林圣地吗？你也是来拿武林秘籍的吗？",
	["tid#RegionalText_310"]="你问我醸了多少？100坛！哈哈哈！武林秘籍？你们说的很重要的事情，就是武林秘籍吗？",
	["tid#RegionalText_311"]="你问我醸了多少？100坛！哈哈哈！是啊，武夷山是道家圣地，纯阳的吕祖当年将一本旷世的武林秘籍藏在了这里。",
	["tid#RegionalText_312"]="这丫头就是手巧！也不知道以后便宜哪个小子。原来如此……",
	["tid#RegionalText_313"]="嗯？这个香囊的确是我的……姑娘也是来找武林秘籍的吗？",
	["tid#RegionalText_314"]="但是因为被泥水弄脏，我已经不要了。你是谁？这里很危险，你还是快点离开吧。",
	["tid#RegionalText_315"]="真是乡下村姑，香囊这东西，难道是可以洗的吗？为何？在下也十分好奇这武林秘籍呢。",
	["tid#RegionalText_316"]="不过乡村野花也别有一番风味，不如你我……马上要用晚宴了。你还是在晚宴前离开吧……",
	["tid#RegionalText_317"]="你剥光了世家公子的一身行头并且把他绑在树上，扬长而去……门口的守卫……看起来怪怪的。",
	["tid#RegionalText_318"]="你觉得话不投机，挥手告辞。这位少侠看来与我看法相同啊。",
	["tid#RegionalText_319"]="来了您呐？小店今天新上的货！您看看有没有中意的？什么？",
	["tid#RegionalText_320"]="好嘞！您收好！在下刚刚进入山门时也觉得这些守卫似乎心怀鬼胎的。",
	["tid#RegionalText_321"]="没有您中意的？您有空常来！是啊，哪有守卫胸前会带红丝巾的……",
	["tid#RegionalText_322"]="我在村外设了陷阱，可以捕获小动物。如果有兴趣，你可以去看看试试运气。阁下是纯阳……",
	["tid#RegionalText_323"]="据说这里有老虎出没，如果看到踪迹，我觉得你还是跑远点比较好。我再说一遍……我也不知道秘籍在哪，真的不知道……",
	["tid#RegionalText_324"]="我的陷阱好用吧？……？",
	["tid#RegionalText_325"]="怎么样？你要不要来一个？吕祖当年确实说过曾将一份宝藏藏在武夷山的道观里。",
	["tid#RegionalText_326"]="好准头！这个彩头不错！它的鹿茸是你的了，剩下的你也带不走，我就处理了吧！只是我辈均不知这宝藏究竟是何物，也不知究竟在哪。",
	["tid#RegionalText_327"]="你顺着足迹查探，结果腥风扑面，迎面出现了一只老虎！难道不是武林秘籍？",
	["tid#RegionalText_328"]="你错手不及，只好仓皇逃跑气氛有些不寻常。",
	["tid#RegionalText_329"]="你遇到老虎了？这畜生可不能力敌！最好结交一些擅长使用弓箭的朋友一起前往才有把握！慕容，没想到在这里又见面啦。你也对秘籍感兴趣吗？",
	["tid#RegionalText_330"]="唐门先发制人，抬手一发暗器正中老虎眼窝，老虎应声倒地……你怎么来了？",
	["tid#RegionalText_331"]="喂！这老虎是我们先看到了！识相的就留下老虎赶快滚！还好你来了，快跟我来， 大家很可能都非常危险。",
	["tid#RegionalText_332"]="什么？你还想抵抗？兄弟们上啊！！你在找什么？",
	["tid#RegionalText_333"]="你居然能打到老虎！实在太厉害了！我来帮你加工一下，这个虎骨可以入药！我认为这次大家聚集在这里……可能并不是什么好事。",
	["tid#RegionalText_334"]="对了，醉仙乡的大叔喜欢喝药酒，你把这个交给他女儿二丫，她最擅长处理这个！怎么，你发现什么线索么？",
	["tid#RegionalText_335"]="这是给我爹的？我找纯阳问过，他说也不知这宝藏的具体信息。",
	["tid#RegionalText_336"]="唉……我不想他喝酒，不过比起喝一些乱七八糟的，还不如喝点补身体的那么究竟是谁通知了大家？",
	["tid#RegionalText_337"]="好了，请您拿好，如果我爹想喝了，您可以陪他喝几口。醉翁之意不在酒，马上要到晚宴了。",
	["tid#RegionalText_338"]="这位同道请了。又是晚宴……",
	["tid#RegionalText_339"]="我奉师命到此游历，但是这里江洋大盗云集……怎么？",
	["tid#RegionalText_340"]="有心杀贼，奈何势单力孤，不只能否看在同为江湖一脉助我一臂之力？我觉得我们可以去后厨看一看。",
	["tid#RegionalText_341"]="甚好！那你我二人就前往南安镇看一看官服的悬赏吧！1、2、3、4，加上那个刚来的……这些剂量应该够了……",
	["tid#RegionalText_342"]="这里贴的都是江洋大盗的通缉令，每个人都不好对付哦！住手！你在干什么？",
	["tid#RegionalText_343"]="如果你想要赏钱，也要量力而为，不要阴沟里翻船了！她好像往饭菜中放了什么。",
	["tid#RegionalText_344"]="这个是有名的飞贼，来无影去无踪，在本地已经做了很多案子不好！被发现了。快逃。",
	["tid#RegionalText_345"]="有人在城外看到过他，不过可别想着和他比轻功，你最好准备点暗器绳索之类的。别走！",
	["tid#RegionalText_346"]="哈哈！想追上我？别开玩笑了！难道她在下毒？那之前她跟我说在晚宴前离开……",
	["tid#RegionalText_347"]="什么东西……你这家伙居然不讲江湖规矩！放开我！！！！怎么突然来了这么多匪徒？等等……他们的穿着跟山门的守卫一样！",
	["tid#RegionalText_348"]="哈哈哈！就凭你也想追上老子？再练十年吧……吧……吧……名剑和花间他们全部都昏迷了！",
	["tid#RegionalText_349"]="多亏这位同道准备充分，才没让他跑掉，我不敢居功！五毒！这些都是你叫来的人吗？",
	["tid#RegionalText_350"]="我就和你说过了，这家伙轻功好，不要想着追得上他，下次做好准备再来吧！果然有埋伏！究竟谁是那个人呢？",
	["tid#RegionalText_351"]="这个混蛋是人人喊打的采花贼他们打过来了！",
	["tid#RegionalText_352"]="这个人善用各种迷药，没人知道他长什么样这群匪徒的身上都挂了红丝巾……",
	["tid#RegionalText_353"]="恩？有事儿？这狗是干嘛的？果然是你！你究竟想干什么？",
	["tid#RegionalText_354"]="啊！这破狗居然咬人！快阻止它！啊！我的手！刚才就发现，大家都中毒了只有明教你不在。",
	["tid#RegionalText_355"]="你在闹市转悠了3天，茫茫人海，根本不知道谁是金毛鼠……还有那些红丝巾……",
	["tid#RegionalText_356"]="这家伙就是采花贼？哦！这是他用的迷药！你就是让狗追着气味……厉害厉害！！我刚刚不是在下毒，我只是放了一些药，让大家假死过去。",
	["tid#RegionalText_357"]="我不是和你说过这个人连相貌都不知道吗，人海茫茫，你到哪里找去？想清楚方法再来吧！这样就可以引出真正的始作俑者。",
	["tid#RegionalText_358"]="这个人在山里啸聚，大兵赶到就逃跑，人少就聚众围攻，很难搞明教，说吧，你打的什么算盘？",
	["tid#RegionalText_359"]="出动官兵肯定不行了，你要是自己前往，做好对方人多势众的准备没什么可说的，看刀！",
	["tid#RegionalText_360"]="你是哪儿来的小子？也敢管老子的闲事？小的们给我上！大家果然都醒来了。明教，你如何面对大家！",
	["tid#RegionalText_361"]="有两手啊？再上去一拨人！这次别怕出人命！这……怎么回事儿？",
	["tid#RegionalText_362"]="这么多人都对付不了？一帮废物！看我的！！发生了……什么？",
	["tid#RegionalText_363"]="你们俩就拿下了黑斧王？！厉害厉害！！！头好昏啊。",
	["tid#RegionalText_364"]="哈哈！不过区区蟊贼，不足挂齿！如果我没猜错的话，明教，是你将武夷宫内有秘籍的消息发散给大家的吧？",
	["tid#RegionalText_365"]="请问姑娘……（捡起一片红色丝巾）呵，不错，只是没想到就连纯阳都不知道这宝藏在哪。",
	["tid#RegionalText_366"]="你是怎么进来的？门口的……本想诈出宝藏地点后和纯阳单挑的。",
	["tid#RegionalText_367"]="守卫吗？和我？何出此言？",
	["tid#RegionalText_368"]="这里是武夷宫，我们在商量一件很重要的事情……纯阳说这宝藏也不一定是秘籍啊。你要来干嘛呢？",
	["tid#RegionalText_369"]="姑娘你的丝巾……今日我方势力在中原见风起势，听闻丐帮即将联合纯阳对抗我方势力",
	["tid#RegionalText_370"]="诶？你是哪个门派派来的？此番我本想以吕祖宝藏要挟纯阳不要参战，没想到……",
	["tid#RegionalText_371"]="在下（玩家名），从蓬莱岛来，此番前来……我纯阳祖上有讯，誓不可参战左右局势，切记保持中立。",
	["tid#RegionalText_372"]="蓬莱？就是那个武林圣地吗？你也是来拿武林秘籍的吗？所以更不会和谁联合，也不会对抗谁。",
	["tid#RegionalText_373"]="武林秘籍？你们说的很重要的事情，就是武林秘籍吗？诶？你们看这是什么？",
	["tid#RegionalText_374"]="是啊，武夷山是道家圣地，纯阳的吕祖当年将一本旷世的武林秘籍藏在了这里。一本食谱？",
	["tid#RegionalText_375"]="原来如此……是《上清豆腐》！",
	["tid#RegionalText_376"]="姑娘也是来找武林秘籍的吗？《上清豆腐》？",
	["tid#RegionalText_377"]="你是谁？这里很危险，你还是快点离开吧。是据说吕祖时期的神秘食谱，用豆腐可以做出山珍一般的味道！竟然在这里找到！",
	["tid#RegionalText_378"]="为何？在下也十分好奇这武林秘籍呢。什么？宝藏竟然是一本食谱？",
	["tid#RegionalText_379"]="马上要用晚宴了。你还是在晚宴前离开吧……有这个可能，道家中人有食戒，于是素菜的山珍般使用方法也算是一种宝藏了。",
	["tid#RegionalText_380"]="门口的守卫……看起来怪怪的。明教是想要这个吗？可以给你。",
	["tid#RegionalText_381"]="这位少侠看来与我看法相同啊。你自己留着吧……",
	["tid#RegionalText_382"]="什么？散了散了……",
	["tid#RegionalText_383"]="在下刚刚进入山门时也觉得这些守卫似乎心怀鬼胎的。来者何人！",
	["tid#RegionalText_384"]="是啊，哪有守卫胸前会带红丝巾的……请问这里可是武夷宫？",
	["tid#RegionalText_385"]="阁下是纯阳……确是武夷宫没错，你是何人，为何来此？",
	["tid#RegionalText_386"]="我再说一遍……我也不知道秘籍在哪，真的不知道……大哥，圣女……老大她说不能放任何人进去。",
	["tid#RegionalText_387"]="……？任何人？这是为何？武夷宫因何不接客？",
	["tid#RegionalText_388"]="吕祖当年确实说过曾将一份宝藏藏在武夷山的道观里。江湖上的几大前辈都在武夷宫中切磋武艺，岂是你这种无名鼠辈可以随意观瞧的。",
	["tid#RegionalText_389"]="只是我辈均不知这宝藏究竟是何物，也不知究竟在哪。你还是哪儿来的回哪儿去吧。",
	["tid#RegionalText_390"]="难道不是武林秘籍？对啊，不然你进去也是送死。",
	["tid#RegionalText_391"]="气氛有些不寻常。那我倒是想见识见识呢。",
	["tid#RegionalText_392"]="慕容，没想到在这里又见面啦。你也对秘籍感兴趣吗？不自量力！",
	["tid#RegionalText_393"]="你怎么来了？",
	["tid#RegionalText_394"]="还好你来了，快跟我来， 大家很可能都非常危险。",
	["tid#RegionalText_395"]="你在找什么？",
	["tid#RegionalText_396"]="我认为这次大家聚集在这里……可能并不是什么好事。",
	["tid#RegionalText_397"]="怎么，你发现什么线索么？",
	["tid#RegionalText_398"]="我找纯阳问过，他说也不知这宝藏的具体信息。",
	["tid#RegionalText_399"]="那么究竟是谁通知了大家？",
	["tid#RegionalText_400"]="醉翁之意不在酒，马上要到晚宴了。",
	["tid#RegionalText_401"]="又是晚宴……",
	["tid#RegionalText_402"]="怎么？",
	["tid#RegionalText_403"]="我觉得我们可以去后厨看一看。",
	["tid#RegionalText_404"]="1、2、3、4，加上那个刚来的……这些剂量应该够了……",
	["tid#RegionalText_405"]="住手！你在干什么？",
	["tid#RegionalText_406"]="她好像往饭菜中放了什么。",
	["tid#RegionalText_407"]="不好！被发现了。快逃。",
	["tid#RegionalText_408"]="别走！",
	["tid#RegionalText_409"]="难道她在下毒？那之前她跟我说在晚宴前离开……",
	["tid#RegionalText_410"]="怎么突然来了这么多匪徒？等等……他们的穿着跟山门的守卫一样！",
	["tid#RegionalText_411"]="名剑和花间他们全部都昏迷了！",
	["tid#RegionalText_412"]="五毒！这些都是你叫来的人吗？",
	["tid#RegionalText_413"]="果然有埋伏！究竟谁是那个人呢？",
	["tid#RegionalText_414"]="他们打过来了！",
	["tid#RegionalText_415"]="这群匪徒的身上都挂了红丝巾……",
	["tid#RegionalText_416"]="果然是你！你究竟想干什么？",
	["tid#RegionalText_417"]="刚才就发现，大家都中毒了只有明教你不在。",
	["tid#RegionalText_418"]="还有那些红丝巾……",
	["tid#RegionalText_419"]="我刚刚不是在下毒，我只是放了一些药，让大家假死过去。",
	["tid#RegionalText_420"]="这样就可以引出真正的始作俑者。",
	["tid#RegionalText_421"]="明教，说吧，你打的什么算盘？",
	["tid#RegionalText_422"]="没什么可说的，看刀！",
	["tid#RegionalText_423"]="大家果然都醒来了。明教，你如何面对大家！",
	["tid#RegionalText_424"]="这……怎么回事儿？",
	["tid#RegionalText_425"]="发生了……什么？",
	["tid#RegionalText_426"]="头好昏啊。",
	["tid#RegionalText_427"]="如果我没猜错的话，明教，是你将武夷宫内有秘籍的消息发散给大家的吧？",
	["tid#RegionalText_428"]="呵，不错，只是没想到就连纯阳都不知道这宝藏在哪。",
	["tid#RegionalText_429"]="本想诈出宝藏地点后和纯阳单挑的。",
	["tid#RegionalText_430"]="和我？何出此言？",
	["tid#RegionalText_431"]="纯阳说这宝藏也不一定是秘籍啊。你要来干嘛呢？",
	["tid#RegionalText_432"]="今日我方势力在中原见风起势，听闻丐帮即将联合纯阳对抗我方势力",
	["tid#RegionalText_433"]="此番我本想以吕祖宝藏要挟纯阳不要参战，没想到……",
	["tid#RegionalText_434"]="我纯阳祖上有讯，誓不可参战左右局势，切记保持中立。",
	["tid#RegionalText_435"]="所以更不会和谁联合，也不会对抗谁。",
	["tid#RegionalText_436"]="诶？你们看这是什么？",
	["tid#RegionalText_437"]="一本食谱？",
	["tid#RegionalText_438"]="是《上清豆腐》！",
	["tid#RegionalText_439"]="《上清豆腐》？",
	["tid#RegionalText_440"]="是据说吕祖时期的神秘食谱，用豆腐可以做出山珍一般的味道！竟然在这里找到！",
	["tid#RegionalText_441"]="什么？宝藏竟然是一本食谱？",
	["tid#RegionalText_442"]="有这个可能，道家中人有食戒，于是素菜的山珍般使用方法也算是一种宝藏了。",
	["tid#RegionalText_443"]="明教是想要这个吗？可以给你。",
	["tid#RegionalText_444"]="你自己留着吧……",
	["tid#RegionalText_445"]="散了散了……",
	["tid#RegionalText_446"]="来者何人！",
	["tid#RegionalText_447"]="请问这里可是武夷宫？",
	["tid#RegionalText_448"]="确是武夷宫没错，你是何人，为何来此？",
	["tid#RegionalText_449"]="大哥，圣女……老大她说不能放任何人进去。",
	["tid#RegionalText_450"]="任何人？这是为何？武夷宫因何不接客？",
	["tid#RegionalText_451"]="江湖上的几大前辈都在武夷宫中切磋武艺，岂是你这种无名鼠辈可以随意观瞧的。",
	["tid#RegionalText_452"]="你还是哪儿来的回哪儿去吧。",
	["tid#RegionalText_453"]="对啊，不然你进去也是送死。",
	["tid#RegionalText_454"]="那我倒是想见识见识呢。",
	["tid#RegionalText_455"]="不自量力！",
	["tid#RegionalText_456"]="年轻人，你知道世上最好的酒是什么吗？",
	["tid#RegionalText_457"]="唉，长了这么大，居然还不知道酒的滋味？你走吧！我们没什么好聊的！",
	["tid#RegionalText_458"]="哦？你有酒？拿出来看看！",
	["tid#RegionalText_459"]="恩……成色一般啊，勉强可以入口，来，这点东西你收下吧！",
	["tid#RegionalText_460"]="哦？你有虎骨酒？拿出来拿出来！",
	["tid#RegionalText_461"]="哈哈！这是我女儿的手艺啊！真是乖丫头！来来来，你也喝点！",
	["tid#RegionalText_462"]="这个酒真甚合我意！这些东西你收下吧！",
	["tid#RegionalText_463"]="来者何人？天王盖地虎？",
	["tid#RegionalText_464"]="看来你是正派弟子，可是接到前来拜会本地长老？",
	["tid#RegionalText_465"]="最近有很多江湖豪客到达本地，总有作奸犯科之辈，已经和我帮弟子有多次冲突，所以我还以为你也是意图不轨之人。",
	["tid#RegionalText_466"]="嗯？外面是什么声音？有敌人来袭！",
	["tid#RegionalText_467"]="哈哈！这就是乞丐窝！居然挡爷爷们的财路！兄弟们，上！端了这个乞丐窝之后咱们就随便快活了！",
	["tid#RegionalText_468"]="贼子！这位大侠，还请援手相助！",
	["tid#RegionalText_469"]="嗯？有点本事，兄弟们再上！",
	["tid#RegionalText_470"]="怎么回事儿？！这么厉害！？一起上一起上！！",
	["tid#RegionalText_471"]="多谢这位大侠相助！如果没有你后果真是不堪设想！这是在下一点心意！以后我们还要多走动走动！",
	["tid#RegionalText_472"]="这位大侠请了，相比您是来拜访本地长老的吧？请随我来。",
	["tid#RegionalText_473"]="丐帮弟子要引荐你拜见本地长老，但是越走越偏僻……",
	["tid#RegionalText_474"]="好贼子！还敢送上门来！兄弟们一起上！！",
	["tid#RegionalText_475"]="好贼子！仗着艺业惊人就敢欺上门来！我丐帮上下绝不投降！",
	["tid#RegionalText_476"]="恩？你说什么？你只是路过？",
	["tid#RegionalText_477"]="……行走江湖……切莫乱对切口啊！这是天大的误会！",
	["tid#RegionalText_478"]="关关雎鸠在河之洲……窈窕淑女君子好逑……",
	["tid#RegionalText_479"]="我本将心向明月……奈何明月照沟渠……",
	["tid#RegionalText_480"]="阿弥陀佛，我佛慈悲……",
	["tid#RegionalText_481"]="您好啊大侠！今天也是好天气呢！",
	["tid#RegionalText_482"]="世人皆醉我独醒……嗯？世人皆醒我独醉？哈哈哈哈！再来一杯！",
	["tid#RegionalText_483"]="天干物燥，小心火烛！",
	["tid#RegionalText_484"]="来了客官？现在没有您感兴趣的货物，您改日再来？",
	["tid#RegionalText_485"]="江湖险恶，我会小心行事的。",
	["tid#RegionalText_486"]="小心！别裁到我布下的陷阱！",
	["tid#RegionalText_487"]="这位爷，请好心赏几个钱吧！",
	["tid#RegionalText_488"]="欢迎来到侠隐村，正巧老朽正在煮茶，要不要来一杯",
	["tid#RegionalText_489"]="村长好，我进来时闻到你们村里茶香满村不知原因是什么",
	["tid#RegionalText_490"]="哈哈哈……老朽这茶是用村子的井水所泡，但是不知为何最近水变得不那么甜了，正好少侠来了，帮我调查一二",
	["tid#RegionalText_491"]="老板你家的茶好香啊，不知是为何啊",
	["tid#RegionalText_492"]="我们这里的茶都是用村中井水泡制的，但是不知道为什么最近水没有以前那么甘甜了，可以问问其他村民是不是也这么觉得",
	["tid#RegionalText_493"]="那在下出去看看",
	["tid#RegionalText_494"]="辛苦少侠",
	["tid#RegionalText_495"]="最近喝水的时候觉得没有以前甘甜了",
	["tid#RegionalText_496"]="最近做的米饭也没有以前香了",
	["tid#RegionalText_497"]="最近炖的汤也没有以前香了",
	["tid#RegionalText_498"]="既然少侠都知道了请帮老朽去调查吧",
	["tid#RegionalText_499"]="谁！",
	["tid#RegionalText_500"]="你是何人，光天化日鬼鬼祟祟",
	["tid#RegionalText_501"]="少侠所见可能是灵玉，村子里一直有灵玉的传说没想到时真的，传说灵玉是龙神脱落的龙角所化……",
	["tid#RegionalText_502"]="多谢少侠帮我们解决井水不甜的问题",
	["tid#RegionalText_503"]="多谢夸奖，愧不敢当",
	["tid#RegionalText_504"]="这些谢礼请少侠务必收下",
	["tid#RegionalText_505"]="最近喝水的时候觉得没有以前甘甜了",
	["tid#RegionalText_506"]="最近做的米饭也没有以前香了",
	["tid#RegionalText_507"]="最近村子水的问题大家都在讨论，但是前面村里来了一个商人见多识广可以去问问看",
	["tid#RegionalText_508"]="请问少侠找老朽有什么事",
	["tid#RegionalText_509"]="老人家见多识广对现在村子里的水不甜有什么见解",
	["tid#RegionalText_510"]="老朽这里有个一甜石，放于水中即可让水甘甜，这就送于你",
	["tid#RegionalText_511"]="多谢少侠帮村子井水恢复甘甜",
	["tid#RegionalText_512"]="少侠今日村子里的井水又不甜了，你再去帮我们看看",
	["tid#RegionalText_513"]="老朽的甜石不是无限的，这次少侠需要给老朽1000金才能把甜石给你",
	["tid#RegionalText_514"]="你这个骗子，村子不欢迎你",
	["tid#RegionalText_515"]="欢迎来到侠隐村！这里山清水秀，四季如春。有好喝的山泉、井水，和淳朴的村民。祝你在这里玩的愉快！",
	["tid#RegionalText_516"]="队伍中有擅长游泳的侠客帮助你进入水底发现了机关，你打开机关进入了一间密室",
	["tid#RegionalText_517"]="队伍中有擅长制作火药的侠客帮助你炸开了上锁的门，你进入了一间密室",
	["tid#RegionalText_518"]="井水的事大家都怎么说？",
	["tid#RegionalText_519"]="这里居然有人",
	["tid#RegionalText_520"]="谁！",
	["tid#RegionalText_521"]="黑影在你面前一闪",
	["tid#RegionalText_522"]="这里的宝物必然是被这个人偷走的，快去找村长",
	["tid#RegionalText_523"]="你眼前一黑失去意识",
	["tid#RegionalText_524"]="哟少侠你醒了",
	["tid#RegionalText_525"]="发生了什么我怎么晕倒了",
	["tid#RegionalText_526"]="昨天我看到你昏倒在门口就把你救了进来",
	["tid#RegionalText_527"]="突然想起来昨天有人偷袭我，是我学艺不精被他打晕了",
	["tid#RegionalText_528"]="今日就不谢谢少侠了，自便吧",
	["tid#RegionalText_529"]="好小子竟有些手段，今日不便再战，有缘再见",
	["tid#RegionalText_530"]="贼子别跑，你把话说清楚",
	["tid#RegionalText_531"]="哈哈，小子你能留下我再说吧",
	["tid#RegionalText_532"]="可恶让他跑了，得赶紧告诉村长去",
	["tid#RegionalText_533"]="糟糕有机关",
	["tid#RegionalText_534"]="这是一口神奇的井这口井的水好像和普通的不一样，尝过的人都说甜，最近这口井有些奇怪。",
	["tid#RegionalText_535"]="一扇带锁的铁门，打开需要有破坏技能的侠客",
	["tid#RegionalText_536"]="有机关的门，看起来要懂得机关的人才能打开",
	["tid#RegionalText_537"]="咳咳……你居然用蛊",
	["tid#RegionalText_538"]="你身受重伤昏迷过去",
	["tid#RegionalText_539"]="一个空宝箱，里面衬底有一个环形凹槽，看起来是常年存放宝物所用",
	["tid#RegionalText_540"]="你身中机关昏迷不醒",
	["tid#RegionalText_541"]="突然想起来昨日在密室内中了机关，待我修养好了再去探探",
	["tid#RegionalText_542"]="哎！年轻人！年轻人！",
	["tid#RegionalText_543"]="叫我吗，村长。",
	["tid#RegionalText_544"]="年轻人，相信你已经对侠隐村有所了解了。",
	["tid#RegionalText_545"]="但是最近村子里发生了一些变化。",
	["tid#RegionalText_546"]="村中的井水原本是甘甜如饴，最近却离奇的失去了甜味。",
	["tid#RegionalText_547"]="是指村中那口井吗？",
	["tid#RegionalText_548"]="是的。可以打一点水，去问一下卖茶的先生。",
	["tid#RegionalText_549"]="老板，来碗茶。",
	["tid#RegionalText_550"]="好嘞。哟呵，客观还带着水来喝茶呀。",
	["tid#RegionalText_551"]="是这样的，村长说村子里的水似乎变得不如以前了。",
	["tid#RegionalText_552"]="你带来的就是最近的井水吗。让我来尝尝……",
	["tid#RegionalText_553"]="……",
	["tid#RegionalText_554"]="确实如此，这井水变得像普通井水一样了。",
	["tid#RegionalText_555"]="那老板知道井水如何才能恢复以往甘甜的味道呢？",
	["tid#RegionalText_556"]="茶馆中恰巧有一位老学究在喝茶，少侠可以前往询问。",
	["tid#RegionalText_557"]="哎，好茶是好茶，终究是水辜负了茶呀。",
	["tid#RegionalText_558"]="老先生，您好，可否请教您一点事儿？这水……",
	["tid#RegionalText_559"]="年轻人，这侠隐村的甜水井可是另有玄机的。只是最近来了一群土匪，破坏了其中机关。",
	["tid#RegionalText_560"]="这机关则是放在井水当中的西域夜光珠。这夜光珠能散发微微的甘甜味道。",
	["tid#RegionalText_561"]="原来如此，我知道该怎么做了。",
	["tid#RegionalText_562"]="村长，我已经将井中的小秘密完璧归赵了。",
	["tid#RegionalText_563"]="年轻有为啊！我已经听到村民们讨论再次变得甘甜的井水。",
	["tid#RegionalText_564"]="感谢你年轻人，不过希望这个小秘密，你可要对外保密哦。",
	["tid#RegionalText_565"]="哪里哪里。好的我会保密的。",
	["tid#RegionalText_566"]="这是给你的奖励。",
	["tid#RegionalText_567"]="什么人！坏我好事！",
	["tid#RegionalText_568"]="你手里拿的什么！",
	["tid#RegionalText_569"]="哈哈，不知道吧，这可是甜水井的秘密。",
	["tid#RegionalText_570"]="获得了这块西域夜光珠！我就能发财啦！！",
	["tid#RegionalText_571"]="不好！他要逃走了，快追上他抢回西域夜光珠！",
	["tid#RegionalText_572"]="可恶！竟然被打败了！",
	["tid#RegionalText_573"]="这就是甜玉吗，作为一位大侠我当然要将这宝物，物归原主！",
	["tid#RegionalText_574"]="少得意！我还会回来的！",
	["tid#RegionalText_575"]="你回来了，少侠在井下发现了什么？",
	["tid#RegionalText_576"]="是甜玉！原来是有人在西域夜光珠上动了手脚。这夜光珠能散发微微的甘甜味道。",
	["tid#RegionalText_577"]="所以水才会变得甘甜，这下侠隐村的井又可以是甜水井了。",
	["tid#RegionalText_578"]="太好了。感谢你，年轻人，真是年少有为，这是给你的奖励。",
	["tid#RegionalText_579"]="村长，我在井下的密室当中发现一个神秘的台子。只是……",
	["tid#RegionalText_580"]="只是这台子上原本的物件不见了是吗？",
	["tid#RegionalText_581"]="正是！",
	["tid#RegionalText_582"]="果然……这就是井水不再甘甜的原因。",
	["tid#RegionalText_583"]="这遗失的物件是西域的夜光珠，这夜光珠可以散发出甘甜的味道，这就是井水甘甜的源泉。",
	["tid#RegionalText_584"]="原来如此。",
	["tid#RegionalText_585"]="你舞剑的姿势无比精准，即使最严厉的长老也挑不出毛病，但你仍不满意现况",
	["tid#RegionalText_586"]="一套碧海裂涛掌被你打的虎虎生风，已经很难有什么提升了",
	["tid#RegionalText_587"]="你运行真气走过一个又一个大周天，内功的瓶颈丝毫没有松动",
	["tid#RegionalText_588"]="一个样式普通的箱子",
	["tid#RegionalText_589"]="少爷，这么早就起来了，要准备晨练了么？",
	["tid#RegionalText_590"]="逆水行舟，不进则退。武功修行一旦落下，再捡起来就难了。",
	["tid#RegionalText_591"]="嗯？方伯，我平时练功的铁剑你看到了么？",
	["tid#RegionalText_592"]="昨天二丫打扫院子来着，怕不是这丫头给收到哪里去了。",
	["tid#RegionalText_593"]="二丫，你看到我平时练功用的铁剑了么。",
	["tid#RegionalText_594"]="唔……少爷的铁剑……",
	["tid#RegionalText_595"]="啊！我想起来了！昨天少爷练完功，二丫帮你收起来了，应该在厢房的箱子里，我这就去拿！",
	["tid#RegionalText_596"]="无妨，我自己去就好。",
	["tid#RegionalText_597"]="少爷为何满脸忧色？",
	["tid#RegionalText_598"]="近日我练功不辍，但功力没有丝毫精进，隐隐还有倒退的迹象。",
	["tid#RegionalText_599"]="少爷，你这是到瓶颈了。你终日在山庄中，不问世事，如此练功不但无益，还有走火入魔的危险。",
	["tid#RegionalText_600"]="方伯意思是……我应该下山去历练一番？",
	["tid#RegionalText_601"]="老爷曾嘱咐过，若有一天少爷遇到瓶颈，可去后山寻一古剑，取得后便可下山闯荡江湖。",
	["tid#RegionalText_602"]="后山，古剑……我明白了。",
	["tid#RegionalText_603"]="虽在山庄居住已久，却从未来过这后山。",
	["tid#RegionalText_604"]="父亲，难道你给我留下了什么考验么？",
	["tid#RegionalText_605"]="这真是一把好剑，咦，上面还有刻字……",
	["tid#RegionalText_606"]="路行万里，义名远扬。",
	["tid#RegionalText_607"]="方伯，父亲所说古剑，可是我手上这把？",
	["tid#RegionalText_608"]="嗯，不错，这把义侠剑正是老爷第一次闯荡江湖时的佩剑。",
	["tid#RegionalText_609"]="老爷还嘱咐我一句话，我辈武功高低固然重要，但智慧有时比刀剑更有用。",
	["tid#RegionalText_610"]="方伯，我记住了",
	["tid#RegionalText_611"]="少爷，准备好就下山去吧。",
	["tid#RegionalText_612"]="看这位大哥面色凝重，是村子附近遭遇了什么祸患吗？",
	["tid#RegionalText_613"]="小兄弟是刚来到我们稻香村的吧。",
	["tid#RegionalText_614"]="没错。",
	["tid#RegionalText_615"]="那小兄弟最近可得多留个心眼儿了，我们这里啊，正在闹狼灾，凶的狠呐！",
	["tid#RegionalText_616"]="嗯，多谢大哥提醒！",
	["tid#RegionalText_617"]="这位大嫂，我路过贵村，腹中实在有些饥饿，不知道能不能讨要一碗饭食？",
	["tid#RegionalText_618"]="抱歉啊小兄弟，问问别人吧，我正在找孩子，家里没有做饭。",
	["tid#RegionalText_619"]="这位先生，我路过贵村，想讨一碗饭食，主要是村子里也没看到有饭馆。",
	["tid#RegionalText_620"]="瞧你人模人样的，不去干点儿正事儿，跑来这里行骗？快走开！",
	["tid#RegionalText_621"]="这位婆婆，我路过贵村，肚子有些饿，是否…？",
	["tid#RegionalText_622"]="抱歉呀孩子，婆婆年纪大了，儿女又不在身边，家里的米也只够婆婆一个人吃了。",
	["tid#RegionalText_623"]="这位老先生，我路过贵村，想讨一碗饭食，不知道可否？我可以付钱的。",
	["tid#RegionalText_624"]="哈哈，不用付钱，只是一顿饭而已。",
	["tid#RegionalText_625"]="欢迎来到我们稻香村，我是这个村子的村长，村子最近有些不太平，招待不周，还请少侠见谅。",
	["tid#RegionalText_626"]="村长您太客气了。",
	["tid#RegionalText_627"]="看我这一见到外人就有些激动，少侠快快进屋，我们边吃边说。",
	["tid#RegionalText_628"]="实在是太感谢村长您的款待了。",
	["tid#RegionalText_629"]="多个人多添双筷子而已，只是粗茶淡饭，还怕怠慢了少侠。",
	["tid#RegionalText_630"]="哪有的事，话说刚来时，听人说村子附近正在闹狼患？",
	["tid#RegionalText_631"]="不瞒少侠，正是如此，而且这狼群近来愈加凶狠起来。",
	["tid#RegionalText_632"]="村里牛羊丢了不知道多少，连人也伤了好多起了，也没别的办法，只好组织一些村里的青壮轮番看护着。",
	["tid#RegionalText_633"]="原来如此。",
	["tid#RegionalText_634"]="村长！村长！快救救我家铁蛋吧！村子里上上下下我都找遍了，就是找不到，说不定是被狼给叼走了！",
	["tid#RegionalText_635"]="什么！村口不是有大胆看着吗，如果有狼的话，他一定会跟大家警示的。",
	["tid#RegionalText_636"]="村长！求求您想想办法吧，铁蛋要是没了，我可怎么活啊，呜呜呜……",
	["tid#RegionalText_637"]="米嫂你先别着急，铁蛋这孩子调皮，极有可能并非是被狼叼走了，我这就张罗大伙帮你找找。",
	["tid#RegionalText_638"]="这事儿我也一起帮忙，就当是报答村长的一饭之恩了。",
	["tid#RegionalText_639"]="好，那就多谢少侠仗义相助！",
	["tid#RegionalText_640"]="一个奇怪的机关，顶端刻着一个木字。",
	["tid#RegionalText_641"]="一个奇怪的机关，【水】已经点亮。",
	["tid#RegionalText_642"]="一个奇怪的机关，【水】【火】已经点亮。",
	["tid#RegionalText_643"]="一个奇怪的机关，【水】【火】【金】已经被点亮。",
	["tid#RegionalText_644"]="仔细检查已经获得的物品。",
	["tid#RegionalText_645"]="看起来是一个宁谧的小村庄，临近大概有四、五户人家，如今腹中颇有些饥饿，不如试着向这里的村民讨一碗饭食。",
	["tid#RegionalText_646"]="机关发出轻微闭合的声音。",
	["tid#RegionalText_647"]="一个暗箱出现，里面似乎有东西。",
	["tid#RegionalText_648"]="一张奇怪的字条，上面写着：金→木→水→火→金。",
	["tid#RegionalText_649"]="咔的一声，机关恢复了最初的样子。",
	["tid#RegionalText_650"]="一些装满水的陶罐。",
	["tid#RegionalText_651"]="一个小本子，上面画满了涂鸦。",
	["tid#RegionalText_652"]="长度略短的木剑，有些地方已经开裂了。",
	["tid#RegionalText_653"]="新鲜的泥土上有几个小小脚印，看上去像是小孩子留下的。",
	["tid#RegionalText_654"]="正对着洞口有个损毁的石门。",
	["tid#RegionalText_655"]="石墙下有个不大的小洞，小孩子应该能钻进去。",
	["tid#RegionalText_656"]="墙壁上有刀剑砍过的痕迹。",
	["tid#RegionalText_657"]="阴暗的角落里，也许有什么东西。",
	["tid#RegionalText_658"]="样式古老的罐子。",
	["tid#RegionalText_659"]="一个空箱子，样子古朴，但看上去有些奇怪。",
	["tid#RegionalText_660"]="你隐约似乎听到了一些声音。",
	["tid#RegionalText_661"]="放在神龛前的香炉，香炉里有许多香灰。",
	["tid#RegionalText_662"]="一扇被堵死的门，大量泥土把门缝都堵住了。",
	["tid#RegionalText_663"]="一张掉落的地图，看着像是铁蛋画的。",
	["tid#RegionalText_664"]="一位抚琴坐化的前辈，不知他生前发生了什么事。",
	["tid#RegionalText_665"]="结实的箱子，但是已经被外力破坏了。",
	["tid#RegionalText_666"]="字迹工整的纸条。",
	["tid#RegionalText_667"]="少侠不要急，有事慢慢和我说。",
	["tid#RegionalText_668"]="你检查了一会，但这些都是家常的东西，一无所获。",
	["tid#RegionalText_669"]="这里面有很多练习时写的歪扭的字，还有一些看不懂的涂鸦。",
	["tid#RegionalText_670"]="这也许是铁蛋的玩具，他也有个大侠梦么？",
	["tid#RegionalText_671"]="强大的内力击碎了破损的墙壁，一条通路出现在眼前。",
	["tid#RegionalText_672"]="这里曾经发生过激烈的战斗，而且造成这些伤痕的一定是神兵利器",
	["tid#RegionalText_673"]="随着一声轻响，箱底的隔层被打开，一本秘籍出现在眼前。",
	["tid#RegionalText_674"]="呜呜呜，呜呜呜呜；有小孩子的声音！在哪边？",
	["tid#RegionalText_675"]="在香灰里，有什么东西在发光，你翻查之后发现那竟然是一把钥匙。",
	["tid#RegionalText_676"]="里面是一个废弃仓库，经过翻找你拿走了唯一能用的东西。",
	["tid#RegionalText_677"]="在你收拾前辈尸骨的时候，其身下的蒲团里调出了一本书籍和一张字条。",
	["tid#RegionalText_678"]="箱子还有些值钱的东西，似乎是之前来过的人不屑于带走",
	["tid#RegionalText_679"]="老夫神龙教教主莫问天，遭武林盟暗算藏身于此，身受重伤命不久矣。",
	["tid#RegionalText_680"]="王大哥，请问这几天村子是否有狼出现的痕迹？",
	["tid#RegionalText_681"]="小兄弟，你王大哥跟你打包票，村子里最近绝对没有狼进来，村里的鸡鸭和其他牲口可一点儿都没丢。",
	["tid#RegionalText_682"]="说句不中听的话，虽说那些畜生歹毒，但是也知道叼走鸡鸭要比叼走一个半大的孩子要容易的多。",
	["tid#RegionalText_683"]="而且你王大哥绝对是时时刻刻盯着，一点儿没松懈！",
	["tid#RegionalText_684"]="嗯，我相信你。",
	["tid#RegionalText_685"]="米嫂，您知道铁蛋平时都爱去什么地方吗，都喜欢玩些什么呢？",
	["tid#RegionalText_686"]="别提了，少侠，我们家铁蛋呀就是贪玩，年纪又还小，这不最近闹狼嘛，我总担心铁蛋被狼给叼走。",
	["tid#RegionalText_687"]="我平时对铁蛋看管的也严，平时根本不让铁蛋出村子，可谁知道今天我一个不注意，这小兔崽子就溜出去了。",
	["tid#RegionalText_688"]="真要说有什么爱去的地方，那也就是村子后的山里了，所以我这才担心铁蛋是遇到狼了。",
	["tid#RegionalText_689"]="山里……米嫂，您先别着急，我再看看家里面，铁蛋还有没有留下什么线索。",
	["tid#RegionalText_690"]="米嫂，这地图是……？",
	["tid#RegionalText_691"]="这地图啊，这地图说来可话长了……",
	["tid#RegionalText_692"]="米嫂，如今事情紧急，您简单介绍一下就好。",
	["tid#RegionalText_693"]="啊，没错，少侠……这张地图确实是铁蛋平时老摆弄的，兴许……兴许这孩子去找这个山洞了？",
	["tid#RegionalText_694"]="这山洞里难道有什么东西，会让铁蛋好奇吗？",
	["tid#RegionalText_695"]="这山洞呀，就是个野洞，还常听人说闹鬼，所以村里人都避讳也从来不去那个山洞附近转悠……铁蛋你可千万别出什么事儿啊。",
	["tid#RegionalText_696"]="看来有了些许眉目，米嫂您且放心，我这就去这个山洞找找看。",
	["tid#RegionalText_697"]="是……是谁在那儿？不会是鬼吧，我好害怕！",
	["tid#RegionalText_698"]="是铁蛋吗，别害怕，我是人不是鬼，我是受村里所托来找你的，快跟我回家吧。",
	["tid#RegionalText_699"]="是真的吗，好……",
	["tid#RegionalText_700"]="咦？怎么是个女孩儿，你就是铁蛋？",
	["tid#RegionalText_701"]="大哥哥，我叫铁蛋，有什么问题么？",
	["tid#RegionalText_702"]="不不不，没有……你刚才说这里有死人，是什么情况？",
	["tid#RegionalText_703"]="我来山洞探险寻宝，就想玩深处看看，结果越走越深也没有尽头，还迷路出不去了。",
	["tid#RegionalText_704"]="可惜我费了好大功夫才进来，却什么宝藏都没有，还看到一个死人……我好害怕，还好大哥哥你来了。",
	["tid#RegionalText_705"]="死人？铁蛋，你且在这里等我一下，我去看看什么情况。",
	["tid#RegionalText_706"]="好，不过大哥哥你要快点回来呀，我还是有些害怕。",
	["tid#RegionalText_707"]="实在是太谢谢少侠了，你说铁蛋要是出个什么三长两短，可让我怎么活呀！",
	["tid#RegionalText_708"]="举手之劳，米嫂不必这么言谢。",
	["tid#RegionalText_709"]="铁蛋，快过来谢谢少侠！",
	["tid#RegionalText_710"]="谢谢大哥哥。",
	["tid#RegionalText_711"]="铁蛋好孩子，以后千万不要一个人去那么危险的地方了。",
	["tid#RegionalText_712"]="嗯……铁蛋知道啦。",
	["tid#RegionalText_713"]="家里也没什么值得拿出手的东西，就送少侠一点微薄的礼物吧。",
	["tid#RegionalText_714"]="对了，今天一定要留在我们家吃饭呀！我必须好好招待一下少侠！",
	["tid#RegionalText_715"]="已经在村子里叨扰多日，我也该启程告别了。",
	["tid#RegionalText_716"]="这村中狭小，自是缚不住少侠鸿鹄之志，不过少侠此去可有什么计划？",
	["tid#RegionalText_717"]="我暂时也无明确的计划，也是走马观花，四处游历。",
	["tid#RegionalText_718"]="说起来，这前路百里之外，有一处百里茶铺。",
	["tid#RegionalText_719"]="哦？百里茶铺？",
	["tid#RegionalText_720"]="没错，这茶铺的店家正是大胆的兄弟的牛大力。",
	["tid#RegionalText_721"]="原来是王大哥的兄弟，那我一定路过进去坐一坐。",
	["tid#RegionalText_722"]="既然少侠这么决定了，便帮忙带一封家书给大力如何？",
	["tid#RegionalText_723"]="少侠，这条路可偏僻，前后十里既无驿馆，也无客栈，进来歇歇脚，喝杯茶吧再走吧。",
	["tid#RegionalText_724"]="喝了我这茶，保证少侠您是神清气爽，身轻如燕，足下有风，赶路轻松！",
	["tid#RegionalText_725"]="你就是牛大力牛大哥吧，没想到你说话居然这般有趣。",
	["tid#RegionalText_726"]="哟？小兄弟你认识我？",
	["tid#RegionalText_727"]="我刚从稻香村来，还带了给你的信。",
	["tid#RegionalText_728"]="信？我看看，这可真是多谢小兄弟了……哎呀，还有人给我写信，我得瞅瞅……",
	["tid#RegionalText_729"]="没想到……大胆兄弟如此惦念我，我……呜呜……",
	["tid#RegionalText_730"]="诶……？牛大哥，发生了什么事儿，你怎么哭了？莫不是家里发生了什么变故？",
	["tid#RegionalText_731"]="让小兄弟见笑了，家里啥事儿也没有，只是看到我大胆兄弟的字迹，心里涌上来一股热气儿，就控制不住自己了，哈哈！",
	["tid#RegionalText_732"]="牛大哥也真是性情中人呢……",
	["tid#RegionalText_733"]="咦？什么事情吵吵嚷嚷的？",
	["tid#RegionalText_734"]="都这么不长眼睛吗，见到爷爷我来了也不知道利索点儿起开？",
	["tid#RegionalText_735"]="老板！老板呢？老板快给我滚出来！店里好吃好喝的赶紧给爷爷我摆上！",
	["tid#RegionalText_736"]="光天化日之下，这厮竟然如此猖狂！看我……",
	["tid#RegionalText_737"]="少侠，别！这瘟神还是不要轻易招惹，少侠先坐，我去招呼这尊瘟神。",
	["tid#RegionalText_738"]="牛大哥，这厮究竟什么来头，让大家如此忌惮？",
	["tid#RegionalText_739"]="唉，这瘟神是武夷山三十六洞天的人，号称什么真升化玄金衣佛陀，算了不说了……",
	["tid#RegionalText_740"]="怠慢了小兄弟，牛大哥实在对不住了，等稍后送走了这瘟神，我一定好好招待小兄弟一番。",
	["tid#RegionalText_741"]="三十六洞天？……",
	["tid#RegionalText_742"]="敢问这位先生，可否了解这附近的所谓“三十六洞天”",
	["tid#RegionalText_743"]="尼…嗦伸莫，窝刚来介哩，还不丝太清粗。",
	["tid#RegionalText_744"]="哦，抱歉，打扰了。",
	["tid#RegionalText_745"]="咩丝~。",
	["tid#RegionalText_746"]="小二，你可知这“三十六洞天”的事情？",
	["tid#RegionalText_747"]="嘿，客官原来您不知道呀，看您跟老板聊的熟络，还以为您对这里熟门熟路呢！",
	["tid#RegionalText_748"]="所以，小哥可否告知一二呢？",
	["tid#RegionalText_749"]="没问题客官，这三十六洞天啊，号称是什么山上成佛成道的漫天神佛哩！",
	["tid#RegionalText_750"]="不过我说，什么漫天神佛，哪有神佛下山逼人上供的，听说还老是强抢民女呢！",
	["tid#RegionalText_751"]="这不就是强盗吗！",
	["tid#RegionalText_752"]="你可说呢客官，不过我们这些乡野小民，能活着就不易喽，还是少惹他们。",
	["tid#RegionalText_753"]="这位仁兄，打扰了，你可对这“三十六洞天”有什么了解吗？",
	["tid#RegionalText_754"]="壮士，你有所不知，这与其说是“三十六洞天”，不如说是三十六窟。",
	["tid#RegionalText_755"]="这帮家伙，就是一伙山里的强盗，不知道哪里听来三十六洞天七十二福地的故事，就拿来对自己涂染一番。",
	["tid#RegionalText_756"]="他们肆意欺压武夷山上的茶农，贱价收茶然后逼着路过的商人的高价买去，一旦有所反抗，动辄直接杀人抢钱。",
	["tid#RegionalText_757"]="他们居然如此心狠手辣！",
	["tid#RegionalText_758"]="我看他们啊，罔生为人，一帮畜生，可惜我们这些商人只能忍气吞声，唉，啥时候才是个头，要不然回头弃了这条商路算了……",
	["tid#RegionalText_759"]="哈哈哈哈哈！你这小娘子，怎生得如此俊俏，便与爷爷我回山上过几天神仙日子如何呀？",
	["tid#RegionalText_760"]="奴家已有婚配，是有夫之妇，辜负大德恩情了。",
	["tid#RegionalText_761"]="这都不重要，哈哈，你且跟我上山就是了，山上可比这人间快活呀！",
	["tid#RegionalText_762"]="你！你这贼秃，你莫要拉扯我……我夫君一定不会放过你的！",
	["tid#RegionalText_763"]="哼！你现在说什么都不好使了，爷爷我就要带你上山！",
	["tid#RegionalText_764"]="好小子，敢坏你爷爷我的好事儿，有胆子你就这里等着，你爷爷我去叫人来！",
	["tid#RegionalText_765"]="还不快滚！",
	["tid#RegionalText_766"]="让这位娘子受惊了，不知道刚刚，那贼人有没有伤到你？",
	["tid#RegionalText_767"]="多谢公子搭救，奴家没什么外伤……不过刚才似也受了些惊吓，如今身体有些不适。",
	["tid#RegionalText_768"]="一个身影闯入茶铺，带来一阵骚动。",
	["tid#RegionalText_769"]="厢房内的书架，摆着很多书。",
	["tid#RegionalText_770"]="有人遗落的丹药，色泽饱满气味芬芳。",
	["tid#RegionalText_771"]="厢房里的木箱子，里面放着些杂物。",
	["tid#RegionalText_772"]="后厨的酒缸，里面呈放着自酿酒水。",
	["tid#RegionalText_773"]="一条绳子上挂着一些风干的腊肉。",
	["tid#RegionalText_774"]="几番调整后，你看上去已经完全是另一个人了。",
	["tid#RegionalText_775"]="一个白色瓷瓶，里面装着秘制的蒙汗药。",
	["tid#RegionalText_776"]="一坛上好的女儿红，坛子周围有隐隐的酒香。",
	["tid#RegionalText_777"]="你走到一刀仙旁边把酒摆在桌上，他看了你一眼但并没有怀疑什么。",
	["tid#RegionalText_778"]="混合着蒙汗药的女儿红，还剩下小半坛。",
	["tid#RegionalText_779"]="你翻看了一会，似有所得。",
	["tid#RegionalText_780"]="这些丹药可能是别人遗落了，你决定先代为保管一下。",
	["tid#RegionalText_781"]="箱子里有些能用的东西。",
	["tid#RegionalText_782"]="酒水带来的热劲直冲丹田，你隐隐觉得功力似乎精进了一分。",
	["tid#RegionalText_783"]="这块腊肉如果用来做菜应该不错。",
	["tid#RegionalText_784"]="你把整瓶蒙汗药都倒了进去，生怕别人喝了不会昏倒。",
	["tid#RegionalText_785"]="其中有一幅格外仔细，看上去像是一张地图？",
	["tid#RegionalText_786"]="问问米嫂知不知道什么吧。",
	["tid#RegionalText_787"]="书籍上面写着几个龙飞凤舞的大字《九霄天元功》，这似乎是一本内功心法。",
	["tid#RegionalText_788"]="老夫一生纵横天下，虽然我败了但我的武功没败，见此信者可研习绝学《九霄天元功》，替老夫继续威震江湖。",
	["tid#RegionalText_789"]="旁边箱子中的《龙吟生灭指》乃神龙教绝学，需要配合天元功一同修炼，否则极易走火入魔。",
	["tid#RegionalText_790"]="如果可以，请帮我掩埋尸骨，权当是传功之恩，莫问天绝笔。",
	["tid#RegionalText_791"]="这段时间从未来过后山，不曾想竟然别有景色。",
	["tid#RegionalText_792"]="前方隐约能看到一个山洞，大概就是存放古剑的地方吧。",
	["tid#RegionalText_793"]="……",
	["tid#RegionalText_794"]="哎哟，客官，这下您可捅了马蜂窝了！",
	["tid#RegionalText_795"]="他们的人马上就到，哎呀，这可糟了。",
	["tid#RegionalText_796"]="他们要来便来，怕他们作甚，我现在就出去，绝不会牵连了店里。",
	["tid#RegionalText_797"]="唉，客官您看您这说的叫什么话，我们不是这个意思。",
	["tid#RegionalText_798"]="客官您虽然武艺高强，但他们毕竟人多势众，好汉还不吃眼前亏呢，您二位到二楼躲躲吧！",
	["tid#RegionalText_799"]="好吧……",
	["tid#RegionalText_800"]="这位姑娘你且这在边歇着，他们就算来再多人，我也不会让他们伤害到你的。",
	["tid#RegionalText_801"]="公子能做到这般地步，奴家已经十分感激了，只是奴家实在不愿意多牵累公子了。",
	["tid#RegionalText_802"]="你放宽心就好，不过你身体确实没什么大碍吧？",
	["tid#RegionalText_803"]="承蒙公子关心，要真说有什么问题，也就是适才拉扯时，手臂有些扭伤而已，皮肉伤都算不上。",
	["tid#RegionalText_804"]="那就好，牛大哥你怎么上来了？",
	["tid#RegionalText_805"]="小兄弟，那花和尚带了他的兄弟一刀仙来，一群人把茶铺给围起来了，你可千万要躲好！",
	["tid#RegionalText_806"]="牛大哥，我不想牵连到你的茶铺和其他客人，我还是把他们引出去，剩下的自己解决吧。",
	["tid#RegionalText_807"]="你说这话是看不起谁！有你牛大哥在，绝对没问题，客人之前我就先疏散出去了，你不必担心。",
	["tid#RegionalText_808"]="可是，这……",
	["tid#RegionalText_809"]="你安心呆着，你牛大哥我敢在这条道上开茶铺，那也是有两把刷子的！",
	["tid#RegionalText_810"]="牛大力！识相点赶紧把人交出来，不然我一把火烧了你这茶铺！",
	["tid#RegionalText_811"]="哟，这位大仙，那短命鬼早就跑路了，人不在我这里了呀。",
	["tid#RegionalText_812"]="少跟爷爷我废话，真当本大仙我是傻子吗？再废话爷爷烧了你的破茶铺！",
	["tid#RegionalText_813"]="……嘿嘿，大仙您先消消气，要不这样，我给您开坛上好的女儿红赔罪，嘿嘿。",
	["tid#RegionalText_814"]="好你个牛大力，既然有好酒，那还不快快拿来？",
	["tid#RegionalText_815"]="（小声）哼，就知道你这老小子好这口……小兄弟！？",
	["tid#RegionalText_816"]="嘘！……",
	["tid#RegionalText_817"]="（小声）小兄弟怎么下来了！快回去！",
	["tid#RegionalText_818"]="（小声）我实在不忍心看牛大哥你被辱，不如让我……",
	["tid#RegionalText_819"]="（小声）且慢，小兄弟的心意我领了，不过明着撕破脸确实划不来，我这里有一剂无色无味的蒙汗药……",
	["tid#RegionalText_820"]="你们嘀嘀咕咕说什么呢？酒呢？",
	["tid#RegionalText_821"]="大仙您稍等，我这不正吩咐伙计去给您拿呢嘛……（小声）小兄弟，这事儿交给你，我来继续应付他们。",
	["tid#RegionalText_822"]="嗯！不错！好你个牛大力，没想到这破茶铺里还能藏着这么好的酒！",
	["tid#RegionalText_823"]="藏了这么久，就是等着大仙来品，这酒啊，也算没白藏着。",
	["tid#RegionalText_824"]="好酒藏着没问题，不过……嗝！你要是敢藏……藏人，本、本大仙可饶……饶不了你……呼！……噜！……",
	["tid#RegionalText_825"]="大仙，大仙？呸！这就倒了？可惜爷爷的一坛好酒。",
	["tid#RegionalText_826"]="兄弟，事不宜迟，你赶紧带着那个小娘子离开这儿！",
	["tid#RegionalText_827"]="一刀仙被我们蒙晕了，你现在赶紧乔装一下，我们离开这里。",
	["tid#RegionalText_828"]="实在是多谢公子。",
	["tid#RegionalText_829"]="这些都不打紧，如今是赶紧离开这里，说起来你家住何处？",
	["tid#RegionalText_830"]="奴家家在香梅镇。",
	["tid#RegionalText_831"]="好，我在门口等着，你赶紧扮好了便出来，我护送你回去。",
	["tid#RegionalText_832"]="少爷你拿到剑了吗？",
	["tid#RegionalZhangJQ_1"]="想不到你这山庄的人，看上去人模人样，暗地里都是些贼人",
	["tid#RegionalZhangJQ_2"]="姑娘，有事我们山庄定然帮忙，但是休要血口喷人！",
	["tid#RegionalZhangJQ_3"]="血口？我这腰坠从不离身，怎的参加一个东海霸王擂就没了呢！",
	["tid#RegionalZhangJQ_4"]="我们山庄可以帮忙……",
	["tid#RegionalZhangJQ_5"]="帮忙？你知道那坠子是什么东西么？找不到的话，我看这山庄也没必要留着了。",
	["tid#RegionalZhangJQ_6"]="狂妄！你……",
	["tid#RegionalZhangJQ_7"]="姑娘稍安勿躁，切磋大会因我召开，那么出了事情我也会负责",
	["tid#RegionalZhangJQ_8"]="哼……",
	["tid#RegionalZhangJQ_9"]="姑娘是何时到的山庄？有无接触过什么人？",
	["tid#RegionalZhangJQ_10"]="前日傍晚我到的山庄，住在乙字厢房，天晚了我并无外出。",
	["tid#RegionalZhangJQ_11"]="……这两日姑娘都去过哪里，接触过哪些人呢？",
	["tid#RegionalZhangJQ_12"]="我一向独来独往，听说这里藏书极多，昨日上午去了书房，下午在演武台观礼，晚宴后直接回去休息了",
	["tid#RegionalZhangJQ_13"]="何时发现那腰坠不在身上了？",
	["tid#RegionalZhangJQ_14"]="今日清晨时还在，等到现在就被偷走了。",
	["tid#RegionalZhangJQ_15"]="姑娘给我点时间，我定给你寻回来。",
	["tid#RegionalZhangJQ_16"]="怎么，我的腰坠找回来了么？",
	["tid#RegionalZhangJQ_17"]="居然还真被你找到了……",
	["tid#RegionalZhangJQ_18"]="姑娘，你说什么？",
	["tid#RegionalZhangJQ_19"]="没什么，这次就先放过你们吧。",
	["tid#RegionalZhangJQ_20"]="啊，{player_name}问的可是那个手持机弩的女侠？",
	["tid#RegionalZhangJQ_21"]="不错。",
	["tid#RegionalZhangJQ_22"]="我有印象，他是前日中午时候到的，别的我就不清楚了。",
	["tid#RegionalZhangJQ_23"]="哦，这样。",
	["tid#RegionalZhangJQ_24"]="唐女侠……我也只有过一面之缘。",
	["tid#RegionalZhangJQ_25"]="昨晚宴会结束，我曾在山庄碰到她神色匆匆的，似乎有什么事情。",
	["tid#RegionalZhangJQ_26"]="哦？那她去哪里了？",
	["tid#RegionalZhangJQ_27"]="这我就不知道了，山庄不限制客人的活动，我便没有询问。",
	["tid#RegionalZhangJQ_28"]="唐姑娘？你是说住在乙字厢房的那位？",
	["tid#RegionalZhangJQ_29"]="没错，你对她有影响么？",
	["tid#RegionalZhangJQ_30"]="有位好友住在丙字厢房，我前日晚去找她，正好遇到那唐门姑娘去甲字厢房找人。",
	["tid#RegionalZhangJQ_31"]="找人？",
	["tid#RegionalZhangJQ_32"]="是的，甲字厢房本来住着一位绝情谷的女侠，但是她好像突然有事，没参加擂台的比赛就走了",
	["tid#RegionalZhangJQ_33"]="腰坠？会不会是掉在她住的厢房里了？要不然就是在廊桥附近。",
	["tid#RegionalZhangJQ_34"]="如果这女侠去过书房，也许是落在书房中了。",
	["tid#RegionalZhangJQ_35"]="来廊桥观景的侠客不在少数，不如在廊桥附近找一找吧。",
	["tid#RegionalZhangJQ_36"]="我从没见过如此无礼的客人，这些蛮子……",
	["tid#RegionalZhangJQ_37"]="至于腰坠，你不妨去问问山庄里其他的人，看看他们有什么建议。",
	["tid#RegionalZhangJQ_38"]="这想必就是唐小夕丢的那个腰坠吧，不过怎么会在这里，这可和她说的不一样。",
	["tid#RegionalZhangJQ_39"]="而且看她身法轻盈，又善用暗器，想必平时为了方便也不会带这零碎之物。",
	["tid#RegionalZhangJQ_40"]="……而且这花纹，总觉得哪里见过，算了不管了，先把东西还给她。",
	["tid#RegionalZhangJQ_41"]="难道还要让我再说一遍么？",
	["tid#RegionalZhangJQ_42"]="我前日傍晚抵达山庄，住在乙字厢房，整晚都未外出。",
	["tid#RegionalZhangJQ_43"]="第二日上午我在书房，下午在演武台观礼，参加晚宴后直接回了厢房。",
	["tid#RegionalZhangJQ_44"]="今日上午参加东海霸王擂。",
	["tid#RegionalZhangJQ_45"]="你找我有事情？",
	["tid#RegionalZhangJQ_46"]="唐姑娘，我听接引弟子说，你前日是中午到的山庄，并非是傍晚？",
	["tid#RegionalZhangJQ_47"]="也许是接引弟子记错了吧。",
	["tid#RegionalZhangJQ_48"]="哦……那么你认识住在甲字厢房的客人么？",
	["tid#RegionalZhangJQ_49"]="……甲字厢房确实住着我的一位旧识，不过我与她并不熟，只是在房外打了个招呼。",
	["tid#RegionalZhangJQ_50"]="哦，廊桥那边唐姑娘有没有去过，景色很不错。",
	["tid#RegionalZhangJQ_51"]="我没去过，也不感兴趣，没别的事就不要来烦我了。",
	["tid#RegionalZhangJQ_52"]="切，这个女人……",
	["tid#RegionalZhangJQ_53"]="看开一点，事情总算解决了，不是么。",
	["tid#RegionalZhangJQ_54"]="但是我总觉得哪里不太对，又说不上来……",
	["tid#RegionalZhangJQ_55"]="我也总有一种不安的感觉，希望是我想多了吧。",
	["tid#RegionalZhangJQ_56"]="桌面被擦的纤尘不染，显然山庄的丫鬟已经打扫过这里了。",
	["tid#RegionalZhangJQ_57"]="在床垫的角落处，你好像看到一根蓝绿色的羽毛。",
	["tid#RegionalZhangJQ_58"]="这里被打扫的很干净，什么痕迹都没留下。",
	["tid#RegionalZhangJQ_59"]="地毯边缘似乎有一小块污点，你仔细一看，是一小块泥土。",
	["tid#RegionalZhangJQ_60"]="床上没有什么意义的线索。",
	["tid#RegionalZhangJQ_61"]="水壶里还泡着茶水，除此以外一无所获。",
	["tid#RegionalZhangJQ_62"]="桌面被擦的纤尘不染，显然山庄的丫鬟已经打扫过这里了。",
	["tid#RegionalZhangJQ_63"]="床垫有个诡异的突起，这显然不是丫鬟留下来的。",
	["tid#RegionalZhangJQ_64"]="这里被打扫的很干净，什么痕迹都没留下。",
	["tid#RegionalZhangJQ_65"]="用普通木材制作的屏风，但是上面所留的画作似乎十分不凡。",
	["tid#RegionalZhangJQ_66"]="一株种在花盆中的植物，看上去像是某种药材。",
	["tid#RegionalZhangJQ_67"]="书架上的书显得有些凌乱，似乎有谁寻找过什么。",
	["tid#RegionalZhangJQ_68"]="一本记录东海风土人情的书籍。",
	["tid#RegionalZhangJQ_69"]="荒废已久的枯井，现在已经不在这里打水了。",
	["tid#RegionalZhangJQ_70"]="山庄中漂亮的水池，四周种植着荷花。",
	["tid#RegionalZhangJQ_71"]="奇形怪状的假山，似乎也没什么看头。",
	["tid#RegionalZhangJQ_72"]="走廊四周雕刻着绚丽的花纹，这建筑设计的十分考究。",
	["tid#RegionalZhangJQ_73"]="略显泥泞的花坛，泥土中好像嵌着什么发光的石头。",
	["tid#RegionalZhangJQ_74"]="一个雕刻着貔貅的翡翠腰坠。",
	["tid#RegionalZhangJQ_75"]="小友，我有一事想请你跑一趟。",
	["tid#RegionalZhangJQ_76"]="前辈但说无妨，只要是我做得到的，都没问题。",
	["tid#RegionalZhangJQ_77"]="其实也不是什么难事，最近我总听山庄的人说，后山的山洞有人影和异响。",
	["tid#RegionalZhangJQ_78"]="这山洞早已荒废，我怕是被什么流窜的贼人占据了，做了据点。",
	["tid#RegionalZhangJQ_79"]="你帮我去看一看，若真有贼人，就驱散他们离开这附近。",
	["tid#RegionalZhangJQ_80"]="什么人！",
	["tid#RegionalZhangJQ_81"]="……",
	["tid#RegionalZhangJQ_82"]="站住！别跑！",
	["tid#RegionalZhangJQ_83"]="……",
	["tid#RegionalZhangJQ_84"]="呼呼……看你往哪里跑！",
	["tid#RegionalZhangJQ_85"]="哼，正好这里也没有外人，若是你死在这里，想必是无人知晓。",
	["tid#RegionalZhangJQ_86"]="想要我的命？先问问我的剑！",
	["tid#RegionalZhangJQ_87"]="受死！",
	["tid#RegionalZhangJQ_88"]="咳咳……你的功力，怎会如此深厚！",
	["tid#RegionalZhangJQ_89"]="不自量力！你到底是什么人！",
	["tid#RegionalZhangJQ_90"]="呵呵，虽然打不过你，但是我要走你也拦不住！神隐术！",
	["tid#RegionalZhangJQ_91"]="人呢！",
	["tid#RegionalZhangJQ_92"]="这令牌……怎么也刻了个貔貅……",
	["tid#RegionalZhangJQ_93"]="这些人，到底是什么人……",
	["tid#RegionalZhangJQ_94"]="前辈，我在后山发现一神秘人，但是被他跑了，只留下这令牌。",
	["tid#RegionalZhangJQ_95"]="令牌给我看看……嗯，我似乎见过这个样式的图案。",
	["tid#RegionalZhangJQ_96"]="看来有些人越来越坐不住了，这件事与你无关，我会命人去调查。",
	["tid#RegionalZhangJQ_97"]="这件事辛苦你了，正好有些东西已与我无用，就送给你权当答谢吧。",
	["tid#RegionalZhangJQ_98"]="前方似乎被巨石堵住了。",
	["tid#RegionalZhangJQ_99"]="黑暗中你不小心中了陷阱，等醒来时已经回到了洞口。",
	["tid#RegionalZhangJQ_100"]="是一个干练飒爽的女子，看衣饰打扮似乎是唐门中人。",
	["tid#RegionalZhangJQ_101"]="山庄的入门弟子，一个看起来大大咧咧的热血小伙，为人倒也和善，却也有些急躁。",
	["tid#RegionalZhangJQ_102"]="这位是山庄多年的老管家，行事稳重，却也有些古板，山庄有什么事，也许可以跟他咨询一番。",
	["tid#RegionalZhangJQ_103"]="山庄厢房的小丫鬟，如果忘记了厢房的位置，问下她就可以了。",
	["tid#RegionalZhangJQ_104"]="这是飞云山庄的接引弟子，看他一副少年老成的样子着实有些有趣。",
	["tid#RegionalZhangJQ_105"]="山庄女弟子，似乎是同辈弟子里的小师妹，嘴里经常念叨着师父的教诲。",
	["tid#RegionalZhangJQ_106"]="这就是天华君，平易近人，与他交谈，其举止言语更是让人心旷神怡。",
	["tid#RegionalZhangJQ_107"]="满脸凶相的地鼠门弟子，手里拿着炸弹，应该可以炸开这里的通路。",
	["tid#RegionalZhangJQ_108"]="恶名昭著的地鼠门商贩，眼中精光四射，直勾勾盯着过路人的荷包，不过……说不定他这里还真有些稀罕货物。",
	["tid#RegionalZhangJQ_109"]="满脸阴郁的神秘男子，身上透出血腥气味的杀意……",
	["tid#RegionalZhangJQ_110"]="在此处找找。",
	["tid#RegionalZhangJQ_111"]="幽深的山洞，黑魆魆的一点儿光都没有。",
	["tid#RegionalZhangJQ_112"]="一条狭窄的小路，勉强可以通过一个普通体型的成人。",
	["tid#RegionalZhangJQ_113"]="巨大的石头，似乎堵住了前面的出路。",
	["tid#RegionalZhangJQ_114"]="它锁住了，也许有什么办法可以打开这道门。",
	["tid#RegionalZhangJQ_115"]="有风流动的感觉，看起来可以安全通过。",
	["tid#RegionalZhangJQ_116"]="一条平整的走廊，不过栏杆有些斑驳，貌似有些年头了。",
	["tid#RegionalZhangJQ_117"]="几本古朴的旧书，上面的文字晦涩难懂。",
	["tid#RegionalZhangJQ_118"]="破旧的酒坛，不过里面已经空空如也，倒有些蛛网盘结。",
	["tid#RegionalZhangJQ_119"]="散发着霉味的破旧箱子，看起来这些木头已经开始腐朽了。",
	["tid#RegionalZhangJQ_120"]="隐藏在墙后的暗道，若非特殊情况，寻常人根本难以察觉。",
	["tid#RegionalZhangJQ_121"]="刻着貔貅的古怪令牌，不知有何来历。",
	["tid#RegionalZhangJQ_122"]="稻香村的女郎中，医术据说相当精湛。",
	["tid#RegionalZhangJQ_123"]="被收养在医馆的小姑娘。",
	["tid#RegionalZhangJQ_124"]="一名来看病的女村民。",
	["tid#RegionalZhangJQ_125"]="稻香村酒家的老板，因为贪财被村名称作刘老财。",
	["tid#RegionalZhangJQ_126"]="穿着纯阳道服的男子，面色略显忧愁。",
	["tid#RegionalZhangJQ_127"]="穿的破破烂烂的村民，身上有一股很重的酒味。",
	["tid#RegionalZhangJQ_128"]="稻香村的老好人牛二，劈柴、挑水、耕地、施肥的一把好手。",
	["tid#RegionalZhangJQ_129"]="稻香村的村长，据说曾经是一地的官老爷，年老了隐居于此。",
	["tid#RegionalZhangJQ_130"]="一名正在村子河边洗衣服的女村民。",
	["tid#RegionalZhangJQ_131"]="一名身强力壮的男村民，身上有淡淡的鱼腥味。",
	["tid#RegionalZhangJQ_132"]="慈眉善目的大娘，口中念念有词。",
	["tid#RegionalZhangJQ_133"]="表情冷库的女侠客，身上缠着锁链，虽然衣服有些脏兮兮的，但她却十分不在乎。",
	["tid#RegionalZhangJQ_134"]="这个农夫一幅十分警惕的表情。",
	["tid#RegionalZhangJQ_135"]="被信徒簇拥的女郎中，脸上充满了慈悲的表情。",
	["tid#RegionalZhangJQ_136"]="白莲教的信徒。",
	["tid#RegionalZhangJQ_137"]="白莲教明光堂堂主魏婧，因为未知的原因南下来到稻香村，一身功力深不可测。",
	["tid#RegionalZhangJQ_138"]="少侠今日准备启程？",
	["tid#RegionalZhangJQ_139"]="在山庄中暂住已有多日，是时候踏入中原了。",
	["tid#RegionalZhangJQ_140"]="不过在下第一次来中原，人生地不熟，不知老先生可有什么建议？",
	["tid#RegionalZhangJQ_141"]="飞云山庄地处东南临海，虽是世外桃源但也比较偏僻，往北六十里有一村庄名为稻香村，是距离最近的村子。",
	["tid#RegionalZhangJQ_142"]="少侠可以先前往此处，然后再做后面的打算。这些盘缠你收下，留在路上用。",
	["tid#RegionalZhangJQ_143"]="老人家，这里可是稻香村？",
	["tid#RegionalZhangJQ_144"]="正是，我是稻香村的村长，少侠可是从飞云山庄而来？",
	["tid#RegionalZhangJQ_145"]="不错，老人家这都看得出来？",
	["tid#RegionalZhangJQ_146"]="哈哈，近些天有不少从飞云山庄来的侠客在村子落脚休息。",
	["tid#RegionalZhangJQ_147"]="少侠若是要吃饭休息，可以去咱们稻香村的酒家，瞧见没有，那立着招子的地方就是了。",
	["tid#RegionalZhangJQ_148"]="客官，打尖还是住店？",
	["tid#RegionalZhangJQ_149"]="吃饭，再给我开间厢房。",
	["tid#RegionalZhangJQ_150"]="客官想吃点什么？",
	["tid#RegionalZhangJQ_151"]="走了这么远，饿的紧了，老板给我来三个菜，不用太复杂，越快越好。",
	["tid#RegionalZhangJQ_152"]="好的客官，马上就做好。",
	["tid#RegionalZhangJQ_153"]="……这饭菜滋味倒是与岛上不太一样。",
	["tid#RegionalZhangJQ_154"]="老板，给我来一壶酒，两张面饼。",
	["tid#RegionalZhangJQ_155"]="你怎么又来了，我，我不卖！",
	["tid#RegionalZhangJQ_156"]="嗯？不卖？",
	["tid#RegionalZhangJQ_157"]="你，你还能当着这么多人的面杀我不成！你们这些鹰犬，就知道欺负老百姓！我今天一口吃的喝的都不卖给你！",
	["tid#RegionalZhangJQ_158"]="哼！你好自为之！",
	["tid#RegionalZhangJQ_159"]="老板，怎么回事？",
	["tid#RegionalZhangJQ_160"]="她是锦衣卫……来我们村里抓人！",
	["tid#RegionalZhangJQ_161"]="抓人？",
	["tid#RegionalZhangJQ_162"]="哼，是乱抓人！抓别人也就罢了，居然要抓魏郎中，魏郎中救过我的命，我不会看着她被抓走的。",
	["tid#RegionalZhangJQ_163"]="既然这锦衣卫赖着不走，那就饿死她，看她能撑多久！",
	["tid#RegionalZhangJQ_164"]="你是谁，来找我做什么？",
	["tid#RegionalZhangJQ_165"]="姑娘是锦衣卫的人？为何要伤害无辜，抓捕无罪之人？",
	["tid#RegionalZhangJQ_166"]="（吞咽）无辜？那魏婧是白莲教明光堂堂主，白莲教乃邪教，祸害百姓危及朝廷，她一个堂主怎么就无辜了。",
	["tid#RegionalZhangJQ_167"]="魏婧是白莲教？",
	["tid#RegionalZhangJQ_168"]="当年朝廷抓了一批，其中跑了几个，这些年我一直在追捕这些人。",
	["tid#RegionalZhangJQ_169"]="如何证明魏婧是白莲教的人？",
	["tid#RegionalZhangJQ_170"]="这些教徒走到哪里都忍不住要传教，什么【强体的功法】【白莲经文】【白莲神像】，这些东西在村子里一定能找到。",
	["tid#RegionalZhangJQ_171"]="不如这样，你要是不信，你便去村子逛逛，肯定很容易就找得到我说的这些东西，那样就证明我没有错怪好人。",
	["tid#RegionalZhangJQ_172"]="还真是一样东西都不少，这下你该信我了吧。",
	["tid#RegionalZhangJQ_173"]="没想到魏婧真是白莲教的人，但是她也没有做什么歹事啊。",
	["tid#RegionalZhangJQ_174"]="邪教最擅长以小恩小惠笼络人心，这些东西对普通人是好东西，对习武之人不过是举手之劳。",
	["tid#RegionalZhangJQ_175"]="走吧，我倒要看看，这些村民还有什么好说的。",
	["tid#RegionalZhangJQ_176"]="魏婧姑娘啊，她可是个好人啊，救死扶伤，全村老小的病都是她看好的。",
	["tid#RegionalZhangJQ_177"]="最近有个锦衣卫的人说魏谷娘是白莲教的人，她怎么可能会是嘛。",
	["tid#RegionalZhangJQ_178"]="哎……世道变了啊。",
	["tid#RegionalZhangJQ_179"]="稻香村，是个好地方啊。",
	["tid#RegionalZhangJQ_180"]="虽然前些年闹过山贼，不过那都是过去的事情了，现在太平得很。",
	["tid#RegionalZhangJQ_181"]="别看我是个商人，但我对佛学可是颇有钻研的。",
	["tid#RegionalZhangJQ_182"]="嗯……这看上去像是南传佛教的经文。",
	["tid#RegionalZhangJQ_183"]="多去问问病人，应该有人学过白莲教的【强体功法】。",
	["tid#RegionalZhangJQ_184"]="至于【白莲经法】，这庙里倒是有一本佛经，但是我不敢保证一定是白莲教的经文。",
	["tid#RegionalZhangJQ_185"]="【白莲神像】这种东西，多半在年纪大的人手里，这些人最好骗了。",
	["tid#RegionalZhangJQ_186"]="白莲教是从南传佛教里脱离出来的教派。",
	["tid#RegionalZhangJQ_187"]="本来是个救死扶伤的教派，后来开始搞白莲圣母那一套，就走向了歧途。",
	["tid#RegionalZhangJQ_188"]="如今已经覆灭了大半，剩下教众都藏在村镇之中。",
	["tid#RegionalZhangJQ_189"]="你是来看病的么？",
	["tid#RegionalZhangJQ_190"]="白莲教？我不知道什么白莲教，少侠请不要被那锦衣卫给蒙骗了。",
	["tid#RegionalZhangJQ_191"]="我从小在山上长大，家里是帮官府采药的采药人，为了生计学了不少采药的本事。",
	["tid#RegionalZhangJQ_192"]="后来有位老前辈教我识字，又给了我一本医术，就这样我学会了一点医术。",
	["tid#RegionalZhangJQ_193"]="我是魏郎中的学徒小草。",
	["tid#RegionalZhangJQ_194"]="我的爹娘都不在了，是魏郎中收养的我，魏郎中是天底下最好的人！",
	["tid#RegionalZhangJQ_195"]="啊！魏郎中啊！那可是神医啊！",
	["tid#RegionalZhangJQ_196"]="我和相公两年了都没怀上，吃了魏郎中的药，一下子就怀了个小子，哈哈哈。",
	["tid#RegionalZhangJQ_197"]="……",
	["tid#RegionalZhangJQ_198"]="哎，不知道楚兄在此处还要呆多久……",
	["tid#RegionalZhangJQ_199"]="魏郎中？啊……我不是很熟，我没怎么生过病。",
	["tid#RegionalZhangJQ_200"]="喝酒，喝酒治百病！嗝……",
	["tid#RegionalZhangJQ_201"]="只要有我在，就没人能欺负魏郎中！",
	["tid#RegionalZhangJQ_202"]="我家孩子就是魏郎中治好的。",
	["tid#RegionalZhangJQ_203"]="魏郎中说了，只要心善，菩萨自会保佑的。",
	["tid#RegionalZhangJQ_204"]="我是个打渔的，经常下水，腿染了寒疾，身体也一天不如一天。",
	["tid#RegionalZhangJQ_205"]="后来魏郎中给我开了药，然后教了我一套功法，我的腿竟然就好了。",
	["tid#RegionalZhangJQ_206"]="大哥，那是一套什么样的功法？我能看看么？",
	["tid#RegionalZhangJQ_207"]="小兄弟要学么？我都已经背会了，那册子在桌子上，你拿去看吧。",
	["tid#RegionalZhangJQ_208"]="大娘，你家里这个神像好漂亮啊，这是什么的神像？",
	["tid#RegionalZhangJQ_209"]="少侠，这可是救苦救难圣母的神像啊。",
	["tid#RegionalZhangJQ_210"]="我也能拜圣母的神像么？",
	["tid#RegionalZhangJQ_211"]="少侠，我这里有个木头的，虽然小一些，但是大娘亲手刻的。",
	["tid#RegionalZhangJQ_212"]="只要心诚，圣母自会保佑你的。",
	["tid#RegionalZhangJQ_213"]="此处通向稻香村的前巷。",
	["tid#RegionalZhangJQ_214"]="此处通向稻香村的后巷。",
	["tid#RegionalZhangJQ_215"]="一壶稻香村佳酿。",
	["tid#RegionalZhangJQ_216"]="一本经文，也许和白莲教有关，可以找懂经文的人辨别一下。",
	["tid#RegionalZhangJQ_217"]="有些破败的佛像，很久都没有人修缮了。",
	["tid#RegionalZhangJQ_218"]="不知名的经书，但是内容已经不完整了。",
	["tid#RegionalZhangJQ_219"]="木架上面铺开了很多药材。",
	["tid#RegionalZhangJQ_220"]="一些膏状或者粉末状的药物放在这些瓶罐之中。",
	["tid#RegionalZhangJQ_221"]="记录着强身练气办法的秘籍。",
	["tid#RegionalZhangJQ_222"]="这里看上去什么都没有。",
	["tid#RegionalZhangJQ_223"]="一个漂亮的神像。",
	["tid#RegionalZhangJQ_224"]="李环让你把搜集的证据放在此处。",
	["tid#RegionalZhangJQ_225"]="三个菜，一个不多，一个不少。",
	["tid#RegionalZhangJQ_226"]="里面没什么可看的，你绕道吧。",
	["tid#RegionalZhangJQ_227"]="几个村民突然从树林里冲了出来，一团混乱当中你不知被谁敲中了脑袋。",
	["tid#RegionalZhangJQ_228"]="李环赶紧带着你从人群中离开，你一睁开眼已经回到了稻香村。",
	["tid#RegionalZhangJQ_229"]="白莲圣母福生无量，你们进去吧。",
	["tid#RegionalZhangJQ_230"]="白莲圣母保佑……",
	["tid#RegionalZhangJQ_231"]="心向善，不嗔怒，不纵欲，不贪婪，白莲明光加诸我身……",
	["tid#RegionalZhangJQ_232"]="多亏了白莲圣母，这林子里再也没有山贼了……",
	["tid#RegionalZhangJQ_233"]="诸位乡亲，今天的集会结束了，各位都回去吧。大家记得，光明一定会普照世间。",
	["tid#RegionalZhangJQ_234"]="你倒是很冷静，是已经料到我会在这找到你么？",
	["tid#RegionalZhangJQ_235"]="你们这些锦衣卫，盯上谁都是不死不休，我又能躲到哪里去？",
	["tid#RegionalZhangJQ_236"]="废话少说，这次我人证物证俱在，看你如何狡辩！",
	["tid#RegionalZhangJQ_237"]="狡辩？我有何罪需要狡辩！我白莲教有何罪需要狡辩！",
	["tid#RegionalZhangJQ_238"]="邪教狂徒还敢妖言惑众，速速投降免得我亲自动手。",
	["tid#RegionalZhangJQ_239"]="魏郎中你快走，这里我们先挡着！",
	["tid#RegionalZhangJQ_240"]="魏郎中，你不是我们的对手，莫要再抵抗了。",
	["tid#RegionalZhangJQ_241"]="这些年，我们东躲西藏，教徒分散各地，断了往来。",
	["tid#RegionalZhangJQ_242"]="无非是心中还相信明光终会照耀世人，这些年苦苦坚持下来。",
	["tid#RegionalZhangJQ_243"]="我们什么坏事都没有做，无非就是帮助老百姓，收点香火钱，可悲，可笑！",
	["tid#RegionalZhangJQ_244"]="既然跑不掉，对不起佛祖，弟子要开杀戒了！",
	["tid#RegionalZhangJQ_245"]="咳咳……",
	["tid#RegionalZhangJQ_246"]="说了你不是对手，走吧，跟我们一起回村子。",
	["tid#RegionalZhangJQ_247"]="这……魏郎中，你们这是做什么！",
	["tid#RegionalZhangJQ_248"]="她不是魏郎中，他是白莲教明光堂堂主魏婧！我的包裹里，装着证据。",
	["tid#RegionalZhangJQ_249"]="不可能！这分明是骗人！今天我舍了性命不要，也不会让你带走魏郎中！",
	["tid#RegionalZhangJQ_250"]="大家，她说的是真的，我确实是白莲教弟子。",
	["tid#RegionalZhangJQ_251"]="魏，魏郎中，你真的是白莲教的人？",
	["tid#RegionalZhangJQ_252"]="但是我从没有做过害大家的事情，白莲教也没做过害人的事情，从来没有……",
	["tid#RegionalZhangJQ_253"]="行了，散了吧。如果你们以后谁能举报白莲教的其他信徒，官府统统有赏。",
	["tid#RegionalZhangJQ_254"]="你是坏人！你们全都是坏人！",
	["tid#RegionalZhangJQ_255"]="……",
	["tid#RegionalZhangJQ_256"]="呜呜呜呜呜……",
	["tid#RegionalZhangJQ_257"]="魏婧那女人去哪里了？",
	["tid#RegionalZhangJQ_258"]="小妹妹，魏郎中人呢？",
	["tid#RegionalZhangJQ_259"]="魏郎中去村外采药了，好像是去村外的树林了。",
	["tid#RegionalZhangJQ_260"]="总觉得把事情给搞砸了……",
	["tid#RegionalZhangJQ_261"]="唉，没想到走江湖除了要武功高，还有这么多人情世故……",
	["tid#RegionalZhangJQ_262"]="唉……",
	["tid#RegionalZhangJQ_263"]="唉……",
	["tid#RegionalZhangJQ_264"]="唉……",
	["tid#RegionalZhangJQ_265"]="唉？",
	["tid#RegionalZhangJQ_266"]="在下{player_name},这位道长叹气不止，莫不是也有什么烦心事？",
	["tid#RegionalZhangJQ_267"]="贫道纯阳宫吴清霄，陪一好友来此了却心结，但是那好友到了这里已经足足月余，还不离开。",
	["tid#RegionalZhangJQ_268"]="纯阳宫事务繁忙，贫道实在是心系师门，所以焦躁不已。",
	["tid#RegionalZhangJQ_269"]="哦？你那好友的心结是什么？",
	["tid#RegionalZhangJQ_270"]="说实话贫道也不知道，只知道他如今在村子不远处的一个无名山上，也许他不想告诉关系亲近的人吧。",
	["tid#RegionalZhangJQ_271"]="正好我闲来无事，不如我试着帮你劝一下你那好友。",
	["tid#RegionalZhangJQ_272"]="……也罢，我那好友名叫楚朝阳，你在山顶上就能找到他。",
	["tid#RegionalZhangJQ_273"]="你是哪位？这山顶可不好上来。",
	["tid#RegionalZhangJQ_274"]="在下{player_name},吴清霄道长很担心你，托我上来看看。",
	["tid#RegionalZhangJQ_275"]="吴清霄？他是着急回纯阳宫吧，你和他说他回去便是，不用陪着我。",
	["tid#RegionalZhangJQ_276"]="……楚兄，不知道能否跟我说说你的心结？",
	["tid#RegionalZhangJQ_277"]="我的酒壶空了，你帮我下山从酒家带壶酒上来，我也许会告诉你。",
	["tid#RegionalZhangJQ_278"]="酒带来了么？",
	["tid#RegionalZhangJQ_279"]="{player_name},你可有手足兄弟，挚爱亲朋？",
	["tid#RegionalZhangJQ_280"]="楚兄何意？",
	["tid#RegionalZhangJQ_281"]="我是个孤儿，从小和师弟一起长大，我对他比亲弟弟还亲，但是没想到，我却害死了他！",
	["tid#RegionalZhangJQ_282"]="（说着话，两行泪水从楚朝阳脸上划过）",
	["tid#RegionalZhangJQ_283"]="楚兄的师弟？他难道也在此处？",
	["tid#RegionalZhangJQ_284"]="他就在这山下，就在这山的山洞之内，我不知道他在哪里，我也不敢面对他……",
	["tid#RegionalZhangJQ_285"]="师弟他从小就爱照顾人，不像我就只顾自己，所以他人缘很好。",
	["tid#RegionalZhangJQ_286"]="我和他约好，以后我做名震江湖的大侠，他做执掌一派的掌门，我们当初就是这么约定的。",
	["tid#RegionalZhangJQ_287"]="结果，师父突然离世，师弟也不在山上，掌门就落在我头上了。",
	["tid#RegionalZhangJQ_288"]="师弟定是想岔了，不知怎么想的入了魔道，我一气之下就把他逐出师门。",
	["tid#RegionalZhangJQ_289"]="但是这些年我很后悔，所以我一直在找他。",
	["tid#RegionalZhangJQ_290"]="在下不善水性，我怕这山洞有暗河。",
	["tid#RegionalZhangJQ_291"]="无妨，我有颗避气丸，你含在嘴中自可在水中通行无阻。",
	["tid#RegionalZhangJQ_292"]="楚兄，这封是柳兄的遗书。",
	["tid#RegionalZhangJQ_293"]="我师弟果然……？",
	["tid#RegionalZhangJQ_294"]="柳兄的尸骨，我已经安置好了。",
	["tid#RegionalZhangJQ_295"]="师弟，都怪师兄不好！让你受了这么多委屈！",
	["tid#RegionalZhangJQ_296"]="楚兄节哀。",
	["tid#RegionalZhangJQ_297"]="我这里有封信，你帮我交给吴清霄，他看了就明白了，我想一个人在这里坐坐。",
	["tid#RegionalZhangJQ_298"]="李道长，楚兄有封信托我交给你。",
	["tid#RegionalZhangJQ_299"]="一封信？我看看。",
	["tid#RegionalZhangJQ_300"]="……其中曲折，不足道也。书于此，作为朋友，劝你一句珍惜眼前人，切莫重蹈我的覆辙……",
	["tid#RegionalZhangJQ_301"]="唉，珍惜眼前人，楚兄，我明白了。",
	["tid#RegionalZhangJQ_302"]="这个男人脸上露出淡淡的悲伤，有些心不在焉的看着远处。",
	["tid#RegionalZhangJQ_303"]="密林中扛着木柴前行的农夫，口中念念有词。",
	["tid#RegionalZhangJQ_304"]="客官，有什么需要？",
	["tid#RegionalZhangJQ_305"]="老板，来坛好酒。",
	["tid#RegionalZhangJQ_306"]="这就上酒。",
	["tid#RegionalZhangJQ_307"]="这酒的味道颇为辛辣，喝完了之后你感觉晕乎乎的。",
	["tid#RegionalZhangJQ_308"]="通过少林的帮助，你鉴别出了经文的内容。",
	["tid#RegionalZhangJQ_309"]="你对着佛像拜了拜，结果不知从何处掉出了一本经书。",
	["tid#RegionalZhangJQ_310"]="你仔细的看了一圈，发现在佛像下压着一本经文。",
	["tid#RegionalZhangJQ_311"]="桌子上积满灰尘，放着一把柴刀。",
	["tid#RegionalZhangJQ_312"]="灯罩已经破破烂烂了，上面曾经画着菩萨的画像。",
	["tid#RegionalZhangJQ_313"]="山路上密布着无色无味的毒瘴，你晕了过去失去了知觉。",
	["tid#RegionalZhangJQ_314"]="显然，摸着黑乱走是十分不靠谱的，你根本找不到方向。",
	["tid#RegionalZhangJQ_315"]="火把照亮了前路。",
	["tid#RegionalZhangJQ_316"]="咔的一声，门被打开了。",
	["tid#RegionalZhangJQ_317"]="你似乎忘了自己不善水性，等醒过来已经被地下河冲到了入口。",
	["tid#RegionalZhangJQ_318"]="这种对死者不敬的事情还是不要做了吧。",
	["tid#RegionalZhangJQ_319"]="在埋葬死者的时候，有一本秘籍掉了出来。",
	["tid#RegionalZhangJQ_320"]="破烂的桌子，上面还遗留着一些物品。",
	["tid#RegionalZhangJQ_321"]="一个很破旧的落地台灯。",
	["tid#RegionalZhangJQ_322"]="斑驳的插槽上，遗留着用过的火把。",
	["tid#RegionalZhangJQ_323"]="看着像是通向山顶的路。",
	["tid#RegionalZhangJQ_324"]="一个木箱子。",
	["tid#RegionalZhangJQ_325"]="往下的通道内充满了积水，似乎是被地下河灌满了。",
	["tid#RegionalZhangJQ_326"]="不知名侠客的遗骸，看上去已经有一段时间了。",
	["tid#RegionalZhangJQ_327"]="刻画着龙头的玉牌。",
	["tid#RegionalZhangJQ_328"]="上面写着什么东西。",
	["tid#RegionalZhangJQ_329"]="看着像是通向山顶的路。",
	["tid#RegionalZhangJQ_330"]="这个门已经被打开了",
	["tid#RegionalZhangJQ_331"]="往下的通道内充满了积水，似乎是被地下河灌满了。",
	["tid#RegionalZhangJQ_332"]="通道尽头有光照射进来，外面看上去是一条山路。",
	["tid#RegionalZhangJQ_333"]="这条路通向山顶。",
	["tid#RegionalZhangJQ_334"]="这里很神秘。",
	["tid#RegionalZhangJQ_335"]="你隐隐听到了河水流动的声音。",
	["tid#RegionalZhangJQ_336"]="少侠，我想起来有把柴刀落在山上的老庙中了，你能帮我去取一下么？",
	["tid#RegionalZhangJQ_337"]="（这是一封名叫柳怀玉的人写下的遗书。）",
	["tid#RegionalZhangJQ_338"]="（上面记录了自己一生的得失，也写明了自己的死因——走火入魔。）",
	["tid#RegionalZhangJQ_339"]="（在遗书的最后，他提到对师兄的思念和愧疚之情，并且表明一切都是他自己的过错。）",
	["tid#RegionalZhangJQ_340"]="（想必，这就是楚朝阳师弟留下来的了，希望楚兄看过后，能够解开心结。）",
	["tid#RegionalZhangJQ_341"]="此处机关密室乃出吾手，尔等侥幸通过，无非运气而已，况且这密室本就是吾闲暇置之。",
	["tid#RegionalZhangJQ_342"]="欲取吾之秘宝者，此方万无一二，毫末之于高台而已。",
	["tid#RegionalZhangJQ_343"]="为这五行功法，我已耗费半余生，终究难以到达九重境界，如今顿感命不久矣，哀之，叹之皆无可奈何。",
	["tid#RegionalZhangJQ_344"]="我将这半生心血记载于此，希望有缘人能延续下去，修行到九重境界。",
	["tid#RegionalZhangJQ_345"]="倘若五行功法有朝一日能够震惊武林，九泉之下，我也倍感欣慰。",
	["tid#RegionalZhangJQ_346"]="一包炸药，足以裂石断金。",
	["tid#RegionalZhangJQ_347"]="中原畅销的一种药酒，据说喝了能提升功力。",
	["tid#RegionalZhangJQ_348"]="一块神秘的八卦牌，不知道用来做什么。",
	["tid#RegionalZhangJQ_349"]="释放着强烈杀意和不甘的幻影残像，简直是闻所未闻之物。",
	["tid#RegionalZhangJQ_350"]="不知存放多少年的古剑，仍然闪耀着寒光。",
	["tid#RegionalZhangJQ_351"]="一颗郁郁葱葱的大树。",
	["tid#RegionalZhangJQ_352"]="一些能够用来制作东西的木材。",
	["tid#RegionalZhangJQ_353"]="一条河静静地流淌着，也不知他的源头在哪里。",
	["tid#RegionalZhangJQ_354"]="这枚宝珠拥有惊人的热量，令人难以接近。",
	["tid#RegionalZhangJQ_355"]="一个隐藏起来的暗门，需要解锁机关才能通过。",
	["tid#RegionalZhangJQ_356"]="一个看上去非常华丽的箱子。",
	["tid#RegionalZhangJQ_357"]="一张写着些留言的字条。",
	["tid#RegionalZhangJQ_358"]="坚固的岩石，很突兀的立在地上。",
	["tid#RegionalZhangJQ_359"]="记录着五行神功的秘籍。",
	["tid#RegionalZhangJQ_360"]="坚固耐用的鹤嘴锄，可以击碎岩石。",
	["tid#RegionalZhangJQ_361"]="一张写着些留言的字条。",
	["tid#RegionalZhangJQ_362"]="记录着武功的秘籍。",
	["tid#RegionalZhangJQ_363"]="不知为何，这把剑拔不出来。",
	["tid#RegionalZhangJQ_364"]="你拔出了一把古剑，他仍然十分锋利。",
	["tid#RegionalZhangJQ_365"]="大树应声而倒，树干和碎木散落一地。",
	["tid#RegionalZhangJQ_366"]="宝珠冷却了下来，你轻易的拿走了宝珠。",
	["tid#RegionalZhangJQ_367"]="一个隐藏起来的暗门，需要解锁机关才能通过。",
	["tid#RegionalZhangJQ_368"]="先问问山庄里的其他人吧，他们应该能给我一些找腰坠的建议。",
	["tid#RegionalZhangJQ_369"]="这里就是唐小夕的厢房了，也需这里能有些线索。",
	["tid#RegionalZhangJQ_370"]="唐小夕来过书房，也需这里能有些线索。",
	["tid#RegionalZhangJQ_371"]="这里是廊坊，唐小夕说她没来过，但是……",
	["tid#RegionalZhangJQ_372"]="这个山洞……似乎真的有人活动的痕迹。",
	["tid#RegionalZhangJQ_373"]="前面有人！",
	["tid#RegionalZhangJQ_374"]="啊！你吓了我一大跳！",
	["tid#RegionalZhangJQ_375"]="我？我不是什么坏人，我是来找宝贝的！",
	["tid#RegionalZhangJQ_376"]="其他人？我没见过其他人。",
	["tid#RegionalZhangJQ_377"]="嘿嘿嘿嘿，客官，你我是有缘人啊。",
	["tid#RegionalZhangJQ_378"]="快来看看我这些货物，保准你满意。",
	["tid#RegionalZhangJQ_379"]="客官，这个宝贝我可不卖。",
	["tid#RegionalZhangJQ_380"]="我的功法，我的功法，我的功法……",
	["tid#RegionalZhangJQ_381"]="谁动了我的功法！",
	["tid#RegionalZhangJQ_382"]="金灵宝剑有缘人，裂木断枝流水存，自有冰心化火海，宝珠招引开天门。",
	["tid#RegionalZhangJQ_383"]="不好意思，我们确实连一坛多余的香梅酒都没有了。",
	["tid#RegionalZhangJQ_384"]="……",
	["tid#RegionalZhangJQ_385"]="打扰一下，这里是什么地方，我赶路正好途经此地。",
	["tid#RegionalZhangJQ_386"]="啊，客官，这里是香梅镇。",
	["tid#RegionalZhangJQ_387"]="我是这里酒家的老板，若是有什么事可以在店里找我。",
	["tid#RegionalZhangJQ_388"]="爱妻很喜欢这香梅镇的香梅酒。",
	["tid#RegionalZhangJQ_389"]="可惜不知道为什么，这里竟然一坛多余的酒都没有了。",
	["tid#RegionalZhangJQ_390"]="小女子青梅，客官要点什么？",
	["tid#RegionalZhangJQ_391"]="这店里好香的酒味，老板娘，来坛酒尝一尝！",
	["tid#RegionalZhangJQ_392"]="客官，这酒……",
	["tid#RegionalZhangJQ_393"]="小娃娃，这酒都是你爷爷的，你还是点些别的吃食吧。",
	["tid#RegionalZhangJQ_394"]="客官不好意思，店里的酒都被那位大爷定了，招待不周多多包涵。",
	["tid#RegionalZhangJQ_395"]="你说酒都被你要了？但我看这柜台最少摆了十几坛，你都能喝掉？",
	["tid#RegionalZhangJQ_396"]="十几坛？你爷爷要的是一百坛！俺们钱都付了，结果这娘们交不出酒，害俺在这里白白等了好几天。",
	["tid#RegionalZhangJQ_397"]="一百坛？你要这么多酒做什么？",
	["tid#RegionalZhangJQ_398"]="怎的小娃娃不是附近的人？俺们武夷山三十六洞下月召开天地英雄会，这酒都是用来款待四方侠客的。",
	["tid#RegionalZhangJQ_399"]="老板娘！你愣着干嘛，三天之内交不齐一百坛，俺就不客气了。",
	["tid#RegionalZhangJQ_400"]="客官，哦不，少侠，小女子有个不情之请。",
	["tid#RegionalZhangJQ_401"]="老板娘但说无妨。",
	["tid#RegionalZhangJQ_402"]="少侠若是可以，能不能……帮我做几坛酒？",
	["tid#RegionalZhangJQ_403"]="哦？在下闲来无事，正好也对你这青梅酒很感兴趣。",
	["tid#RegionalZhangJQ_404"]="谢谢少侠！那酒的配方我放在后厨桌子上了，少侠一观便知。",
	["tid#RegionalZhangJQ_405"]="黄酒六两，挤碎的浆果三个，梅花两钱，红糖四钱",
	["tid#RegionalZhangJQ_406"]="浆果可在后山采摘，其余三样分别可从田老伯，采花女和糖婆婆那里拿到。",
	["tid#RegionalZhangJQ_407"]="呼……这一坛终于做好了，去找青梅女过看看吧。",
	["tid#RegionalZhangJQ_408"]="老板娘，这是我做好的一坛青梅酒。",
	["tid#RegionalZhangJQ_409"]="辛苦少侠了，只是，唉……算了，大概是奴家命里有此一劫吧。",
	["tid#RegionalZhangJQ_410"]="怎么回事？",
	["tid#RegionalZhangJQ_411"]="那人要一百坛酒，如今算上少侠这坛，店里总共只有四十六坛，三天时间叫我如何去凑那一百坛。",
	["tid#RegionalZhangJQ_412"]="什么？我做着一坛都需要几个时辰，当初老板娘为什么要答应他的要求。",
	["tid#RegionalZhangJQ_413"]="奴家从未要卖一百坛，那人自顾自的把钱给我，完全是强买，而且那银子也不够买这么多酒，但我一个女子又能如何？",
	["tid#RegionalZhangJQ_414"]="哼！原来如此，让我去会会他。",
	["tid#RegionalZhangJQ_415"]="好啊，原来你是强买强卖，欺负女人，你把银子收回去，这酒不卖了！",
	["tid#RegionalZhangJQ_416"]="小娃娃嘴巴厉害，敢教训你爷爷！就不知道你命硬不硬，看招！",
	["tid#RegionalZhangJQ_417"]="呸，小子手底下有两招，俺今天认栽，把钱拿来，俺不买了。",
	["tid#RegionalZhangJQ_418"]="你打坏这么多桌椅，不需要赔钱么？这钱你拿不走了！",
	["tid#RegionalZhangJQ_419"]="小娃娃欺人太甚！你等着，你爷爷找人拆了你这破店！",
	["tid#RegionalZhangJQ_420"]="少侠，你快走吧，那贼人肯定不会善罢甘休。",
	["tid#RegionalZhangJQ_421"]="我走了，你怎么办？老板娘不用怕，我就等着他来，看他能怎么样。",
	["tid#RegionalZhangJQ_422"]="嘿，小娃娃竟然没跑。弟兄们，给俺上！",
	["tid#RegionalZhangJQ_423"]="哼！天威擒拿！",
	["tid#RegionalZhangJQ_424"]="啊！！！",
	["tid#RegionalZhangJQ_425"]="哪里来的小娘皮，弟兄们撤！",
	["tid#RegionalZhangJQ_426"]="你怎么在这里？",
	["tid#RegionalZhangJQ_427"]="我奉朝廷旨意，来此抓捕武夷山三十六洞的乱党头目，没想到在这里也遇到了几个宵小之辈。",
	["tid#RegionalZhangJQ_428"]="这才过去多久，又有案子要办……",
	["tid#RegionalZhangJQ_429"]="你还有别的事么？没事我要找地方吃饭了，赶了几天路，我的饼都吃完了。",
	["tid#RegionalZhangJQ_430"]="我认识这里酒家的老板娘，不如我带你去吧。",
	["tid#RegionalZhangJQ_431"]="老伯，你这里有六两的黄酒么。",
	["tid#RegionalZhangJQ_432"]="（余光打量了一下你的一身行头）少侠，我这已经没酒了。",
	["tid#RegionalZhangJQ_433"]="没了？这可怎么办……",
	["tid#RegionalZhangJQ_434"]="但……也不是不能商量，我还剩那么一点点，刚好六两，只要你给我十两银子。",
	["tid#RegionalZhangJQ_435"]="十两，就不能商量一下么……",
	["tid#RegionalZhangJQ_436"]="最少六两，否则我绝不给你。",
	["tid#RegionalZhangJQ_437"]="（我身上的钱不够，看看在镇上怎么能弄到六两银子）",
	["tid#RegionalZhangJQ_438"]="老伯，你这里有六两的黄酒么。",
	["tid#RegionalZhangJQ_439"]="（余光打量了一下你的一身行头）少侠，我这已经没酒了。",
	["tid#RegionalZhangJQ_440"]="没了？这可怎么办……",
	["tid#RegionalZhangJQ_441"]="但……也不是不能商量，我还剩那么一点点，刚好六两，只要你给我十两银子。",
	["tid#RegionalZhangJQ_442"]="哼，你这老头分明是想讹钱吧，我劝你老实一点，否则……",
	["tid#RegionalZhangJQ_443"]="嘿嘿，少侠，别生气，酒有的是，这就给你装好。",
	["tid#RegionalZhangJQ_444"]="请问，这林子里哪里有浆果？",
	["tid#RegionalZhangJQ_445"]="浆果？都已经被我吃了，【驿站密林】里应该还有一些，你去那里看看吧",
	["tid#RegionalZhangJQ_446"]="请问，你这里有梅花么？",
	["tid#RegionalZhangJQ_447"]="啊，我的已经都给酒家的老板娘了，如果你想要的找梅花，可以去【驿站密林】里找找",
	["tid#RegionalZhangJQ_448"]="婆婆，你这里有红糖么？",
	["tid#RegionalZhangJQ_449"]="有，婆婆这里有，你是要去给青梅女做青梅酒吧。",
	["tid#RegionalZhangJQ_450"]="婆婆你怎么知道。",
	["tid#RegionalZhangJQ_451"]="最近很多人都在帮她，唉，这三十六洞的人啊，这不是个东西。",
	["tid#RegionalZhangJQ_452"]="小娃娃过来，你爷爷今天高兴，你跟俺比划拳。",
	["tid#RegionalZhangJQ_453"]="哦？输赢怎么算？",
	["tid#RegionalZhangJQ_454"]="你要是能连续赢俺三把，俺就给你五、六，六两银子！",
	["tid#RegionalZhangJQ_455"]="嗨呀，晦气！再来！",
	["tid#RegionalZhangJQ_456"]="想要赢俺，你小子还差的有点远呢。",
	["tid#RegionalZhangJQ_457"]="哼，小娃娃运气挺好，这六两银子就赏你了！",
	["tid#RegionalZhangJQ_458"]="一名长相年轻清秀，脸上带着淡淡笑容的女子。",
	["tid#RegionalZhangJQ_459"]="身穿黑衣的无名男子，似乎是来买酒的。",
	["tid#RegionalZhangJQ_460"]="浑身酒气体型剽悍的男子，浑身行头看着有些像俗家的佛门弟子。",
	["tid#RegionalZhangJQ_461"]="贼眉鼠眼的老伯，好像一直在算计别人。",
	["tid#RegionalZhangJQ_462"]="一名年轻的姑娘，手捧着花篮，以卖花为生。",
	["tid#RegionalZhangJQ_463"]="靠着大树昏昏欲睡的乞丐，身边散落着一地果皮果核。",
	["tid#RegionalZhangJQ_464"]="香梅镇卖糖为生的婆婆。",
	["tid#RegionalZhangJQ_465"]="……",
	["tid#RegionalZhangJQ_466"]="曾在稻香村有一面之缘的锦衣卫，武功高强行事凌厉。",
	["tid#RegionalZhangJQ_467"]="少侠，我那朋友可有什么回复？",
	["tid#RegionalZhangJQ_468"]="记录着青梅酒制作方法的配方。",
	["tid#RegionalZhangJQ_469"]="一个空酒坛，能装大概一斤酒。",
	["tid#RegionalZhangJQ_470"]="镇前道路的中央，可以挡住任何人的去路。",
	["tid#RegionalZhangJQ_471"]="你正在进行一场猜拳。",
	["tid#RegionalZhangJQ_472"]="桌子上摆着一些吃食，茶水还有余温。",
	["tid#RegionalZhangJQ_473"]="有些晃动的一张木床，似乎由两层构成。",
	["tid#RegionalZhangJQ_474"]="一个酒坛，不知道里面装着什么。",
	["tid#RegionalZhangJQ_475"]="有些干枯的梅花，这不是它盛开的季节。",
	["tid#RegionalZhangJQ_476"]="红色的浆果，似乎很可口的样子。",
	["tid#RegionalZhangJQ_477"]="这条路通向附近的民宅。",
	["tid#RegionalZhangJQ_478"]="从这里去后厨。",
	["tid#RegionalZhangJQ_479"]="这是一个灌木丛。",
	["tid#RegionalZhangJQ_480"]="一条林间小路，不知道通向哪里。",
	["tid#RegionalZhangJQ_481"]="顺着枯井向下，你来到了一个阴森的洞穴中。",
	["tid#RegionalZhangJQ_482"]="你找到了一张潦草的地图。",
	["tid#RegionalZhangJQ_483"]="一条分叉路，通向驿道密林的不同区域。",
	["tid#RegionalZhangJQ_484"]="一条在树林中延伸的小路。",
	["tid#RegionalZhangJQ_485"]="似乎是一条路，但是前方有着大雾，看上去有迷失的危险。",
	["tid#RegionalZhangJQ_486"]="一条在树林中延伸的小路，远处有淡淡的花香。",
	["tid#RegionalZhangJQ_487"]="泥泞的弯路，令人怀疑这是否真的能通过。",
	["tid#RegionalZhangJQ_488"]="一条在树林中延伸的小路。",
	["tid#RegionalZhangJQ_489"]="带着斑驳锈迹的铁箱，不知已经被放置了多久。",
	["tid#RegionalZhangJQ_490"]="有些破损的地图，上面记录了一些内容。",
	["tid#RegionalZhangJQ_491"]="山崖边上的山洞。",
	["tid#RegionalZhangJQ_492"]="一条在树林中延伸的小路，远处有淡淡的花香。",
	["tid#RegionalZhangJQ_493"]="一朵颜色艳丽的花，散发着浓郁的香味。",
	["tid#RegionalZhangJQ_494"]="一颗在海边的参天大树。",
	["tid#RegionalZhangJQ_495"]="一朵颜色艳丽的花，散发着浓郁的香味。",
	["tid#RegionalZhangJQ_496"]="泥泞的弯路，令人怀疑这是否真的能通过。",
	["tid#RegionalZhangJQ_497"]="漂浮在半空的神奇陨铁，似乎带着磁力。",
	["tid#RegionalZhangJQ_498"]="碎裂的未知矿石，散发着余温。",
	["tid#RegionalZhangJQ_499"]="哈哈哈，长生不老，我早晚有一天可以长生不老！",
	["tid#RegionalZhangJQ_500"]="海仙大神保佑，保佑我明年日进斗金！",
	["tid#RegionalOpZhangJQ_1"]="少羽，我来和她说",
	["tid#RegionalText_Zhao_1"]="路过茶铺时，你感受到了一道一闪即逝的锐利目光，但是似乎并无敌意",
	["tid#RegionalText_Zhao_2"]="你顺着感觉看去，看到路边的茶铺二层有一个风采逼人的侠客……",
	["tid#RegionalText_Zhao_3"]="失礼了，我观阁下气宇非凡，忍不住运气相视……如有得罪，还请海涵。",
	["tid#RegionalText_Zhao_4"]="（遥遥一辑）客气了，兄台过誉了。",
	["tid#RegionalText_Zhao_5"]="哈哈！真是快人快语，如果有意，不如上来一起喝一杯？正好我的酒快喝完了。",
	["tid#RegionalText_Zhao_6"]="甚好甚好，那我就打扰了。",
	["tid#RegionalText_Zhao_7"]="伙计，刚才那位兄台在哪间客房？",
	["tid#RegionalText_Zhao_8"]="大侠，那位客观在天字甲号。大侠们不是身怀轻功，为何不直接飞进去？",
	["tid#RegionalText_Zhao_9"]="小二哥你也很会说笑，我是来做客的，怎能如此失礼？",
	["tid#RegionalText_Zhao_10"]="两位果然是真大侠！唉……",
	["tid#RegionalText_Zhao_11"]="（似乎有什么心事）不知你们这里有何好酒？",
	["tid#RegionalText_Zhao_12"]="大侠，我们这里是茶铺……本不卖酒水的，那位客官的酒是他自带的。",
	["tid#RegionalText_Zhao_13"]="这……还真是不巧，也是我失礼了。恩，闻味道，柜上应该有上号毛尖？那便给我准备一套茶具，我和这位兄台以茶代酒好了。",
	["tid#RegionalText_Zhao_14"]="有有有！我们的毛尖是品相最好的！大侠您真是神了！我这便给您准备！",
	["tid#RegionalText_Zhao_15"]="哦？阁下这是……",
	["tid#RegionalText_Zhao_16"]="本来以为兄台好酒，想必这里也有好酒才是，可惜此处似乎并无酒水售卖……",
	["tid#RegionalText_Zhao_17"]="哈哈哈！所以你看，我这是自己带的女儿红！",
	["tid#RegionalText_Zhao_18"]="实在失礼，本想和兄台一醉方休，可这……",
	["tid#RegionalText_Zhao_19"]="你我也是一见如故，何必如此客套，酒逢知己千杯少，既然不够喝……那喝茶也是极好的！",
	["tid#RegionalText_Zhao_20"]="既然如此，便让兄台试试我的茶艺。",
	["tid#RegionalText_Zhao_21"]="恩……似乎有败兴之人来了……",
	["tid#RegionalText_Zhao_22"]="来人不少……可是兄台仇家？恩，这些人上不得台面，恐怕还不配做兄台仇人。",
	["tid#RegionalText_Zhao_23"]="哈哈，多谢看重，似乎是来寻晦气的……",
	["tid#RegionalText_Zhao_24"]="话音未落，只见大门被一脚踹开，涌进了一伙彪形大汉……",
	["tid#RegionalText_Zhao_25"]="……这帮无赖……我……可恶……我……",
	["tid#RegionalText_Zhao_26"]="小二哥？小二哥？",
	["tid#RegionalText_Zhao_27"]="哇！！！！",
	["tid#RegionalText_Zhao_28"]="哈哈，小二哥这么大声，小心把贼人招来。",
	["tid#RegionalText_Zhao_29"]="我……是我胆小了……让两位大侠看笑话了",
	["tid#RegionalText_Zhao_30"]="明知不可为，保存自己也不算丢脸，不过这些贼人是何来头？",
	["tid#RegionalText_Zhao_31"]="这些是附近的山贼，叫什么三十六洞的。他们要这附近所有的店铺都要付给他们银钱，不然就要砸店……",
	["tid#RegionalText_Zhao_32"]="原来是坐地分赃的蟊贼，本地官府和武林帮派也不管？",
	["tid#RegionalText_Zhao_33"]="这里穷山恶水，哪儿有人为我们出头？",
	["tid#RegionalText_Zhao_34"]="我看小二哥义愤填膺，可是不甘心？",
	["tid#RegionalText_Zhao_35"]="掌柜待我如亲子，我有心拼命，可是他们人多势众又凶神恶煞，我实在是……",
	["tid#RegionalText_Zhao_36"]="既然你有心，那便好说，我有一计，可以保你们以后再无人上门寻事，你有胆量试试嘛？",
	["tid#RegionalText_Zhao_37"]="刑兄，莫非……",
	["tid#RegionalText_Zhao_38"]="如你所想，不知你意下如何？",
	["tid#RegionalText_Zhao_39"]="哈哈，有趣，既然如此，那么也算我一个……",
	["tid#RegionalText_Zhao_40"]="两位大侠在说什么？我怎么听不懂……",
	["tid#RegionalText_Zhao_41"]="包在我们身上，小二哥你只要如此这般……",
	["tid#RegionalText_Zhao_42"]="老家伙！你是不是当我们大当家的说话是放屁？",
	["tid#RegionalText_Zhao_43"]="你这笨蛋！有你这么说话的嘛！",
	["tid#RegionalText_Zhao_44"]="这……总之是这老家伙不要命了！大当家！咱们拆了他这把老骨头！",
	["tid#RegionalText_Zhao_45"]="呔！你们这帮土匪！看我教训你们！",
	["tid#RegionalText_Zhao_46"]="这……你这是干什么！不是让你躲起来？！你不要命了！",
	["tid#RegionalText_Zhao_47"]="掌柜放心，其实我是功夫高手，这帮土匪，我两三下就能打发！",
	["tid#RegionalText_Zhao_48"]="臭小子你失心疯了吧！看我卸了你的胳膊！",
	["tid#RegionalText_Zhao_49"]="突然，山贼的手一抖，刀脱手飞出",
	["tid#RegionalText_Zhao_50"]="咦？我刀呢？？",
	["tid#RegionalText_Zhao_51"]="（原来如此，刑兄是善使暗器的，这一下隔空弹指，就能震飞这个喽啰的兵刃还能让他不自知，真是好功力）",
	["tid#RegionalText_Zhao_52"]="再吃我一拳！",
	["tid#RegionalText_Zhao_53"]="哎呀！！！",
	["tid#RegionalText_Zhao_54"]="小二一拳封眼，山贼甲应声而倒",
	["tid#RegionalText_Zhao_55"]="（恩，看似是中了迎面一拳，其实是被真气打中了脑门昏厥了过去）",
	["tid#RegionalText_Zhao_56"]="怕了吧？还有谁敢上？",
	["tid#RegionalText_Zhao_57"]="这……不过是碰巧，吃我一拳！",
	["tid#RegionalText_Zhao_58"]="来、来的正好！也吃我一拳！（大侠救我……）",
	["tid#RegionalText_Zhao_59"]="（轮到我了，恩，刑兄妙技，我也不能太张扬，就用传功入体……）",
	["tid#RegionalText_Zhao_60"]="看我黑虎掏心！……哇！！！！",
	["tid#RegionalText_Zhao_61"]="哇！！！！咦？",
	["tid#RegionalText_Zhao_62"]="山贼乙一拳正中小二前胸，小二纹丝不动，山贼却倒飞了出去……",
	["tid#RegionalText_Zhao_63"]="喂！怎么回事？中邪了？？？！！",
	["tid#RegionalText_Zhao_64"]="哈哈，好功力，居然可以将内力注入他人体内，妙啊！",
	["tid#RegionalText_Zhao_65"]="彼此彼此，刑兄的暗器功夫也是出神入化",
	["tid#RegionalText_Zhao_66"]="小二哥也是露了一手，接下来咱们出面收拾残局吧？",
	["tid#RegionalText_Zhao_67"]="正有此意，那刑兄请！",
	["tid#RegionalText_Zhao_68"]="哈哈哈，我们一起！",
	["tid#RegionalText_Zhao_69"]="你们是什么人？！",
	["tid#RegionalText_Zhao_70"]="小小贼寇也敢横行乡里，让你们知道茶铺里也是藏龙卧虎的！",
	["tid#RegionalText_Zhao_71"]="多谢两位大侠！多谢两位大侠！",
	["tid#RegionalText_Zhao_72"]="哈哈，痛快，本来只是教训一下山野蟊贼，没想到这么痛快！",
	["tid#RegionalText_Zhao_73"]="都是刑兄妙技，我也觉得快意非常！",
	["tid#RegionalText_Zhao_74"]="你我二人真是投机，不过我有个约会不可不赴……",
	["tid#RegionalText_Zhao_75"]="相逢即是有缘，如我和刑兄缘分未尽，自然有重逢之时。",
	["tid#RegionalText_Zhao_76"]="有道理！既然如此我就此别过，下次我会多带两坛酒。",
	["tid#RegionalText_Zhao_77"]="哈哈，那我就更加期待与刑兄重逢之日了，刑兄一路顺风！",
	["tid#RegionalText_Zhao_78"]="外表风流不羁的侠客，指尖常把玩着一柄散发着寒芒的飞刀。",
	["tid#RegionalText_Zhao_79"]="看起来很机灵的小二哥。",
	["tid#RegionalText_Zhao_80"]="看起来很市侩的老板。",
	["tid#RegionalText_Zhao_81"]="功力不入流的江湖匪类，似乎是三十六洞的杂兵。",
	["tid#RegionalText_Zhao_82"]="功力不入流的江湖匪类，似乎是三十六洞的杂兵。",
	["tid#RegionalText_Zhao_83"]="功力不入流的江湖匪类，似乎是三十六洞的头目。",
	["tid#RegionalText_Zhao_84"]="犀利的目光",
	["tid#RegionalText_Zhao_85"]="小二，有酒吗？",
	["tid#RegionalText_Zhao_86"]="这位兄台，打扰了。",
	["tid#RegionalText_Zhao_87"]="小二哥，发生了什么？",
	["tid#RegionalText_Zhao_88"]="让探花暗中助阵小二哥",
	["tid#RegionalText_Zhao_89"]="我来暗中助阵小二哥",
	["tid#RegionalText_Zhao_90"]="是时候出手了",
	["tid#RegionalText_Zhao_91"]="与探花道别",
	["tid#ZhaoNpcName_1"]="我",
