	["tid#ZhaoNpcName_5"]="山贼乙",
	["tid#ZhaoNpcName_6"]="掌柜",
	["tid#ZhaoNpcName_7"]="山贼头目",
	["tid#option_txt_zhao_1"]="去找小二买壶酒吧……",
	["tid#option_txt_zhao_2"]="茶是好茶，让我看看人又如何……",
	["tid#option_txt_zhao_3"]="来者不善，后厨似乎有动静……",
	["tid#option_txt_zhao_4"]="看我和探花兄来一场双簧……",
	["tid#option_txt_zhao_5"]="好，到我出手了……",
	["tid#option_txt_zhao_6"]="效果不错啊……",
	["tid#option_txt_zhao_7"]="好好教训这帮小贼！",
