	["tid#regionalTXTs_155"]="发现五毒在饭菜中下毒后，众多带着武器的歹徒向大家袭来，而此时各大派高手都已中毒无法战斗，现在就需要少侠您来保护他们了。",
	["tid#regionalTXTs_156"]="打败反众后，通过一些线索，发现五毒并没有取得武林秘籍的动机，她下毒只是想要让大家假死，反而是想要救大家。那么谁才是这场闹剧的主导者。",
	["tid#regionalTXTs_157"]="原来明教早听说丐帮联合了纯阳对抗自己，故想要拿到纯阳秘籍，以此要挟。最终，纯阳直言自己将会保持中立。",
	["tid#regionalTXTs_158"]="这是你第一次来到大名鼎鼎的道教圣地武夷山，势必要到著名的武夷宫转一转了，只是武夷宫山门有两个不太对劲的守卫，过去看看。",
	["tid#regionalTXTs_159"]="谢渊表示浩气盟正在用人之时",
	["tid#regionalTXTs_160"]="七星阵是军师翟季真所布，可以问问他",
	["tid#regionalTXTs_161"]="根据四象八卦、星相演变而布之阵。可聚天地之气，纳四时之华。",
