	["tid#regionalGuide_239"]="护送妇人离开茶铺",
	["tid#regionalGuide_240"]="与方齐云交谈",
	["tid#regionalGuide_241"]="找到少羽了解情况",
	["tid#regionalGuide_242"]="与唐小夕交谈",
	["tid#regionalGuide_243"]="找到翡翠腰坠并交换给唐小夕",
	["tid#regionalGuide_244"]="与少羽对话",
	["tid#regionalGuide_245"]="天华君正在正房等你，似乎找你有事",
	["tid#regionalGuide_246"]="探寻后山情况",
	["tid#regionalGuide_247"]="追踪神秘人",
	["tid#regionalGuide_248"]="击败神秘人",
	["tid#regionalGuide_249"]="调查地上的令牌",
	["tid#regionalGuide_250"]="回到山庄找天华君复命",
	["tid#regionalGuide_251"]="向老管家打听周围地区的信息",
	["tid#regionalGuide_252"]="抵达稻香村，与村长交谈",
	["tid#regionalGuide_253"]="前往稻香村酒家找刘老财",
	["tid#regionalGuide_254"]="饱餐一顿",
	["tid#regionalGuide_255"]="跟随李环并与她交谈",
	["tid#regionalGuide_256"]="搜集李环所需的三项证据",
	["tid#regionalGuide_257"]="与李环商讨下一步行动",
	["tid#regionalGuide_258"]="与刘老财对话了解事情原由",
	["tid#regionalGuide_259"]="去医馆找到魏婧",
	["tid#regionalGuide_260"]="去【村外树林】寻找魏婧",
	["tid#regionalGuide_261"]="击败并抓捕魏婧",
	["tid#regionalGuide_262"]="回到村中，找到村长并公布真相",
	["tid#regionalGuide_263"]="心中感到烦闷，去酒家找刘老财要酒喝",
	["tid#regionalGuide_264"]="借酒消愁愁更愁，喝酒",
	["tid#regionalGuide_265"]="询问道长叹气的原由",
	["tid#regionalGuide_266"]="找到山顶的楚朝阳",
	["tid#regionalGuide_267"]="成功解开楚朝阳的心结后，找吴清霄复命",
	["tid#regionalGuide_268"]="与吴清霄交谈",
	["tid#regionalGuide_269"]="抵达香梅镇，与镇民交谈",
	["tid#regionalGuide_270"]="进入香梅酒家，与青梅女对话",
	["tid#regionalGuide_271"]="与酒家中的孔武对话",
	["tid#regionalGuide_272"]="青梅女似乎找你有事情",
	["tid#regionalGuide_273"]="完成一坛青梅酒的制作",
	["tid#regionalGuide_274"]="将青梅酒交给青梅女",
	["tid#regionalGuide_275"]="质问孔武",
	["tid#regionalGuide_276"]="在村外等待孔武返回",
	["tid#regionalGuide_277"]="与突然出现的的李环交谈",
	["tid#regionalGuide_278"]="把酒带给楚朝阳",
	["tid#regionaltips_1"]="飞云山庄的少羽似乎遇到了什么麻烦，不如先去[演武场]问问少羽，发生了什么。",
	["tid#regionaltips_2"]="既然要帮这位唐姑娘寻找腰坠，还需要[问问她]近日的行踪，这样才好推测她丢失的地点。",
	["tid#regionaltips_3"]="唐姑娘的行动轨迹大概也了解了，再去[问问山庄的其他人]，说不定会得到更多的线索。",
	["tid#regionaltips_4"]="看来唐姑娘腰坠的事情算是解决了，麻烦虽然解除，不过[少羽]依旧一副眉头不展的样子，似乎有什么话想说。",
	["tid#regionaltips_5"]="此前还在蓬莱之时便是得到了天华君的帮助，才能来到这中原，如今切磋大会总算是告一段落，也该去正式[拜会一下天华君]了。",
	["tid#regionaltips_6"]="天华君说山庄[后山]的山洞之中总有人影和异响，现在也无他事，就应允去[后山]的山洞里调查一番，一定要将贼人揪拿出来。",
	["tid#regionaltips_7"]="天华君说的没错，这山洞中果然盘桓着可疑之人，继续向正前方追踪神秘人，问清楚他到底有什么目的！",
	["tid#regionaltips_8"]="在山洞尽头追到了神秘人，战斗一触即发，先将他制服再说。",
	["tid#regionaltips_9"]="不想竟让这神秘的贼人逃走了，还是大意了，不过他遗落一枚奇怪的[令牌]，会从这上面找到什么线索吗？",
	["tid#regionaltips_10"]="这家店还真是行事利落，饭菜已经上桌了，赶紧填饱肚子为妙。",
	["tid#regionaltips_11"]="先前那差人与村子似有什么矛盾，这差人也算一身英气，也未为难店家，不像是什么坏人，她好像去村里的[荒庙]了,跟上去打听看看好了。",
	["tid#regionaltips_12"]="白莲教……如果真按李环所说，她所提到[强体功法][白莲经文][圣母神像]便都在村子里能够找到，这就去村子里打听一下，一旦找到就可以放在庙中的箱子里。",
	["tid#regionaltips_13"]="小草姑娘说魏大夫去了[村外树林]，但是看魏大夫在村中做的都是些好事，有些不愿意去面对真相，尤其是对小草这孩子……但是白莲教终究是邪教，还是去树林寻找看看吧，真希望魏大夫真的是去采药了。",
	["tid#regionaltips_14"]="没想到魏大夫果然是白莲教的人，果然还是必须帮助李环将她[抓捕]起来……吧？",
	["tid#regionaltips_15"]="事情结束了，魏大夫也已经被李环带走了，但是心里总觉得很奇怪……算了，去村子的酒家喝一杯吧。",
	["tid#regionaltips_16"]="稻香村的酒果然名不虚传，尚在酒瓮，就已经清香四溢，这就倒一杯试试看好了。",
	["tid#regionaltips_17"]="看起来邻座的朋友也在烦恼之中，既然如此，也听听他的愁怨如何。",
	["tid#regionaltips_18"]="看来想要帮助李道长尽快回到师门处理事务，就必须问清楚他朋友楚朝阳的事情，按照道长所言，他应该在近处无名山的山顶。",
	["tid#regionaltips_19"]="想了解一段故事，还需一壶好酒，也罢，就去村里买一壶酒给楚朝阳。",
	["tid#regionaltips_20"]="楚朝阳跟他的师弟，其实有什么误会，当面诉说有什么不好，他的师弟一定就在这[无名洞天]之间,只要找到他，说不定二人的误会就可解开了。",
	["tid#regionaltips_21"]="在个中逗留也有几日，听说去往武夷山的路上有个大一些的[镇子]，总是要路过，待路过时也探听一下当地特产，权当是不枉游历。",
	["tid#regionaltips_22"]="青梅姑娘的嘱托并非什么难事，这中原各式酿酒之法也是有趣的事情，这就去按照后厨的[配方]，去镇子里找些材料，再回来用这里空酒坛就可以完成。",
	["tid#regionaltips_23"]="且在镇外林道的[路中央]等着孔武那厮，看他“漫天神佛”能翻起什么波澜来！",
	["tid#regionaltips_24"]="带着令牌回到飞云山庄，找天华君听听他有什么看法。",
	["tid#regionaltips_25"]="在山庄已经逗留多日，是时候开始真正的中原之旅了，不过最好先找老管家问问这周边的情况。",
	["tid#regionaltips_26"]="稻香村在几十里外，等到了那里，先找村长了解下情况吧。",
	["tid#regionaltips_27"]="村长介绍了村子的酒家，虽然村子不大，但是酒家看起来相当不错，饥肠辘辘的肚子应该不会受委屈了。",
	["tid#regionaltips_28"]="这老板居然不做客人的生意，而且这客人看上去十分不凡，耐不住好奇还是问问刘老财吧。",
	["tid#regionaltips_29"]="现在所有的证据都到手了，虽然不愿意承认，但是到了和魏婧对峙的时候了，和李环商讨下一步的计划。",
	["tid#regionaltips_30"]="前往前巷的医馆，希望魏婧还在那里。",
	["tid#regionaltips_31"]="尘埃落定，魏婧伏法，这件事情对稻香村影响颇大，赶快回到稻香村去和[村长]解释清楚吧。",
	["tid#regionaltips_32"]="带着信回到酒馆找到李道长，李道长似乎很受触动，不过私人之事不宜打探，希望李道长自己没有什么心结。",
