	["tid#Narrator_id_30"]="茶铺风云",
	["tid#Narrator_id_31"]="在山庄日复一日的修炼，终究不是来到中原的目的，是时候离开这里下山历练了。",
	["tid#Narrator_id_32"]="隐藏在后山山下的世界，远比想象中更复杂，一场阴谋正悄悄地在黑暗中酝酿。",
	["tid#Narrator_id_33"]="本是一次单纯的游历，却意外碰上了朝廷大案，这一切到底是冤枉的，还是另有隐情？",
	["tid#Narrator_id_34"]="愚兄坐山头，吾弟埋山下，问君愁几许，徒留恨无期。",
	["tid#Narrator_id_35"]="官道上的茶铺，迎送了多少四方来客，在这些行色匆匆的人身上也总少不了行侠仗义的江湖事，也不知道今天吹过茶铺望子的风，是否有些喧嚣。",
	["tid#Narrator_id_36"]="书架",
	["tid#Narrator_id_37"]="丹药",
