	["tid#Conditional_hints_18"]="队伍中缺少唐门和五毒，无法通行。",
	["tid#Conditional_hints_19"]="你的包裹中未找到解毒丹。",
	["tid#Conditional_hints_20"]="你的包裹中未找到火把。",
	["tid#Conditional_hints_21"]="未找到可开启石门的道具。",
	["tid#Conditional_hints_22"]="队伍中缺少巨鲸和海沙，无法通行。",
	["tid#Conditional_hints_23"]="你的包裹中未找到避气丸。",
	["tid#Conditional_hints_24"]="他现在似乎不想动，[下午][晚上]过来试试。",
	["tid#Conditional_hints_25"]="他现在不想说话，[晚上]过来试试。",
	["tid#Conditional_hints_26"]="这件商品这个时间不卖。",
	["tid#Conditional_hints_27"]="她现在正饥肠辘辘，也需可以用面饼打消她的戒备。",
	["tid#Conditional_hints_28"]="缺少关键的证据。",
	["tid#Conditional_hints_29"]="这里黑黢黢的有些危险，还是稍后再来吧。",
	["tid#Conditional_hints_30"]="这里锁上了，需要一个圆形的东西开启它。",
	["tid#Conditional_hints_31"]="心魔在低语着什么，而你无法靠近它。",
	["tid#Conditional_hints_32"]="需要趁手的器具才能劈砍。",
	["tid#Conditional_hints_33"]="需要一些工具才能取水。",
	["tid#Conditional_hints_34"]="需要一桶水扑灭火焰。",
	["tid#Conditional_hints_35"]="需要一把鹤嘴锄击碎石头。",
	["tid#Conditional_hints_36"]="身上没有足够的银两。",
	["tid#Conditional_hints_37"]="身上没有足够的材料。",
	["tid#Conditional_hints_38"]="你需要先去酒家买酒。",
	["tid#Conditional_hints_39"]="楚朝阳还没有给你答复呢。",
	["tid#Conditional_hints_40"]="这条路最好不要擅自探索，特别是在没有地图的情况下。",
	["tid#Conditional_hints_41"]="树林前方有淡淡的毒瘴，需要[唐门]才能顺利通行。",
	["tid#Conditional_hints_42"]="这条道路在晚上前行会非常危险，还是白天再过来吧。",
	["tid#Conditional_hints_43"]="只有天师门的人擅长辨别这种花草。",
	["tid#Conditional_hints_44"]="得想办法搜集一些可疑的东西才能劝说信徒。",
	["tid#Conditional_hints_45"]="没有飞升丸，无法完成交易。",
	["tid#Conditional_hints_46"]="空口无凭，没有证据无法揭穿胡道人。",
	["tid#Conditional_hints_47"]="童子不愿意与你交谈飞升丸的事情，除非你完成过交易。",
	["tid#point_out_1"]="接取任务条件不满足",
	["tid#MapEncounterEvent_1"]="一个乞丐拦住了你的去路，他似乎已经饿得神志不清了，干裂的嘴唇中传出了沙哑的呓语……",
	["tid#MapEncounterEvent_2"]="突然从周围冒出了一伙彪形大汉，乞丐似乎也有了精神，他们把你围了起来……",
	["tid#MapEncounterEvent_3"]="乞丐恢复了神志，眼中放出摄人的精光，他手一挥，你感觉凭空增加了很多功力……",
	["tid#MapEncounterEvent_4"]="乞丐无力的倒下，而你拍拍手继续你的路程……",
	["tid#MapEncounterEvent_5"]="击败了这帮匪徒，你一边感叹世风日下人心不古，一边收下了他们身上的零钱。",
	["tid#MapEncounterEvent_6"]="在这荒郊野外，你居然看到一个美丽女子在路旁哭泣，据说她丢了盘缠正走投无路……",
	["tid#MapEncounterEvent_7"]="美女感谢你的帮助，作为报答，她将家传武具赠送给你",
	["tid#MapEncounterEvent_8"]="你拒绝帮忙，但是当你走远后发现钱袋已经不翼而飞……",
	["tid#MapEncounterEvent_9"]="你正欲顺便劫个色，但是走近一看女子已经消失不见，你不禁出了一身冷汗……",
	["tid#MapEncounterEvent_10"]="走在路上你正感觉又饥又渴，但是突然发现前面有间客栈，在这荒郊野外间显得十分诡异……",
	["tid#MapEncounterEvent_11"]="你前去投店，当晚睡得异常昏沉，起来一看已经被洗劫一空……",
	["tid#MapEncounterEvent_12"]="荒郊野外，这一定是黑店！你决定上前为民除害，没想到打砸一番后发现这是误会，你只能赔偿……",
	["tid#MapEncounterEvent_13"]="你正想转身离开，没想到后路已经被贼人包抄，只能动手了……",
	["tid#MapEncounterEvent_14"]="击溃敌人后，你收下了盗匪身上的钱作为战利品。",
	["tid#MapEncounterEvent_15"]="行走在僻静之处，不远处的山林间居然有冲天红光，一定有异宝出世！",
	["tid#MapEncounterEvent_16"]="你正准备打他们一个措手不及，没想到正中圈套，敌人狞笑着向你包围而来……",
	["tid#MapEncounterEvent_17"]="你本打算避免麻烦绕路而行，没想到迎面遇到一波夺宝者，只能动手自保。",
	["tid#MapEncounterEvent_18"]="你亲眼看着四波人马打得天昏地暗，最后成功者也匆匆而去，而你搜捡战场小赚了一笔……",
	["tid#MapEncounterEvent_19"]="敌人源源不断，此地不宜久留，你匆匆拿起了身边的钱箱迅速离开……",
	["tid#MapEncounterEvent_20"]="敌人源源不断，此地不宜久留，你匆匆拿起了身边的钱箱迅速离开……",
	["tid#MapEncounterEvent_21"]="你走过一片森林，突然听到林中有人呼救，似乎十分危急……",
	["tid#MapEncounterEvent_22"]="你立刻前往，发现正有强盗打劫行商，似乎将要有一场恶战。",
	["tid#MapEncounterEvent_23"]="你慢慢上前，发现强盗正在打劫行商，已经尸横遍地了。",
	["tid#MapEncounterEvent_24"]="事不关己高高挂起，你决定继续赶路。",
	["tid#MapEncounterEvent_25"]="你消灭了强盗，行商感谢你的见义勇为，送上了一笔钱作为谢礼。",
	["tid#MapEncounterEvent_26"]="你消灭了强盗，才发现剩下的几个行商已经趁乱逃走了。",
	["tid#MapEncounterEvent_27"]="不宽的路却被巨石挡住，不知道是被人特意放在此处还是从和山上滚下的……",
	["tid#MapEncounterEvent_28"]="你运气发力，将大石搬开，却看到不远处的树后几个毛贼正飞速离开，看来是拦路抢劫的，你上前捡起了他们扔下的武器。",
	["tid#MapEncounterEvent_29"]="你决定以不变应万变，坐在了路边，这时从路边走来一伙毛贼说出了熟悉的台词：【此山是我开，此树是我栽……】",
	["tid#MapEncounterEvent_30"]="为了不耽误时间，你决定绕路而行，想罢就运气轻功飞身而起，跳过了巨石。",
	["tid#MapEncounterEvent_31"]="你轻松打败了这伙毛贼，意外发现了一瓶突破丹。",
	["tid#MapEncounterEvent_32"]="路边看到一个衣衫破烂的妙龄少女在路边哭泣，旁边有草席盖住了一个人。似乎是传说中的卖身葬父……",
	["tid#MapEncounterEvent_33"]="你拿出50000文铜钱交给姑娘，姑娘感激不尽，将一本据说是父亲走火入魔前修炼的武功秘籍转赠给你。你看了下感觉茅塞顿开。",
	["tid#MapEncounterEvent_34"]="你拿出5000文铜钱交给姑娘，却被周围围观的人嘲笑小家子气，你觉得十分羞愧，低头快步离开。",
	["tid#MapEncounterEvent_35"]="你觉得囊中羞涩还是莫趟浑水，于是快步走过。",
	["tid#MapEncounterEvent_36"]="你走在路上，突然冲出一伙匪徒让你留下买路钱。",
	["tid#MapEncounterEvent_37"]="【对不起，我赶时间】，你扔出一把钱，匪徒忙于捡钱无心挡路，你扬长而去。",
	["tid#MapEncounterEvent_38"]="【我这一拳下去……你们可能会死】，说罢你踢翻了眼前的匪徒……",
	["tid#MapEncounterEvent_39"]="三十六计走为上，你看准人少的方向拔腿便跑，很快就冲出了重围。",
	["tid#MapEncounterEvent_40"]="很快匪徒就溃不成军，你觉得一番活动后，似乎对武学有新的感悟。",
	["tid#MapEncounterEvent_41"]="不远处的树林中有人争斗，查探之下发现有人正倚多欺少，怎么救人，你很犹豫……",
	["tid#MapEncounterEvent_42"]="路见不平拔刀相助，你跳进场中与人多一方斗到一起……",
	["tid#MapEncounterEvent_43"]="敌众我寡，只宜智取，你高声大喊官差来了，结果把两拨人都吓走了……你看着一地狼藉陷入了沉思……",
	["tid#MapEncounterEvent_44"]="你正想转身离开，没想到后路已经被贼人包抄，只能动手了……",
	["tid#MapEncounterEvent_45"]="很快匪徒就溃不成军，你觉得一番活动后，似乎对武学有新的感悟。",
	["tid#MapEncounterEvent_46"]="击败了这帮匪徒，你一边感叹世风日下人心不古，一边收下了他们身上的零钱。",
	["tid#MapEncounterEvent_47"]="你眼尖，发现路边草丛里掉了一个包裹，虽然没有打开看，但是凭入手重量，里面应该装了不少金银之物……",
	["tid#MapEncounterEvent_48"]="你觉得如此重金一定对失主至关重要，但是你在原地等了两天也不见失主前来，只好自己收下。",
	["tid#MapEncounterEvent_49"]="你发现草丛中压出了一条蹒跚的脚印，还有血迹，追踪之下发现了失主的遗体。埋葬了失主后，你将包裹收入囊中。",
	["tid#MapEncounterEvent_50"]="人不为己天诛地灭，你刚打算把金银收下，失主就带着兄弟们找了回来，不由分说拔刀便砍……",
	["tid#MapEncounterEvent_51"]="击败了这帮匪徒，你一边感叹世风日下人心不古，一边收下了他们身上的零钱。",
	["tid#MapEncounterEvent_52"]="一个乞丐拦住了你的去路，他似乎已经饿得神志不清了，干裂的嘴唇中传出了沙哑的呓语……",
	["tid#MapEncounterEvent_53"]="乞丐突然破口大骂：【我都饿的快死了，你给我钱有什么用？！】说罢夺过你的干粮袋自己吃了起来，再也不理你，你也不好意思要回那5000铜钱……",
	["tid#MapEncounterEvent_54"]="乞丐突然破口大骂：【我都饿的快死了，你给我酒有什么用？！】说罢夺过你的干粮袋自己吃了起来，还把你的酒也喝了。不过走前扔给了你一本武功秘籍【制杖神功】。",
	["tid#MapEncounterEvent_55"]="乞丐突然破口大骂：【我都饿的快死了，你连口吃的都不给我？！】说罢扬长而去。",
	["tid#MapEncounterEvent_56"]="在这荒郊野外，你居然看到一个美丽女子在路旁哭泣，据说她丢了盘缠正走投无路……",
	["tid#MapEncounterEvent_57"]="女子微微一笑，扬手对你洒出了一阵烟雾，你随即失去了知觉……醒来后，发现身上的银钱已经被搜刮一空。",
	["tid#MapEncounterEvent_58"]="你正想转身离开，没想到后路已经被贼人包抄，果然是一个圈套，只能动手了……",
	["tid#MapEncounterEvent_59"]="你假装色授魂与，一脸痴迷的靠近，突然出手制住了女子，原来是江洋大盗白牡丹。将她交给捕快后你得到了一笔赏金。",
	["tid#MapEncounterEvent_60"]="很快匪徒就溃不成军，你觉得一番活动后，似乎对武学有新的感悟。",
	["tid#MapEncounterEvent_61"]="走在路上你正感觉又饥又渴，但是突然发现前面有间客栈，在这荒郊野外间显得十分诡异……",
	["tid#MapEncounterEvent_62"]="你前去投店，结果意外的非常舒适，第二天醒来感觉精神百倍，功力甚至有所增进。",
	["tid#MapEncounterEvent_63"]="荒郊野外，这一定是黑店！你决定上前为民除害，果不其然这是一家人肉包子铺，小二、掌柜、厨子全都是江洋大盗！",
	["tid#MapEncounterEvent_64"]="小心驶得万年船，你决定今天露宿，于是匆匆离开。一夜过去，无事发生。",
	["tid#MapEncounterEvent_65"]="很快匪徒就溃不成军，你觉得一番活动后，似乎对武学有新的感悟。",
	["tid#MapEncounterEvent_66"]="行走在僻静之处，不远处的山林间居然有冲天红光，一定有异宝出世！",
	["tid#MapEncounterEvent_67"]="你打算捡个便宜，但是七拐八拐间居然跟丢了……只好继续赶路。",
	["tid#MapEncounterEvent_68"]="你本打算避免麻烦绕路而行，没想到迎面遇到一波夺宝者，只能动手自保。",
	["tid#MapEncounterEvent_69"]="你正想螳螂捕蝉，没想到还有人打算黄雀在后……只能动手了……",
	["tid#MapEncounterEvent_70"]="很快匪徒就溃不成军，你觉得一番活动后，似乎对武学有新的感悟。",
	["tid#MapEncounterEvent_71"]="击败了这帮匪徒，你一边感叹世风日下人心不古，一边收下了他们身上的零钱。",
	["tid#MapEncounterEvent_72"]="你走过一片森林，突然听到林中有人呼救，似乎十分危急……",
	["tid#MapEncounterEvent_73"]="你正准备杀他们一个措手不及，没想到正中圈套，敌人狞笑着向你包围而来……",
	["tid#MapEncounterEvent_74"]="你慢慢上前，果然发现这是个引军入瓮的圈套，你戏耍了敌人后扬长而去，念头通达下感觉功力又有精进。",
	["tid#MapEncounterEvent_75"]="你正想转身离开，没想到后路已经被贼人包抄，只能动手了……",
	["tid#MapEncounterEvent_76"]="很快匪徒就溃不成军，你觉得一番活动后，似乎对武学有新的感悟。",
	["tid#MapEncounterEvent_77"]="击败了这帮匪徒，你一边感叹世风日下人心不古，一边收下了他们身上的零钱。",
	["tid#MapEncounterEvent_78"]="不宽的路却被巨石挡住，不知道是被人特意放在此处还是从和山上滚下的……",
	["tid#MapEncounterEvent_79"]="你运气发力，将大石搬开，正在面红耳赤发力期间，突然被拦路毛贼包围，你只能扔下大石准备自卫……",
	["tid#MapEncounterEvent_80"]="你决定以不变应万变，坐在了路边，过了一会儿又来了几位江湖同道，你们合力搬开了大石。众人结伴同行，切磋印证武功之后感觉功力又有精进。",
	["tid#MapEncounterEvent_81"]="为了不耽误时间，你决定绕路而行，想罢就运气轻功飞身而起，没想到被人用网捉住，被抢走了身上的财物。",
	["tid#MapEncounterEvent_82"]="很快匪徒就溃不成军，你觉得一番活动后，似乎对武学有新的感悟。",
	["tid#MapEncounterEvent_83"]="路边看到一个衣衫破烂的妙龄少女在路边哭泣，旁边有草席盖住了一个人。似乎是传说中的卖身葬父……",
	["tid#MapEncounterEvent_84"]="你拿出50000文铜钱交给姑娘，姑娘感激不尽，这时人群中突然挤进来几个泼皮勒索你，你决定让他们知道花儿为什么这样红……",
	["tid#MapEncounterEvent_85"]="你拿出5000文铜钱交给姑娘，姑娘千恩万谢表示来世做牛做马也要报答你的恩情，你念头通达，感觉功力又有精进！",
	["tid#MapEncounterEvent_86"]="你正打算离开，但是突然发现有个阔少大声调戏姑娘，你揍了他一顿，顺手拿了他的钱袋。",
	["tid#MapEncounterEvent_87"]="击败了这帮匪徒，你一边感叹世风日下人心不古，一边收下了他们身上的零钱。",
	["tid#MapEncounterEvent_88"]="你走在路上，突然冲出一伙匪徒让你留下买路钱。",
	["tid#MapEncounterEvent_89"]="【对不起，我赶时间】，你扔出一把钱，匪徒忙于捡钱无心挡路，你扬长而去。",
	["tid#MapEncounterEvent_90"]="【我这一拳下去……你们可能会死】，说罢你踢翻了眼前的匪徒……",
	["tid#MapEncounterEvent_91"]="三十六计走为上，你看准人少的方向拔腿便跑，很快就冲出了重围。",
	["tid#MapEncounterEvent_92"]="很快匪徒就溃不成军，你觉得一番活动后，似乎对武学有新的感悟。",
	["tid#MapEncounterEvent_93"]="不远处的树林中有人争斗，查探之下发现有人正倚多欺少，怎么救人，你很犹豫……",
	["tid#MapEncounterEvent_94"]="路见不平拔刀相助，你跳进场中与人多一方斗到一起……没想到人多一方是官差！你被两面夹击了！",
	["tid#MapEncounterEvent_95"]="敌众我寡，只宜智取，你高声大喊官差来了，果然人多一方做贼心虚很快就撤退了。被围攻的商队首领感谢你的机智，赠送你一袋钱。",
	["tid#MapEncounterEvent_96"]="三十六计走为上，你看准人少的方向拔腿便跑，很快就冲出了重围。",
	["tid#MapEncounterEvent_97"]="敌人源源不断，此地不宜久留，你匆匆拿起了身边的钱箱迅速离开……",
	["tid#MapEncounterEvent_98"]="你眼尖，发现路边草丛里掉了一个包裹，虽然没有打开看，但是凭入手重量，里面应该装了不少金银之物……",
	["tid#MapEncounterEvent_99"]="你觉得如此重金一定对失主至关重要，但是很快失主就带着兄弟们找了回来，不由分说拔刀便砍……",
	["tid#MapEncounterEvent_100"]="你发现草丛中压出了一条蹒跚的脚印，还有血迹，追踪之下发现了一个受伤的姑娘……事后姑娘和你惜别，并将一瓶突破丹赠送给你。",
	["tid#MapEncounterEvent_101"]="人不为己天诛地灭，你将包裹里的钱据为己有，迅速离开了。",
	["tid#MapEncounterEvent_102"]="击败了这帮匪徒，你一边感叹世风日下人心不古，一边收下了他们身上的零钱。",
	["tid#MapEncounterChoice_1"]="给他5000铜钱",
	["tid#MapEncounterChoice_2"]="给他酒",
	["tid#MapEncounterChoice_3"]="轰他走",
