	["tid#MapEncounterChoice_10"]="前往抢夺",
	["tid#MapEncounterChoice_11"]="绕道而行",
	["tid#MapEncounterChoice_12"]="去看热闹",
	["tid#MapEncounterChoice_13"]="立刻上前",
	["tid#MapEncounterChoice_14"]="小心查探",
	["tid#MapEncounterChoice_15"]="听而不闻",
