	["tid#MapEncounterChoice_20"]="量力而为五千文",
	["tid#MapEncounterChoice_21"]="视而不见",
	["tid#MapEncounterChoice_22"]="10000铜钱花钱消灾",
	["tid#MapEncounterChoice_23"]="上前动手",
	["tid#MapEncounterChoice_24"]="夺路而逃",
	["tid#MapEncounterChoice_25"]="拔刀相助",
	["tid#MapEncounterChoice_26"]="智取解决",
	["tid#MapEncounterChoice_27"]="与我无关",
	["tid#MapEncounterChoice_28"]="静待失主",
	["tid#MapEncounterChoice_29"]="追踪寻找",
	["tid#MapEncounterChoice_30"]="据为己有",
	["tid#MapEncounterName_1"]="路遇乞丐",
	["tid#MapEncounterName_2"]="荒郊美女",
	["tid#MapEncounterName_3"]="荒村野店",
	["tid#MapEncounterName_4"]="异宝出世",
	["tid#MapEncounterName_5"]="求救之声",
	["tid#MapEncounterName_6"]="大石挡路",
	["tid#MapEncounterName_7"]="卖身葬父",
	["tid#MapEncounterName_8"]="拦路恶霸",
	["tid#MapEncounterName_9"]="路见不平",
	["tid#MapEncounterName_10"]="路不拾遗",
	["tid#MapEncounterName_11"]="路遇乞丐",
	["tid#MapEncounterName_12"]="荒郊美女",
	["tid#MapEncounterName_13"]="荒村野店",
	["tid#MapEncounterName_14"]="异宝出世",
	["tid#MapEncounterName_15"]="求救之声",
	["tid#MapEncounterName_16"]="大石挡路",
	["tid#MapEncounterName_17"]="卖身葬父",
	["tid#MapEncounterName_18"]="拦路恶霸",
	["tid#MapEncounterName_19"]="路见不平",
	["tid#MapEncounterName_20"]="路不拾遗",
	["tid#dialogueEventName_1"]="张九龄",
	["tid#dialogueEventName_2"]="我",
	["tid#dialogueEventName_3"]="韩非池",
	["tid#dialogueEventName_4"]="吉婆婆",
	["tid#dialogueEventName_5"]="李白",
	["tid#dialogueEventName_6"]="慕容",
	["tid#dialogueEventName_7"]="八卦",
	["tid#dialogueEventDes_1"]="年轻人，找老朽何事。",
	["tid#dialogueEventDes_2"]="相比阁下就是九龄公了，我来请教慕容的基本习俗。",
	["tid#dialogueEventDes_3"]="姑苏慕容演奏本是一件娱人身心的乐事，或收或发全凭演奏着内心的感悟。",
	["tid#dialogueEventDes_4"]="若演奏之人真心居正，那么这曲子便可以驱百祟，荡奸邪，舞人心。",
	["tid#dialogueEventDes_5"]="哦，原来是这样。",
	["tid#dialogueEventDes_6"]="来，跟我一起读。",
	["tid#dialogueEventDes_7"]="望月怀远",
	["tid#dialogueEventDes_8"]="海上生明月，天涯共此时。",
	["tid#dialogueEventDes_9"]="情人怨遥夜，竟夕起相思。",
	["tid#dialogueEventDes_10"]="灭烛怜光满，披衣觉露滋。",
	["tid#dialogueEventDes_11"]="不堪盈手赠，还寝梦佳期。",
	["tid#dialogueEventDes_12"]="好诗，不愧是九龄公，余音袅袅，悄怆幽邃。",
	["tid#dialogueEventDes_13"]="我去也，这些东西，你去交给韩非池，他会告诉你招贤日的由来。",
	["tid#dialogueEventDes_14"]="你手中的彩锦可是九龄公命你送来的？",
	["tid#dialogueEventDes_15"]="是的韩先生。",
	["tid#dialogueEventDes_16"]="招贤日是本门一年一度的祭典。是创立姑苏慕容的子敬公设立的，本是用以纪念他与挚友李百药先生的情谊，百余年过去，招贤日也逐渐演化成为纪念姑苏慕容创立以及祭拜储位先贤的典礼。",
	["tid#dialogueEventDes_17"]="每年姑苏慕容的吉时吉日，都是在除夕当晚由门中负责教授数书科目的先生们根据星相卜卦而得的，如今招贤日已近，需得尽快将准备工作做完。",
	["tid#dialogueEventDes_18"]="那幸好九龄公准备的及时。",
	["tid#dialogueEventDes_19"]="也是你送的准时。请你帮我去找吉婆婆带个话。说招贤日的材料已经备齐，请她来做最后的准备工作，当然你也可以向她了解更多姑苏慕容的历史。",
	["tid#dialogueEventDes_20"]="韩先生派你来的，原来如此。",
	["tid#dialogueEventDes_21"]="是的，韩先生派我来此给您带个口信，说是招贤日材料已经备齐，请您去做最后的准备工作。",
	["tid#dialogueEventDes_22"]="好。好。我随后就去，年轻人，你好面生，不似是门中人啊。",
	["tid#dialogueEventDes_23"]="是的阿婆，我并非门中人。此番也是来了解慕容的武学和文化。",
	["tid#dialogueEventDes_24"]="很好，年轻人是要四处多看看，可惜武学方面老太婆我给不了你太多的经验了，这门内传承的文化故事我倒是可以给你讲上一讲。",
	["tid#dialogueEventDes_25"]="那太好了婆婆。",
	["tid#dialogueEventDes_26"]="姑苏慕容可是打前朝末期就建立在这千岛湖畔了,那个时候,不少文人为了实现自己的理想去做官,他们大都心高气傲,执着于自己的信念,但是在官场的斗争中是没有什么单纯可言的,他们或者失去了自己的信念,或者隐藏自己了的才华。",
	["tid#dialogueEventDes_27"]="因此杨家的先人杨子敬便建立了相知山庄和微山书院,希望文人们能有个聚集起来畅谈理想、实现抱负的地方。",
	["tid#dialogueEventDes_28"]="后来文人越聚越多,再加上杨家经营有道,因音律而衍生出的武学亦自成一派这微山书院在江湖上声望日渐其高,便索性敞开了大门招收有志入朝为官、辅佐唐王的弟子。如今朝中便有不少为官者是从咱们姑苏慕容走出去的。",
	["tid#dialogueEventDes_29"]="当年九龄公、邠王和姑苏慕容众贤士排除万难,拥佐当今圣上继位,令太平公主一党当权的计谋彻底失败,这大唐才有了如今的盛世。",
	["tid#dialogueEventDes_30"]="那太平公主定不肯就此罢休,难道没有暗中命人谋害姑苏慕容诸位贤良吗?",
	["tid#dialogueEventDes_31"]="别急,婆婆正要说呢。",
	["tid#dialogueEventDes_32"]="那时候咱们老门主杨尹安正带领慕容众人助玄宗皇帝平叛,太平公主一党被剿,但其党羽中的主要势力的两个负责突袭的“云鬓轩”与负责刑讯的“暗军亭”中的数位首脑和高手却在首领解秀朝和年勒的率领下一同杀出重围,逃出了长安,随后伪装成前来拜访的文人悄然进入微山书院,大开杀戒……",
	["tid#dialogueEventDes_33"]="这场战争真是惊心动魄啊……杨老夫人和梅先生重伤我的结发夫君竹先生战死,自此岁寒三友只还有青月那孩子。",
	["tid#dialogueEventDes_34"]="青月？那是何人？",
	["tid#dialogueEventDes_35"]="唉……别说江湖中人了,就是这姑苏慕容中弟子都鲜少听说这个名字。杨青月是杨家大少爷,也本应是杨家这偌大产业的继承人,这代的姑苏慕容门主。",
	["tid#dialogueEventDes_36"]="只因在那一战中,青月中了敌人一招“阴雨针”,虽经杨家秘术《天音知脉》治疗,却仍旧无法挽回。自那时起,青月就时常会陷入浑噩的梦境之中,在外人看来便是神智呆愕了。",
	["tid#dialogueEventDes_37"]="嗯，那难怪只剩青月一人了。",
	["tid#dialogueEventDes_38"]="好了，就说这么多了，关于武学，我倒是可以推荐你去一个地方。你若勇于与他比试一二，定能大有收获。",
	["tid#dialogueEventDes_39"]="何人赴我琼瑶宴？",
	["tid#dialogueEventDes_40"]="在下近日初访姑苏慕容内，拜访了几位长老后，此番是向您虚心求教的。",
	["tid#dialogueEventDes_41"]="#REF!",
	["tid#dialogueEventDes_42"]="哦？求教。哪方面？",
	["tid#dialogueEventDes_43"]="当然是……",
	["tid#dialogueEventDes_44"]="当然是您的青莲剑法啦！众所周知您是文韬武略样样精通。只是小辈我此行是久仰您的青莲剑法，特意来领教一二。",
	["tid#dialogueEventDes_45"]="咳咳……啊青莲啊……",
	["tid#dialogueEventDes_46"]="看剑！！！",
	["tid#dialogueEventDes_47"]="？？？",
	["tid#dialogueEventDes_48"]="……",
	["tid#dialogueEventDes_49"]="……",
	["tid#dialogueEventDes_50"]="……黄河之水~天上来！",
	["tid#dialogueEventDes_51"]="直接跳过了可还行！？",
	["tid#dialogueEventDes_52"]="年轻人，你很有前途。",
	["tid#dialogueEventDes_53"]="我也知道你志不在此，那么等你志得意满，还记得回来跟我喝上一杯。如何？",
	["tid#dialogueEventDes_54"]="君子一言，驷马难追。",
	["tid#dialogueEventDes_55"]="哎……",
	["tid#dialogueEventDes_56"]="怎么。难道是在担心与我比武，输的太难看？",
	["tid#dialogueEventDes_57"]="……",
	["tid#dialogueEventDes_58"]="放心。我只讨教武学，不会伤人，不论时颜面还是身体。",
	["tid#dialogueEventDes_59"]="随你吧，反正我也没什么可以失去的了。",
	["tid#dialogueEventDes_60"]="失去？你失去了什么？",
	["tid#dialogueEventDes_61"]="我失去了……我的羁绊。",
	["tid#dialogueEventDes_62"]="羁绊，那一定是你牵挂很深刻的一位朋友。",
	["tid#dialogueEventDes_63"]="是啊。我们吵了一架，他不告而别，我知道他就在这附近，可我不知道他为什么躲着我。",
	["tid#dialogueEventDes_64"]="不知道？那就去问啊，不闻不问怎么知道他不想见你呢？",
	["tid#dialogueEventDes_65"]="我……",
	["tid#dialogueEventDes_66"]="（我什么我，大老爷们真墨迹）如果公子为难，我可以为公子代劳，只是……",
	["tid#dialogueEventDes_67"]="只是什么？",
	["tid#dialogueEventDes_68"]="公子需要给我一个可以证明身份的信物，我也好为两位传话。",
	["tid#dialogueEventDes_69"]="也好，我手边有这三样可以作为信物，少侠可以自行挑选一个。",
	["tid#dialogueEventDes_70"]="好，我就选这封信了。",
	["tid#dialogueEventDes_71"]="那么有劳少侠，我就在此等候您的回复。多谢。",
	["tid#dialogueEventDes_72"]="是谁？",
	["tid#dialogueEventDes_73"]="兄台好耳力啊。在下是慕容的朋友。",
	["tid#dialogueEventDes_74"]="慕容？我怎么未曾听说他有这样一位陌生朋友。",
	["tid#dialogueEventDes_75"]="我还知道你是八卦，你们最近似乎有些芥蒂。",
	["tid#dialogueEventDes_76"]="你是谁！究竟有什么目的！",
	["tid#dialogueEventDes_77"]="兄台莫要慌张，请看，这是慕容托我带来的信物。（掏出慕容的琴）",
	["tid#dialogueEventDes_78"]="这……",
	["tid#dialogueEventDes_79"]="这下兄台相信我的身份了吧。",
	["tid#dialogueEventDes_80"]="他果然是知道了……但是我又怎会如他所想。",
	["tid#dialogueEventDes_81"]="八卦兄，不是我八卦，而是你得把事情的经过给我讲明白。我也好帮你们调节一下。",
	["tid#dialogueEventDes_82"]="我与慕容自幼相识，只是我身份特殊，而如今，我接到了让我为难的命令。",
	["tid#dialogueEventDes_83"]="命令？在下没猜错的话，这信物就是命令的目标吧。",
	["tid#dialogueEventDes_84"]="只是一部分……所以我才为难。",
	["tid#dialogueEventDes_85"]="论如何，都应该当面说清楚的。",
	["tid#dialogueEventDes_86"]="算了，这琴，你还给他。我在处理好这件事之前还是不要见他了,也不会再……伤害他。",
	["tid#dialogueEventDes_87"]="是谁？",
	["tid#dialogueEventDes_88"]="兄台好耳力啊。在下是慕容的朋友。",
	["tid#dialogueEventDes_89"]="慕容？我怎么未曾听说他有这样一位陌生朋友。",
	["tid#dialogueEventDes_90"]="我还知道你是八卦，你们最近似乎有些芥蒂。",
	["tid#dialogueEventDes_91"]="你是谁！究竟有什么目的！",
	["tid#dialogueEventDes_92"]="兄台莫要慌张，请看，这是慕容托我带来的信物。（掏出慕容的项链）",
	["tid#dialogueEventDes_93"]="这……",
	["tid#dialogueEventDes_94"]="这下兄台相信我的身份了吧。",
	["tid#dialogueEventDes_95"]="这是我与他相识已久的见证，我幼年就带在身边的一颗狼牙，他叫你把这个还给我是……不想再见我了对不对？",
	["tid#dialogueEventDes_96"]="正好相反，慕容兄想要与兄台再见面聊聊。",
	["tid#dialogueEventDes_97"]="可是我现在的身份特殊，而如今，我又接到了让我为难的命令。",
	["tid#dialogueEventDes_98"]="命令？在下没猜错的话，慕容已久知道了八卦兄的身份和任务。",
	["tid#dialogueEventDes_99"]="我也早想过他已经知道了，只是一直在骗自己。却万万没想到他还留着这个狼牙项链，我还以为我们吵过架，他一定会把这个丢了。",
	["tid#dialogueEventDes_100"]="不论如何，都应该当面说清楚的。兴许有其他解决办法呢？",
	["tid#dialogueEventDes_101"]="好吧，你说的确实有理，那么你帮我告诉他，我在这里等他。",
	["tid#dialogueEventDes_102"]="是谁？",
	["tid#dialogueEventDes_103"]="兄台好耳力啊。在下是慕容的朋友。",
	["tid#dialogueEventDes_104"]="慕容？我怎么未曾听说他有这样一位陌生朋友。",
	["tid#dialogueEventDes_105"]="我还知道你是八卦，你们最近似乎有些芥蒂。",
	["tid#dialogueEventDes_106"]="你是谁！究竟有什么目的！",
	["tid#dialogueEventDes_107"]="兄台莫要慌张，请看，这是慕容托我带来的信物。（掏出慕容的信）",
	["tid#dialogueEventDes_108"]="这……",
	["tid#dialogueEventDes_109"]="这下兄台相信我的身份了吧。",
	["tid#dialogueEventDes_110"]="（阅读信……）",
	["tid#dialogueEventDes_111"]="既然是自幼认识的深厚情谊，就应该给彼此足够的信任，俨然慕容已经知晓八卦兄杀手的身份，也已经知道八卦兄的任务目标。",
	["tid#dialogueEventDes_112"]="你看过信了？",
	["tid#dialogueEventDes_113"]="额……这……在下只是觉得应该还有比不辞而别更好的办法。",
	["tid#dialogueEventDes_114"]="见面…还是不必了，办法我来想，我也写一封书信，你替我交给他吧。",
	["tid#dialogueEventDes_115"]="好吧。",
	["tid#dialogueEventDes_116"]="你回来了。见到八卦了吗？",
	["tid#dialogueEventDes_117"]="见到了，只是这信物，他没收下。",
	["tid#dialogueEventDes_118"]="没收？他怎么说？",
	["tid#dialogueEventDes_119"]="八卦兄并不是想要和你永不相见，只是暂时不知道该如何面对你。",
	["tid#dialogueEventDes_120"]="他不是接到任务要拿琴吗？不拿走琴怎么行？",
	["tid#dialogueEventDes_121"]="也可能，八卦兄接到的命令也不只是拿琴这么简单吧。",
	["tid#dialogueEventDes_122"]="所以，我也是目标吗？",
	["tid#dialogueEventDes_123"]="所以他才这么为难。",
	["tid#dialogueEventDes_124"]="这个傻瓜，有什么困难，我和他一起解决不就好了吗！",
	["tid#dialogueEventDes_125"]="我能理解他，他只是不想伤害你。",
	["tid#dialogueEventDes_126"]="可他这样做会伤害自己！我会很愧疚。我如果只是一个目标就好了。",
	["tid#dialogueEventDes_127"]="在下觉得，可能要相信八卦兄的能力。",
	["tid#dialogueEventDes_128"]="他会回来吗？",
	["tid#dialogueEventDes_129"]="他会的。",
	["tid#dialogueEventDes_130"]="你回来了。见到八卦了吗？",
	["tid#dialogueEventDes_131"]="见到了，信物也交给他了。",
	["tid#dialogueEventDes_132"]="他怎么说？",
	["tid#dialogueEventDes_133"]="八卦兄并不是想要和你永不相见，只是暂时不知道该如何面对你。",
	["tid#dialogueEventDes_134"]="所以他还是不肯见我是吗？",
	["tid#dialogueEventDes_135"]="那倒不是，我已经帮你转达了意思。他也同意了见面。",
	["tid#dialogueEventDes_136"]="真的吗！真的非常感谢你了。",
	["tid#dialogueEventDes_137"]="小事。他说他就在那等你。慕容兄准备好了就可以去找他了。",
	["tid#dialogueEventDes_138"]="我这就去找他。",
	["tid#dialogueEventDes_139"]="慢走。",
	["tid#dialogueEventDes_140"]="你回来了。见到八卦了吗？",
	["tid#dialogueEventDes_141"]="见到了，信物也交给他了。",
	["tid#dialogueEventDes_142"]="他怎么说？",
	["tid#dialogueEventDes_143"]="八卦兄并不是想要和你永不相见，只是暂时不知道该如何面对你。",
	["tid#dialogueEventDes_144"]="所以他还是不肯见我是吗？",
	["tid#dialogueEventDes_145"]="对，他说事情他会亲自解决好，再来找你。",
	["tid#dialogueEventDes_146"]="所以还是会见我的是吗？",
	["tid#dialogueEventDes_147"]="是的，那么请慕容兄相信他吧。这是八卦给你留的信。",
	["tid#dialogueEventDes_148"]="（阅读信……）",
	["tid#dialogueEventDes_149"]="在下相信，八卦只是因为不想伤害慕容兄，才避而不见。所以慕容兄只要耐心等待即可。",
	["tid#dialogueEventDes_150"]="好，我等他回来。",
	["tid#MapEventMissionDes_1"]="门外河水旁的张九龄等候你多时，快去找他吧。",
	["tid#MapEventMissionDes_2"]="将物资送给韩非池。",
	["tid#MapEventMissionDes_3"]="找吉婆婆带口信。",
	["tid#MapEventMissionDes_4"]="根据吉婆婆的指导，得知姑苏慕容境内有一个可以讨教的武学泰斗。来的路上听说是李太白，李太白的青莲剑法此时傲视南方。今日与他切磋一二，定能有所成就。",
	["tid#MapEventMissionDes_5"]="去找慕容对话。",
	["tid#MapEventMissionDes_6"]="去找慕容对话。",
	["tid#MapEventMissionDes_7"]="去找慕容对话。",
	["tid#MapEventMissionDes_8"]="去找慕容对话。",
	["tid#MapEventMissionDes_9"]="寻找八卦，传递慕容的信物。",
	["tid#MapEventMissionDes_10"]="寻找八卦，传递慕容的信物。",
	["tid#MapEventMissionDes_11"]="寻找八卦，传递慕容的信物。",
	["tid#MapEventMissionDes_12"]="将八卦的意思传达给慕容。",
	["tid#MapEventMissionDes_13"]="将八卦的意思传达给慕容。",
	["tid#MapEventMissionDes_14"]="将八卦的意思传达给慕容。",
	["tid#MapEventName_1"]="初仰九龄公",
	["tid#MapEventName_2"]="慕容招贤日",
	["tid#MapEventName_3"]="姑苏慕容往事",
	["tid#MapEventName_4"]="武学求教",
	["tid#MapEventName_5"]="八卦之心",
	["tid#MapEventStory_1"]="八音之中，弦声为首。众器之中，琴徳最优。门中人正式操琴，虚的沐浴更衣，焚香拜书。你这边去外面想找寻九龄公了解这些仪式吧，此事向来由九龄公主持的。",
	["tid#MapEventStory_2"]="九龄公临走前给了你一些物资，嘱咐你去拜访一下韩非池，将物资送给韩非池，并向他了解一下最近的招贤日由来。",
	["tid#MapEventStory_3"]="韩非池先生托我找吉婆婆带话，吉婆婆向我介绍了姑苏慕容的建立，以及铲除太平公主的往事。太平公主一党，为此寻仇，偷袭姑苏慕容，谋害了吉婆婆的夫君，重伤门主之子导致其时常呆病发作。",
	["tid#MapEventStory_4"]="找李白讨教一下他的南方第一青莲剑法。",
	["tid#MapEventStory_5"]="慕容此时刚刚与八卦不欢而散，他大概能猜到八卦突然消失的原因，拜托主角询问调查。最终发现八卦作为杀手，收到了暗杀慕容夺取名琴的任务。",
