	["tid#MapEncounterName_63"]="林间秘境·四",
	["tid#MapEncounterName_64"]="林间秘境·五",
	["tid#MapEncounterEvent_103"]="你正走在深林中，忽听得耳边一声虎啸，紧接着平地起了一场大风。一阵飞沙走石之后，面前突然窜出了一直吊睛白额大虫！",
	["tid#MapEncounterEvent_104"]="你正走在路上，忽听得前方一阵喧闹声，往前紧走两步后，发现原来有人在举办比武大会，听说获胜者可以得到丰厚的奖励。",
	["tid#MapEncounterEvent_105"]="你正走在荒郊野岭中，又渴又累，突然间发现前面有间客栈便推门走了进去，刚一开门立马有热情的店小二迎了上来，问道“客官是打尖还是住店啊？”",
	["tid#MapEncounterEvent_106"]="你穿过一个平平无奇的小镇，却发现小镇最高处的房檐上站着一个负剑而立的剑客。",
	["tid#MapEncounterEvent_107"]="在一处山洞深处，你发现了一处密室，室内有三个圆盘形机关，分别写着“无价”“无涯”“无回”。",
	["tid#MapEncounterEvent_108"]="你行至沼泽深处，却突然起了一阵大雾，在雾中摸索行进许久后，你已然迷失了方向，现在在你面前有一个三叉路。",
	["tid#MapEncounterEvent_109"]="你行至一片竹林，忽听得耳边传来一阵悦耳的琴声，琴声峨峨兮若泰山，洋洋兮若江河。循声过去，之间一俊朗的白衣少年盘坐抚琴。少年转头看向你，问道：“少侠可听出我弹得是什么曲子？”",
	["tid#MapEncounterEvent_110"]="你正走来路上，却突然被一名书生模样的人拦住了去路，那少年张口便问“有一美人兮见之不忘，下一句是什么？”",
	["tid#MapEncounterEvent_111"]="你来到一处庄严广大的寺庙，正欲进入内殿却被一个小沙弥拦住了，小沙弥说前方是本寺的机密之地，只开放给有慧根的香客。想要进去的话，必须要回答他的问题。问题是：“佛教所谓的六根中不包含哪个。”",
	["tid#MapEncounterEvent_112"]="你在路边发现了一株枝蔓叶茂，亭亭如盖的巨木，竟有四五人环抱那么粗，看到如此壮阔的景色，你不禁感叹。",
	["tid#MapEncounterEvent_113"]="你走过一片森林，突然听到林中有人呼救，似乎十分危急……",
	["tid#MapEncounterEvent_114"]="你正走在一个普通的村落中，一个乞丐拦住了你的去路，他似乎已经饿得神志不清了，干裂的嘴唇中传出了沙哑的呓语……",
	["tid#MapEncounterEvent_115"]="你走在路上，突然冲出一伙匪徒让你留下买路钱。",
	["tid#MapEncounterEvent_116"]="你眼尖，发现路边草丛里掉了一个包裹，虽然没有打开看，但是凭入手重量，里面应该装了不少金银之物……",
	["tid#MapEncounterEvent_117"]="你正走在雪山脚下，突然听到一阵闷雷般的声音，抬头一看，竟然是发生了雪崩。",
	["tid#MapEncounterEvent_118"]="在这荒郊野外，你居然看到一个美丽女子在路旁哭泣，据说她丢了盘缠正走投无路……",
	["tid#MapEncounterEvent_119"]="行走在僻静之处，不远处的山林间居然有冲天红光，一定有异宝出世！",
	["tid#MapEncounterEvent_120"]="你正在林间行走，突然发现了一条人迹罕至的小路。沿着小路继续往前走了不远，你来到一处幽静的小院，院中端坐着一位仙风道骨的老者，老者抚须一笑说你与他有缘，然后端出了三杯酒让你选一杯喝。",
	["tid#MapEncounterEvent_121"]="路遇大雨，匆忙之间你躲进了一间破庙，破庙中有一座残破的如来佛雕像，如今已经倒在了地上，上面布满了蜘蛛网和灰尘。",
	["tid#MapEncounterEvent_122"]="你行走至一处水潭边，忽然发现水中似乎有什么东西在闪闪发光。",
	["tid#MapEncounterEvent_123"]="你正走在热闹的大街上，突然迎面走来一个衣衫褴褛的小男孩撞了你一下。小男孩一脸惊慌，连声说着“对不起”，跑进了一旁的小巷中，你回过神来才发现，腰间的钱袋被摸走了。",
	["tid#MapEncounterEvent_124"]="你紧随那小男孩进了木屋，正好看到一个黑脸刀疤大汉把那小男孩推到在地上，抢走了钱袋，还要揍那个孩子。",
	["tid#MapEncounterEvent_125"]="你跟随小男孩来到城外的一处破庙，发现这里原来是一处贫民窟，里面住着很多衣衫褴褛，无家可归的孩子。你看到那男孩将钱分给了其他孩子，让他们去买吃的、看病，自己却一点都没有留下。",
	["tid#MapEncounterEvent_126"]="你走进村东头的铁匠铺，却发现店老板正在唉声叹气。询问过后才知道，原来村西头新开了一家铁匠铺，铺中有一柄神兵品质的镇店之宝，凭借着神兵的噱头，将客人都抢走了。",
	["tid#MapEncounterEvent_127"]="为了帮助村东头的铁匠，你来到了后山的矿洞，发现这里果然聚集了大量的盗匪。",
	["tid#MapEncounterEvent_128"]="村里的赵大娘跟你抱怨，最近村口的枯井里老师传出奇怪的声音，还每次都是在半夜中响起，其中还夹杂着女人的惨叫，非常吓人。",
	["tid#MapEncounterEvent_129"]="夜半三更，你下到了王大娘所说的枯井下，却发现枯井之下竟然隐藏着一道石门，将耳朵贴在石门上仔细聆听，果然有奇怪的声音和女人的惨叫！",
	["tid#MapEncounterEvent_130"]="京城中最近出了个义贼叫“燕云三郎”，专门偷窃朝中权贵，劫富济贫。朝廷颜面尽失，于是发下悬赏令，只要有人能捉拿“燕云三郎”，便可领取丰厚的奖赏。",
	["tid#MapEncounterEvent_131"]="追寻着朝廷给予的线索，你成功找到了燕云三郎。",
	["tid#MapEncounterEvent_132"]="在路上闲逛时，你来到了一处杏坛，坛上端坐着一位儒家装扮的老者。老者向你提出了一个问题：“修身、齐家、平天下，你认为最重要的是哪个？”",
	["tid#MapEncounterEvent_133"]="顺着老者所指的方向，你来到了第二处杏坛，坛上端坐着一位儒家装扮的中年男人。中年男人向你提出了第二个问题：“修身、齐家、平天下，你认为最重要的是哪个？”",
	["tid#MapEncounterEvent_134"]="顺着中年男人所指的方向，你来到了第三处杏坛，坛上端坐着一位儒家装扮的少年。少年人向你提出了第三个问题：“修身、齐家、平天下，你认为最重要的是哪个？”",
	["tid#MapEncounterEvent_135"]="你正走在路上，突然被一位少女拦住了去路，她从怀中掏出一封书信，说要你帮他把这封信交给一位少年。",
	["tid#MapEncounterEvent_136"]="你根据少女描绘的形貌，成功找到了哪位少年。那少年似魔怔了一半，一直低头反复喃喃道“有一美人兮见之不忘”",
	["tid#MapEncounterEvent_137"]="你来到一处水边，见到一位剑客这正对着汹涌而来的海浪不住的挥剑，打听过后才知道他原来在练一种能把大海都劈开的剑术。",
	["tid#MapEncounterEvent_138"]="又过了两天，你又在另一处地方偶遇了那位想要斩开大海的剑客，他仍在对着海浪奋力劈砍。",
	["tid#MapEncounterEvent_139"]="又过了两天，你又在另一处地方偶遇了那位想要斩开大海的剑客，此时他已经不再对着海浪劈砍了，而是面对大海负剑而立。",
	["tid#MapEncounterEvent_140"]="你正走在大街上，突然一位算命先生打扮的人将你拦住了，说你近日里必有血光之灾，只有他能救你！",
	["tid#MapEncounterEvent_141"]="你跟随算命先生一路走到了树林深处，正欲开口询问，突然间，从树林两边跳出了四五个彪形大汉将你团团围住。那算命先生扬天大小道：“怎么样，我说你要有血光之灾吧！”",
	["tid#MapEncounterEvent_142"]="你行走在一处山林间，互见路旁有一块石碑，上面写着“欲寻玄机处，需到水中寻。”，又继续往前走了几步后，你遇到了一处岔路。",
	["tid#MapEncounterEvent_143"]="依照石碑的指引，你来到一处院落，半开的屋门上挂着一个木牌，上面写着，“水不在深，有龙则灵。”你在院落中搜索了片刻，找到了几个可疑的地点。",
	["tid#MapEncounterEvent_144"]="依照石碑的指引，你来到了一处寺庙，庙中空无一人，只有一尊庄严的佛像，佛像前摆放有一个蒲团、一个木鱼和一本经书。佛像底座上还刻有一行字，写着“欲入佛门玄秘，需得六根清净”",
	["tid#MapEncounterEvent_145"]="依照石碑的指示，你来到了一颗巨木之下，绕着树转了两圈之后，你再树根处发现一座残破的石板，上面写着“上古之时有大椿，以八千岁为春。”树下放有三个石凳和一方石桌，石凳上分别刻有梅花、菊花、桃花、",
	["tid#MapEncounterEvent_146"]="依照石板的指示，你来到了一处洞窟，洞窟中机关密布，正中央摆放有两个宝箱，分别写着“力量”“财富”",
