	["tid#MapEncounterResult_1"]="那大虫凶狠异常，先发出一声虎啸，震得人心肝俱颤，随后便后足发力，朝你扑了过来。（战斗）",
	["tid#MapEncounterResult_2"]="你刚站上擂台，就看见人群中窜出一个剑客，半空中一个转身，轻飘飘的落上了擂台。剑客冲着你一抱拳，接着便提剑刺了过来。（战斗）",
	["tid#MapEncounterResult_3"]="店小二道一声“好嘞！”然后走向后厨，不一会儿就端着一盘好酒好菜过来了。你端起酒杯刚喝了一口，却突然感到天旋地转。再醒来时，发现已经被扒光丢到了大街上。（一无所获）",
	["tid#MapEncounterResult_4"]="那剑客看了你一眼，低声说了一句“还不到火候。”就飞身跳了下去，两三个呼吸之间已经不见了踪影。（一无所获）",
	["tid#MapEncounterResult_5"]="一阵吱丫丫的齿轮转动声过后，有一件密室的门被打开了，里面摆放着一件武功秘籍，你正想伸手去拿，忽听得一阵破空声袭来！（战斗）",
	["tid#MapEncounterResult_6"]="你选择了左边的道路，又接着走了许久，竟然走到了一处土匪的山寨。土匪们以为是来剿的官兵，不由分说就冲了上来。（战斗）",
	["tid#MapEncounterResult_7"]="那少年仰头大笑，说到：“千金易得，知音难求啊！”然后便随手甩来一个木匣，你打开后发现，里面竟然装满了金银珠宝。（获得奖励）",
	["tid#MapEncounterResult_8"]="那书生摇了摇头，喃喃道“不对不对，不是你不是你”然后就离开了。（一无所获）",
	["tid#MapEncounterResult_9"]="那沙弥摇了摇头说，对不起，施主慧根不够，还是请回吧。（一无所获）",
	["tid#MapEncounterResult_10"]="刚感叹完，突然一阵风吹过，从树冠上掉下一个钱袋子，正落到你的怀中。",
	["tid#MapEncounterResult_11"]="你正准备杀他们一个措手不及，没想到正中圈套，敌人狞笑着向你包围而来……（战斗）",
	["tid#MapEncounterResult_12"]="乞丐突然破口大骂：【我都饿的快死了，你给我钱有什么用？！】说罢夺过你的干粮袋自己吃了起来。（一无所获）",
	["tid#MapEncounterResult_13"]="【对不起，我赶时间】，你扔出一把钱，匪徒忙于捡钱无心挡路，你扬长而去。（一无所获）",
	["tid#MapEncounterResult_14"]="你觉得如此重金一定对失主至关重要，但是你在原地等了两天也不见失主前来，只好自己收下。（获得奖励）",
	["tid#MapEncounterResult_15"]="你转过头就往来时的路上跑，却发现路口被一颗巨石堵上了，而此时你已经错失了逃跑的最佳时机，被大雪掩埋，再醒来时已经在城中的医馆里了。（一无所获）",
	["tid#MapEncounterResult_16"]="美女感谢你的帮助，作为报答，她将家传宝物赠送给你（获得奖励）",
	["tid#MapEncounterResult_17"]="你正准备杀他们一个措手不及，没想到正中圈套，敌人狞笑着向你包围而来……（战斗）",
	["tid#MapEncounterResult_18"]="你喝下一杯女儿红，随后一阵止不住的眩晕感袭来，你倒在地上睡了过去。睡梦中，你似乎见到了一个红衣蹁跹的绝世美女与你对坐而歌，良宵一刻……（一无所获）",
	["tid#MapEncounterResult_19"]="你费尽了九牛二虎之力才将雕像扶起来，还在雕像的身下发现了一个尘封的宝箱。（获得奖励）",
	["tid#MapEncounterResult_20"]="你毫不犹豫，一纵身便跳了下去，在水中摸索了好久，水都弄浑浊了，却始终找不到那个发光的东西。（一无所获）",
	["tid#MapEncounterResult_21"]="你连忙回头紧追了两步，刚好看到那小男孩拐进了一间破木屋中，消失不见了。（一无所获）",
	["tid#MapEncounterResult_22"]="那大汉轻蔑的笑了一声，一吹口哨便招来了四五个彪形大汉将你团团围住。（战斗）",
	["tid#MapEncounterResult_23"]="那群弱不禁风的孩子显然不是你的对手，你三两下就抢回了钱袋离开了。三天后，你听说了一则消息，城外破庙中，有十几个孤儿被饿死了……（一无所获）",
	["tid#MapEncounterResult_24"]="你跑到村西头的铁匠铺看热闹，那宝剑突然发出了一道神秘的霞光，霞光笼罩下，你感觉平日的武学桎梏消散了。（获得奖励）",
	["tid#MapEncounterResult_25"]="你大吼一声冲进了矿洞，矿洞内的盗匪先是被你吓了一跳，然后便叫骂着冲了进来。（战斗）",
	["tid#MapEncounterResult_26"]="赵大娘一拍脑袋说“对呀！我怎么没想到呢！”然后就给了你一些报酬匆匆离开了。（获得奖励）",
	["tid#MapEncounterResult_27"]="你一脚踹开了大门，正撞见一对儿衣衫不整的男女搂抱在一起，原来的村尾潘寡妇和王花匠在幽会。这两人为了封你的口，给了你一大笔钱。（获得奖励）",
	["tid#MapEncounterResult_28"]="你接下了悬赏令，按照线索搜寻了三天三夜，却一无所获。（一无所获）",
	["tid#MapEncounterResult_29"]="燕云三郎本打算辩解，但你已经攻了过来，只好长叹一口气提剑迎战。（战斗）",
	["tid#MapEncounterResult_30"]="老者抚着胡须微笑道“孺子可教”（获得奖励）",
	["tid#MapEncounterResult_31"]="中年人眉头微蹙，摇头叹道“非也非也……”然后便起身离开了。（一无所获）",
	["tid#MapEncounterResult_32"]="少年轻蔑的一笑，道“燕雀焉知鸿鹄之志……”然后便起身离开了。（一无所获）",
	["tid#MapEncounterResult_33"]="少女将少年的形貌描述了一番之后，又给予了你一些报酬就离开了。（获得奖励）",
	["tid#MapEncounterResult_34"]="少年将信展开，刚读了几行便高兴的手舞足蹈！一边高呼：“她原来是这个意思！我明白了！我明白了！”然后便塞给你一个包裹离开了。（获得奖励）",
	["tid#MapEncounterResult_35"]="那剑客被你激怒了，提出要跟你决斗！（战斗）",
	["tid#MapEncounterResult_36"]="那剑客被你激怒了，提出要跟你决斗！（战斗）",
	["tid#MapEncounterResult_37"]="那剑客被你激怒了，提出要跟你决斗！（战斗）",
	["tid#MapEncounterResult_38"]="你听了算命先生的话，给了他10000铜钱破财消灾，果然没有遇到血光之灾。（一无所获）",
	["tid#MapEncounterResult_39"]="你转头想走，却发现来时的路上已经被两个彪形大汉挡住。退无可退，只能迎战了。（战斗）",
	["tid#MapEncounterResult_40"]="往东走了不远，你遇到了一处悬崖，无法再往前走了，只能悻悻而回。（一无所获）",
	["tid#MapEncounterResult_41"]="你从小屋的后门出来，一路上到山顶，却没有任何的收获。",
	["tid#MapEncounterResult_42"]="你盘腿坐在蒲团上，放空大脑，不发出任何声音。约莫过了半柱香后，你听到一阵轰隆隆的声音。睁开眼镜后，你发现佛像被机关移开了，原本的位置上出现了一道暗门，在门中你又发现了一处石碑。",
	["tid#MapEncounterResult_43"]="你坐在了梅花凳子上，刚一坐下，面前的石桌中突然传出了一阵齿轮转动声，桌面突然出现了一个大洞，从洞中缓缓升起了一个宝箱。",
	["tid#MapEncounterResult_44"]="你打开“财富”宝箱，里面是数不尽的金银珠宝。",
	["tid#MapEncounterResult_45"]="你转身就跑，连头都不敢回，一口气跑出了好几个山头才敢停下来。停下后才发现，随身的钱袋竟然跑丢了。(一无所获)",
	["tid#MapEncounterResult_46"]="你站在擂台便看了半天，看到许多高手见的打斗，武学得到了精进。（获得奖励）",
	["tid#MapEncounterResult_47"]="店小二将你引到了一处客房后便退下了。夜半三更，你突然听到门外有响动，刚睁眼，就看到店小二手持一把尖刀正要刺向你的胸口！（战斗）",
	["tid#MapEncounterResult_48"]="那剑客冷哼一声，只伸出两根手指就夹住了你偷袭而来的剑尖，另一只手拔出宝剑，朝你攻来。（战斗）",
	["tid#MapEncounterResult_49"]="一阵吱丫丫的齿轮转动声过后，有一件密室的门被打开了，里面摆放着一箱金银珠宝，你正想伸手去拿，忽听得一阵破空声袭来！（战斗）",
	["tid#MapEncounterResult_50"]="你选择了右边的道路，又接着走了许久，大雾也逐渐散去，你终于逃离了那片沼泽。（获得奖励）",
	["tid#MapEncounterResult_51"]="那少年皱眉低首，摇头叹道“一曲肝肠断，天涯何处觅知音。”然后便收起琴离开了。（一无所获）",
	["tid#MapEncounterResult_52"]="那书生高兴的手舞足蹈，大喊道“找到啦！找到啦！”然后硬塞给你一个包裹就离开了。（获得奖励）",
	["tid#MapEncounterResult_53"]="那沙弥摇了摇头说，对不起，施主慧根不够，还是请回吧。（一无所获）",
	["tid#MapEncounterResult_54"]="感叹的话刚说完，一旁突然冲出来一群手拿草叉、锄头的农民，一边嚷着“不准侮辱神树大人！”一边朝你扑了过来。（战斗）",
	["tid#MapEncounterResult_55"]="你慢慢上前，果然发现这是个引军入瓮的圈套，你戏耍了敌人后扬长而去，念头通达下感觉功力又有精进。（获得奖励）",
	["tid#MapEncounterResult_56"]="乞丐突然破口大骂：【我都饿的快死了，你给我酒有什么用？！】说罢夺过你的干粮袋自己吃了起来，还把你的酒也喝了。（一无所获）",
	["tid#MapEncounterResult_57"]="【我这一拳下去……你们可能会死】，说罢你踢翻了眼前的匪徒……（战斗）",
	["tid#MapEncounterResult_58"]="你发现草丛中压出了一条蹒跚的脚印，还有血迹，追踪之下发现了失主的遗体。埋葬了失主后，你将包裹收入囊中。（获得奖励）",
	["tid#MapEncounterResult_59"]="你没有丝毫犹豫，拔腿就往前跑，左躲右闪之间，你发现了一处山洞，躲过了这场雪崩，还在山洞中发现了一个宝箱。（获得奖励）",
	["tid#MapEncounterResult_60"]="你拒绝帮忙，但是当你走远后发现钱袋已经不翼而飞……（一无所获）",
	["tid#MapEncounterResult_61"]="你本打算避免麻烦绕路而行，没想到迎面遇到一波夺宝者，只能动手自保。（战斗）",
	["tid#MapEncounterResult_62"]="你喝下了一杯千金醉，随后一阵止不住的眩晕感袭来，你倒在地上睡了过去。睡醒过后，你发现身上多了一个钱袋。（获得奖励）",
	["tid#MapEncounterResult_63"]="你双手合十道了声“阿弥陀佛”，并没有什么事发生。（一无所获）",
	["tid#MapEncounterResult_64"]="你没有轻举妄动，又蹲在水边仔细观察，确定好了位置后一个猛子扎进去，成功找到了一个装满金币的宝箱。（获得奖励）",
	["tid#MapEncounterResult_65"]=" 衙门里的差爷根本就不拿正眼看你，你只能自认倒霉，灰溜溜的回去了。（结束）",
	["tid#MapEncounterResult_66"]="那黑脸大汉一愣神，小孩趁机从地上窜起来，一把抢回了钱袋夺门而出，你紧追出去，正看见那小孩往城外逃去了。（一无所获）",
	["tid#MapEncounterResult_67"]="你于心不忍，默默的离开了。三天后的清晨，你推开房门，看到门口放着一个包裹，远比你当时丢的更多。（获得奖励）",
	["tid#MapEncounterResult_68"]="铁匠叹了一口气，说哪那么容易。（一无所获）",
	["tid#MapEncounterResult_69"]="你从乔装打扮了一番，准备偷偷的溜进去，但刚往前走了不远就被发现了，使劲了浑身解数才侥幸逃了出来。（一无所获）",
	["tid#MapEncounterResult_70"]="赵大娘很感谢你，一边提醒着你小心，一边给你指出了枯井的位置。（一无所获）",
	["tid#MapEncounterResult_71"]="你听得脊背发凉，匆匆离开了。（一无所获）",
	["tid#MapEncounterResult_72"]="你找了个人冒充“燕云三郎”，想要骗取赏金。却被六扇识破了，打入了大牢，最后只能画10000铜币将自己赎了出来。（一无所获）",
	["tid#MapEncounterResult_73"]="燕云三郎解释说自己盗窃的对象都是朝中的贪官污吏，偷他们的钱也是为了救济贫民窟中的孩子。于是你心软了，放他走了。燕云三郎替贫民窟的孩子道了谢，并给了你一些谢礼。（获得奖励）",
	["tid#MapEncounterResult_74"]="老者眉头微蹙，摇头叹道“非也非也……”然后便起身离开了。（一无所获）",
	["tid#MapEncounterResult_75"]="中年人仰头大笑道“不错！正该如此！”（获得奖励）",
	["tid#MapEncounterResult_76"]="少年轻蔑的一笑，道“燕雀焉知鸿鹄之志……”然后便起身离开了。（一无所获）",
	["tid#MapEncounterResult_77"]="少女眉头紧蹙，眼神也暗淡无光，然后转身离开了。（一无所获）",
	["tid#MapEncounterResult_78"]="你眼看着少年一边不停的喃喃着，一边从你身边走过，似乎根本就没有看到你。（一无所获）",
	["tid#MapEncounterResult_79"]="那剑客说他现在还练的不到火候，要你过两天再来找他。（一无所获）",
	["tid#MapEncounterResult_80"]="那剑客说他现在还练的不到火候，要你过两天再来找他。（一无所获）",
	["tid#MapEncounterResult_81"]="那剑客道了一声好！然后提剑来战！（战斗）",
	["tid#MapEncounterResult_82"]="算命先生一时语塞，一边摇头一边嘟囔着“血光之灾”就离开了。（一无所获）",
	["tid#MapEncounterResult_83"]="你扯开嗓子大声呼救，几个呼吸之后，一道白色的身影突然从林中窜出，几个闪转腾挪之间，已经将贼人尽数打倒在地，并将你护送回了城中。（获得奖励）",
	["tid#MapEncounterResult_84"]="往西走了不远，你突然遇到了一伙劫匪。（战斗）",
	["tid#MapEncounterResult_85"]="你进入了屋内的密道，一路下到最深处，最后在尽头处发现了一个宝箱。",
	["tid#MapEncounterResult_86"]="你拿过木鱼敲击起来，但过了好半天却没有发生任何事。",
	["tid#MapEncounterResult_87"]="你坐在了菊花凳子上，刚一坐下，面前的石桌中突然传出了一阵齿轮转动声，桌面突然出现了一个大洞，从洞中缓缓升起了一本秘籍。",
	["tid#MapEncounterResult_88"]="你打开“力量”宝箱，里面是数本武林前面呕心沥血写就的武学经验。",
	["tid#MapEncounterResult_89"]="你刚开口叫喊，呼救声却被那大虫的一声虎啸盖了过去，再想呼救时，那大虫已经扑了过来。（战斗）",
	["tid#MapEncounterResult_90"]="你转身离开了，无视身后的喧嚣，独自美丽……（一无所获）",
	["tid#MapEncounterResult_91"]="眼前的客栈普通又平凡，但你却感觉到了一丝不对劲，思虑再三后，你还是转身离开了。（一无所获）",
	["tid#MapEncounterResult_92"]="那剑客大量了你一眼，说道“也罢，那就用两分力吧。”随后便提剑做出了迎战姿态。（战斗）",
	["tid#MapEncounterResult_93"]="一阵吱丫丫的齿轮转动声过后，有一件密室的门被打开了，里面空无一物，只有一个巨大的机关人偶。正疑惑间，那人偶已经活了过来，手持利剑向你扑来。（战斗）",
	["tid#MapEncounterResult_94"]="你选择了前方的道路，深一脚浅一脚的走着。突然你被一截倒下的绊倒了，正欲将其搬开，却发现那原来不是木头，而是一条巨蟒！（战斗）",
	["tid#MapEncounterResult_95"]="那少年皱眉低首，摇头叹道“一曲肝肠断，天涯何处觅知音。”然后便收起琴离开了。（一无所获）",
	["tid#MapEncounterResult_96"]="那书生也不生气，转身就找下个人去了。（一无所获）",
	["tid#MapEncounterResult_97"]="你回答对了沙弥的问题，成功进去了，在其中发现了很多典藏的佛门典籍，获益良多。（获得奖励）",
	["tid#MapEncounterResult_98"]="你费劲九牛二虎之力终于爬上了树顶，看到了前所未见的壮阔景象，武学进境也有所提升。（获得奖励）",
	["tid#MapEncounterResult_99"]="你正想转身离开，没想到后路已经被贼人包抄，只能动手了……（战斗）",
	["tid#MapEncounterResult_100"]="乞丐恢复了神志，眼中放出摄人的精光，他手一挥，你感觉凭空增加了很多功力……（获得奖励）",
	["tid#MapEncounterResult_101"]="三十六计走为上，你看准人少的方向拔腿便跑，很快就冲出了重围。（一无所获）",
	["tid#MapEncounterResult_102"]="人不为己天诛地灭，你刚打算把金银收下，失主就带着兄弟们找了回来，不由分说拔刀便砍……（战斗）",
	["tid#MapEncounterResult_103"]="你运气内力护住全身，想要硬抗下这波雪崩，但这雪崩的威力远远超出了你的预料。你两眼一黑晕了过去，再醒来是是在城中的医馆里。（一无所获）",
	["tid#MapEncounterResult_104"]="你正欲顺便劫个色，但是走近一看女子已如幽魂般消失不见，你不禁出了一身冷汗……（一无所获）",
	["tid#MapEncounterResult_105"]="你亲眼看着4波人马杀得天昏地暗，最后成功者也匆匆而去，而你搜捡尸体小赚了一笔……（获得奖励）",
	["tid#MapEncounterResult_106"]="你喝下了一杯剑气生，随后一阵止不住的眩晕感袭来，你倒在地上睡了过去。睡醒过后，你发现自己的的内力涨了一大截。（获得奖励）",
	["tid#MapEncounterResult_107"]="清理佛像上的蜘蛛网时，你的手却不小心被蜘蛛咬了一口。回去之后，你逐渐感觉身体中觉醒了一股力量，内力得到了精进。（获得奖励）",
	["tid#MapEncounterResult_108"]="你找来了一个熟悉水性的帮手，那帮手一个猛子扎下去，却始终不见上来，又过了一会儿之后，那个发光的东西也消失不见了……（一无所获）",
	["tid#MapEncounterResult_109"]="人群中突然窜出了一位形貌俊朗的白衣侠客。只见他施展轻功，三两下就追上了那个小男孩，帮你夺回了钱袋。（获得奖励）",
	["tid#MapEncounterResult_110"]="那大汉将男孩揍了个半死，然后从后门离开了，你追出去时，却怎么也找不到大汉的身影了。（一无所获）",
	["tid#MapEncounterResult_111"]="你走进破庙，将身上的钱财都给了孩子们。孩子们很高兴，邀请你一起吃了晚饭。吃饭时你不经意间抬头看，发现破庙墙壁上竟然有前辈刻的武学感悟！（获得奖励）",
	["tid#MapEncounterResult_112"]="铁匠听闻你的话后又气又恼，不由分说把你赶走了。（一无所获）",
	["tid#MapEncounterResult_113"]="你先在矿洞外不远大汉“官兵来啦！”把洞中的劫匪吸引了出来，然后成功溜了进去。不仅获得了矿石，还获得了铁匠的谢礼！（获得奖励）",
	["tid#MapEncounterResult_114"]="赵大娘叹了一口气说：“忙……都忙……忙点好啊……”然后就离开了。（一无所获）",
	["tid#MapEncounterResult_115"]="你冲着门口大喊一声：“什么人在装神弄鬼！”听到声音后，里面的惨叫声戛然而止，你随后进入了石门，只发现了几件遗落的衣衫。（一无所获）",
	["tid#MapEncounterResult_116"]="你认为“燕云三郎”的行为乃是侠义，拒绝了悬赏令。第二天早上，你再门口发现了一个装满金币的包裹，上书“赠侠义之君——燕云三郎”（获得奖励）",
	["tid#MapEncounterResult_117"]="燕云三郎说这样提心吊胆的日子，他一个人过就够了，拒绝了你。但还是对你的侠义表示肯定，给予了你一些谢礼。（获得奖励）",
	["tid#MapEncounterResult_118"]="老者眉头微蹙，摇头叹道“非也非也……”然后便起身离开了。（一无所获）",
	["tid#MapEncounterResult_119"]="中年人眉头微蹙，摇头叹道“非也非也……”然后便起身离开了。（一无所获）",
	["tid#MapEncounterResult_120"]="少年激动的站起身来，一边踱步一边高呼道：“男儿何不带吴钩，收取关山五十州！”言罢便丢下一个包裹离开了。（获得奖励）",
	["tid#MapEncounterResult_121"]="",
	["tid#MapEncounterResult_122"]="",
	["tid#MapEncounterResult_123"]="你再旁白观摩了一会，觉得他的剑法果然十分精神，武学也大有精进。（获得奖励）",
	["tid#MapEncounterResult_124"]="你再旁白观摩了一会，觉得他的剑法果然十分精神，武学也大有精进。（获得奖励）",
	["tid#MapEncounterResult_125"]="等了约莫有半柱香的功夫，那剑客眼中突然精光一闪，以肉眼难以看到的速度，冲着大海挥出了一剑，紧接着一股巨大的剑气向前飞射而出，硬生生将大海分成两半，数秒钟都未闭合。你观次当世无匹的剑术，感悟良多！（获得奖励）",
	["tid#MapEncounterResult_126"]="见你将信将疑，算命先生提出带你去看证据，就在不远处的树林里。（一无所获）",
	["tid#MapEncounterResult_127"]="你毫不畏惧，主动迎战，敌人也被你的气势吓了一跳，竟有些畏缩。（战斗）",
	["tid#MapEncounterResult_128"]="往北走了不远，你遇到了第二块石碑，石碑刻画的似乎是一个地点。（获得奖励）",
	["tid#MapEncounterResult_129"]="你一个猛子扎进了水井，在井底发现了第三个石碑，石碑上又刻着一个地点。",
	["tid#MapEncounterResult_130"]="你拿过经书仔细阅读，只觉得书中所讲高深莫测，自身的内力也得到了提升。",
