	["tid#BountyQuestName1079"]="剑道独尊",
	["tid#BountyQuestText3021"]="你的师傅最近对你很满意，要你向其他师弟传授一下心得",
	["tid#BountyQuestText3022"]="几个门派之间举行弟子大比，师傅要你参加。",
	["tid#BountyQuestText3023"]="你的师傅觉得你已经可以出师了，给了你一个最终的考验让你完成。",
	["tid#BountyQuestText3024"]="江湖中最近出了一个臭名昭著的大盗，师傅要你和他一起前往捉拿。",
	["tid#BountyQuestText1031"]="你从姑苏慕容附近的酒馆中得知了一个情报，说三天之后，江湖中将有异宝现世。",
	["tid#BountyQuestText1032"]="从酒馆出来，你突然听到一声大喊“抓贼啊！”，原来是有人偷东西！",
	["tid#BountyQuestText1033"]="小偷最终还是跑掉了，但在逃跑过程中却掉落了一个藏宝图，你觉得前往藏宝图上记录的地点。",
	["tid#BountyQuestText1034"]="来到了藏宝图上记录的地点，你发现这里原来是一个机关密布的山洞。",
	["tid#BountyQuestText1035"]="你在山洞深处发现了一扇门，但却上了锁，需要在四周找找有没有钥匙。",
	["tid#BountyQuestText1036"]="你前进的路上有一处非常危险的机关，需要耗费一些时间破解机关才能继续前进",
	["tid#BountyQuestText1037"]="破解了重重机关，你终于来到了宝物面前，却发现有人已经捷足先登了！必须要夺回来！",
	["tid#BountyQuestText1038"]="近日稻香村周边匪患四起，村长向你发来了求助。",
	["tid#BountyQuestText1039"]="前往稻香村后山的土匪营寨，救出被抓走的村民",
	["tid#BountyQuestText1040"]="前往稻香村后山的土匪营寨，夺回被土匪们抢走的物资。",
	["tid#BountyQuestText1041"]="前往稻香村村口的道路，清理土匪们设下的路障。",
	["tid#BountyQuestText1042"]="营地内的土匪们似乎刚举办过庆功宴，都喝的倒在地上呼呼大睡，正是下手的好时候",
	["tid#BountyQuestText1043"]="清理路障时，你遇上了巡逻的土匪斥候。",
	["tid#BountyQuestText1044"]="土匪首领被你这段时间的所作所为彻底激怒了，集结所有手下准备踏平稻香村，必须要前往守卫。",
	["tid#BountyQuestText1045"]="一个面容悲戚的少年找上门来，说他的父母被人杀害了，想要你帮他查出凶手。",
	["tid#BountyQuestText1046"]="一番调查后，你发现凶手不仅是朝廷中的权贵，还是外家拳的高手。少年提出要你教他武功，亲手打败仇人。",
	["tid#BountyQuestText1047"]="一番调查后，你发现凶手不仅是朝廷中的权贵，还是外家拳的高手。为了找到下手机会，必须先收集情报。",
	["tid#BountyQuestText1048"]="少年一心复仇，进境神速。但要击破外家拳的防御，还需要一件趁手的兵器。",
	["tid#BountyQuestText1049"]="你从姑苏慕容附近的酒馆中得知了一个情报，说三天之后，江湖中将有异宝现世。",
	["tid#BountyQuestText1050"]="那位权贵将于今天晚上举办寿宴，正是绝佳的下手机会，但进入宴会需要请柬，必须要想想办法。",
	["tid#BountyQuestText1051"]="那位权贵将于今天晚上举办寿宴，正是绝佳的下手机会，但宴会中有许多守卫在把守，必须想办法绕开。",
	["tid#BountyQuestText1052"]="那位权贵将于今天晚上举办寿宴，正是绝佳的下手机会，按照计划，你们要潜伏在卧房之中，等待仇人的到来。",
	["tid#BountyQuestText1053"]="少年如愿手刃了仇敌，但那权贵临死的哀嚎却惊动了院中的守卫，必须要尽快逃离这个地方。",
	["tid#BountyQuestText1054"]="敌人最近频频侵扰边境，朝廷发布了最新的悬赏令，号召江湖义士前往抵御。",
	["tid#BountyQuestText1055"]="前线的粮草储备已经所剩无几了，需要尽快运送新的粮草。",
	["tid#BountyQuestText1056"]="在敌人的频繁侵扰下，许多城防工事都被破坏了，需要尽快修复。",
	["tid#BountyQuestText1057"]="大战将近，但军队的士气却在敌人的频繁侵扰下有些低迷，急需人来鼓舞军队士气。",
	["tid#BountyQuestText1058"]="敌人的大军已经集结于城下，守城大战一触即发。",
	["tid#BountyQuestText1059"]="守城战大胜！我军决定乘胜追击，一举击垮敌方左军。",
	["tid#BountyQuestText1060"]="守城战大胜！我军决定乘胜追击，一举击垮敌方右军。",
	["tid#BountyQuestText1061"]="守城战大胜！我军决定乘胜追击，一举击垮敌方中军的主力部队！",
	["tid#BountyQuestText1062"]="在我方将士的奋勇冲锋下，敌军节节败退，溃不成军。乘次机会，一鼓作气歼灭敌军，永绝后患！",
	["tid#BountyQuestText1063"]="近几日来，江湖中频繁发生失踪案，你受邀前往调查。",
	["tid#BountyQuestText1064"]="调查过程中，突然又有一个少女失踪了，趁着现场还未被破坏，尽快前往调查。",
	["tid#BountyQuestText1065"]="调查过程中，突然又有一个少年失踪了，趁着现场还未被破坏，尽快前往调查。",
	["tid#BountyQuestText1066"]="调查了一番之后，你发现了每个失踪现场都留下了一个奇怪的，意义不明的图案，必须想办法弄清楚。",
	["tid#BountyQuestText1067"]="一番调查之后，你发现了一些蛛丝马迹，但要到达事情的真相，还需要更多的线索。",
	["tid#BountyQuestText1068"]="查询了许多资料之后，却仍然找不到那个奇怪图案的信息。你只能求助于江湖中见多识广的老前辈。",
	["tid#BountyQuestText1069"]="又收集了许多线索之后，你终于弄清楚了案件的缘由，竟是一个早已消失的魔教门派又复苏了！",
	["tid#BountyQuestText1070"]="询问前辈过后，你终于知道了，原来那个图案是一门邪教功法的经脉运行图。",
	["tid#BountyQuestText1071"]="整件事情已经完全清楚了，原来失踪的人们都是被复苏的魔教门派掳走的。魔教中人想要借此修炼邪功扰乱江湖秩序！如此邪恶所为，必须全力阻止！",
	["tid#BountyQuestText1072"]="江湖中正在举行剑道大会，只要通过入场试炼的侠客皆可参加，最终的胜者可获得名剑山庄所铸的一柄宝剑。",
	["tid#BountyQuestText1073"]="在剑道大会中击败慕容",
	["tid#BountyQuestText1074"]="在剑道大会中击败天策",
	["tid#BountyQuestText1075"]="在剑道大会中击败唐门",
	["tid#BountyQuestText1076"]="在剑道大会中击败嵩山",
	["tid#BountyQuestText1077"]="在剑道大会中击败峨眉",
	["tid#BountyQuestText1078"]="在剑道大会半决赛中击败纯阳",
	["tid#BountyQuestText1079"]="在剑道大会决赛中击败华山",
