	["tid#prestigename_1"]="碌碌无为",
	["tid#prestigename_2"]="小有名声",
	["tid#prestigename_3"]="声名鹊起",
	["tid#prestigename_4"]="家喻户晓",
	["tid#prestigename_5"]="威震一方",
	["tid#prestigename_6"]="名扬四海",
	["tid#prestigename_7"]="武林泰斗",
	["tid#prestigename_8"]="江湖至尊",
	["tid#ArticleDes111001"]="一号包子",
	["tid#ArticleDes111002"]="二号包子",
	["tid#ArticleDes111003"]="三号包子",
	["tid#ArticleDes111004"]="四号包子",
	["tid#ArticleDes111005"]="五号包子",
	["tid#RegionalNpcName_111001"]="说书先生",
	["tid#RegionalNpcName_111002"]="旁白",
	["tid#RegionalNpcName_111003"]="贾万贯",
	["tid#RegionalNpcName_111004"]="柳萦",
	["tid#RegionalEventDes_11101"]="难难难，道德玄，不对知音不可谈，对了知音谈几句，不对知音枉费舌尖！",
	["tid#RegionalEventDes_11102"]="“啪——！”惊堂木拍下，茶馆中旋即雅雀无声。",
	["tid#RegionalEventDes_11103"]="诸位明公细听，今天咱们这场书啊，说的是“女魍魉现身黑风地，土财主怪病散千金”！",
	["tid#RegionalEventDes_11104"]="却说这百里茶铺往东三十里，有一处黑风林，林间草木茂盛，走兽众多，不少樵夫和猎户都以此地为生。",
	["tid#RegionalEventDes_11105"]="但半个月前，黑风林突然起了一场大雾，一直到现在都没散……",
	["tid#RegionalEventDes_11106"]="……于是就有人传言啊，这黑风林原本是一处乱葬岗，阴气郁结良久，化成了一个女鬼……",
	["tid#RegionalEventDes_11107"]="凡是见到女鬼的人，都会被这个女鬼诅咒，轻则身染怪病，重则伤筋断骨，连小命都有可能保不住。",
	["tid#RegionalEventDes_11108"]="往近了说吧，就说这三天以前，香梅镇上的土财主——贾万贯，就碰上了女鬼，至今怪病缠身，千金散尽都没有治好。",
	["tid#RegionalEventDes_11109"]="这其中缘由啊，您听我细细道来……",
	["tid#RegionalEventDes_11110"]="少侠找我有何事？",
	["tid#RegionalEventDes_11111"]="唉……还谈什么生意，我现在这身体，别说生意了，能不能活过这个冬天都不一定啊……",
	["tid#RegionalEventDes_11112"]="治病？唉……算了吧，我早就明白了，我这不是病，是诅咒，那个女鬼的诅咒……",
	["tid#RegionalEventDes_11113"]="自从三天前我在黑风林遇见女鬼之后，我就已经被诅咒了，如今手足无力，茶饭不思，双目无神，夜不能寐，简直如行尸走肉一般。",
	["tid#RegionalEventDes_11114"]="既然是诅咒，那把女鬼除掉不就行了？",
	["tid#RegionalEventDes_11115"]="哪那么容易，前前后后有好几拨人动过这个念头了，但自打进了那黑风林，就在没出现过，如今那黑风林就如同阎罗殿一般，没人敢去啦、",
	["tid#RegionalEventDes_11116"]="那不如你告诉我你遇见女鬼的位置，我去帮你除掉她。",
	["tid#RegionalEventDes_11117"]="少侠有此侠义心肠自是好的，但那日我受了惊吓后，连东南西北偶读分不清了吗，倒是同行里还有一位侠客，叫做柳萦，如今应该也在香梅镇上，少侠不如去找她问问吧。",
	["tid#RegionalEventDes_11118"]="呦，好俊俏的少侠，来找我有什么事吗？",
	["tid#RegionalEventDes_11119"]="镇上的贾万贯说，前几日他遇上“女鬼”的时候，你也在场？",
	["tid#RegionalEventDes_11120"]="一上来就说正事啊，真没有情调。",
	["tid#RegionalEventDes_11121"]="人命关天，姑娘还是别难为在下了。",
	["tid#RegionalEventDes_11122"]="对对对，人命关天，但是不管我的事啊。",
	["tid#RegionalEventDes_11123"]="我知道你的目的，不就是想知道位置，去除掉那个“女鬼”吗？我可以告诉你，但要按照我的规矩来。",
	["tid#RegionalEventDes_11124"]="什么规矩？",
	["tid#RegionalEventDes_11125"]="走吧，跟我去厨房。",
	["tid#RegionalEventDes_11126"]="看到了吗，这蒸笼里有五个包子，其中只有一个是肉馅的，你要做的就是从这些包子中找出肉馅的包子，然后吃下去。",
	["tid#RegionalEventDes_11127"]="只有一个？那其他的呢？都是什么馅的?",
	["tid#RegionalEventDes_11128"]="那可就多了，竹叶青、鹤顶红、断肠散、半步颠，每一种都是我精心调配的，保证你吃了之后啊……呵呵",
	["tid#RegionalEventDes_11129"]="当然了，向你这样俊俏的少侠，是可以给一些优待的，每个包子下面，我都放了一个提示，不过嘛……",
	["tid#RegionalEventDes_11130"]="不过什么？",
	["tid#RegionalEventDes_11131"]="不过，这些提示里只有一句是真话哟，你可要动动脑子了。",
	["tid#RegionalEventDes_11132"]="包子下面压着一张纸条，上面写着：三号包子里是鹤顶红",
	["tid#RegionalEventDes_11133"]="包子下面压着一张纸条，上面写着：五号包子里不是断肠散",
	["tid#RegionalEventDes_11134"]="包子下面压着一张纸条，上面写着：这个包子里不是鹤顶红",
	["tid#RegionalEventDes_11135"]="包子下面压着一张纸条，上面写着：这个包子里不是肉",
	["tid#RegionalEventDes_11136"]="包子下面压着一张纸条，上面写着：二号包子里是竹叶青",
	["tid#RegionalEventDes_11137"]="你一口咬下包子，入口是一股奇怪又辛辣的液体，紧接着腹部便传来一阵剧痛，你一头晕了过去。",
	["tid#RegionalEventDes_11138"]="你一口咬下包子，入口是鲜美的肉味。将包子吃完后，也没有感到任何的不适。",
	["tid#RegionalEventDes_11139"]="怎么样，我亲手做的包子味道还不错吧。",
	["tid#RegionalEventDes_11140"]="算你这家伙命大，这都被你找到了。",
	["tid#RegionalEventDes_11141"]="多谢了，告辞。",
	["tid#RegionalEventDes_11142"]="吃干抹净就走了啊，真是个小没良心的。",
	["tid#RegionalEventDes_11143"]="风情万种的老板娘，胆敢开口调戏她的人都已经永远开不了口了。",
	["tid#RegionalEventDes_11144"]="酒馆中的说书人，眼神中似乎蕴藏着与年纪不符的睿智。",
	["tid#RegionalEventDes_11145"]="曾经富甲一方的商人，如今似乎生了病，一副虚弱的样子。",
	["tid#RegionalEventDes_11146"]="看起来普普通通的包子，只有吃下去才能知道是什么馅的。",
	["tid#RegionalEventDes_11147"]="先是肚子里钻心的痛，紧接着你会感到一阵无法抵挡的眩晕，最后你会四肢无力，再最后……",
	["tid#RegionalEventDes_11148"]="不过放心，我可舍不得你这张俊俏的小脸，好好睡一觉吧，第二天醒来就会好了。",
	["tid#RegionalEventDes_11149"]="你眼前一黑，晕了过去。",
	["tid#RegionalEventDes_11150"]="怎么样，我亲手做的包子味道还不错吧。",
	["tid#RegionalEventDes_11151"]="喏，遇见女鬼的地点我已经标在这个地图上了，拿去吧。",
	["tid#RegionalEventDes_11152"]="多谢了，告辞。",
	["tid#RegionalEventDes_11153"]="吃干抹净就走了啊，真是个小没良心的。",
	["tid#RegionalEventDes_11154"]="好吧，谁让我心软呢。放心好了，我可舍不得你这张俊俏的小脸，好好睡一觉吧，第二天醒来就会好了。",
	["tid#ArticleOptionDes_11101"]="我来找你谈一笔生意",
