	["tid#NewBountyDes_125"]="星宿听闻你的门派实力大增，向你提出了一个考验。",
	["tid#NewBountyDes_126"]="唐门听闻你的门派实力大增，向你提出了一个考验。",
	["tid#NewBountyDes_127"]="剑仙“太白”的秘籍出现在了江湖中，整个江湖的剑客都前往争抢。",
	["tid#NewBountyDes_128"]="一位神秘高手约你在紫禁之巅决战，并以家传宝物作为赌注。",
	["tid#NewBountyDes_129"]="扬州城外的一处山谷中今日总有异光出现，江湖传言说可能会有异宝现世。",
	["tid#NewBountyDes_130"]="江湖中传言有一处“舍身崖”，悬崖下隐居着一位绝世高手。",
	["tid#NewBountyDes_131"]="有人在山中发现了一座神秘的洞窟，洞窟石壁上刻有奇怪的壁画。",
	["tid#NewBountyDes_132"]="稻香村中突发瘟疫，超过半数村民都身染重疾，需要尽快救治。",
	["tid#NewBountyDes_133"]="欧冶子今日要开炉铸造一件绝世神兵，但尚缺一块陨铁作为材料。",
	["tid#NewBountyDes_134"]="悬空寺中的佛祖雕像内总是传出钟声，寺中僧人言说是佛祖显灵。",
	["tid#NewBountyDes_135"]="江湖传言林海之中有一异兽现世，其皮毛可以制成神器级别的防具。",
	["tid#NewBountyDes_136"]="西部荒野出现了至阴信徒的踪迹，据说有一位骑白马的大侠出现……",
	["tid#NewBountyDes_137"]="欲成当世大侠，需行侠客之路……",
	["tid#NewBountyDes_138"]="海外突然出现了一座云雾缭绕的小岛，江湖中人都是是传说中的蓬莱仙岛……",
	["tid#NewBountyDes_139"]="失传已久的玄机卷轴现身江湖，据说解开卷轴的人可以获得富可敌国的宝藏。",
	["tid#NewBountyDes_140"]="江湖中有一座废弃的青龙遗迹，据说其中沉睡着曾经纵横江湖的机关兽——青龙",
	["tid#NewBountyDes_141"]="江湖中有一座废弃的白虎遗迹，据说其中沉睡着曾经纵横江湖的机关兽——白虎",
	["tid#NewBountyDes_142"]="江湖中有一座废弃的玄武遗迹，据说其中沉睡着曾经纵横江湖的机关兽——玄武",
	["tid#NewBountyDes_143"]="江湖中有一座废弃的朱雀遗迹，据说其中沉睡着曾经纵横江湖的机关兽——朱雀",
	["tid#NewBountyDes_144"]="天机楼中据传有一处隐藏的区域，可以再其中接受金之试炼，迅速提高武学进境。",
	["tid#NewBountyDes_145"]="天机楼中据传有一处隐藏的区域，可以再其中接受木之试炼，迅速提高武学进境。",
	["tid#NewBountyDes_146"]="天机楼中据传有一处隐藏的区域，可以再其中接受水之试炼，迅速提高武学进境。",
	["tid#NewBountyDes_147"]="天机楼中据传有一处隐藏的区域，可以再其中接受火之试炼，迅速提高武学进境。",
	["tid#NewBountyDes_148"]="江湖中举办论剑大会，会上的胜者可以获得丰厚的奖励。",
	["tid#NewBountyDes_149"]="终于发现了魔教总坛，需要集结正道中的有识之士前往讨伐。",
	["tid#NewBountyDes_150"]="魔教突袭正道宗门，必须要立即前往救援。",
	["tid#MapEncounterEvent_147"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“画时圆，写时方，冬时短，夏时长”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_148"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“古月照水水长流，水伴古月度春秋。留得水光昭古月，碧波深处好泛舟。”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_149"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“偶因一语蒙抬举，反被多情又别离。送得郎君归去也，倚门独自泪淋漓。”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_150"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“若教有口便哑，且要无心为恶。中间全没肚肠，外面强生棱角。”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_151"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“一月又一月，两月共半边。上有可耕之田，下有长流之川。一家有六口，两口不团圆。”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_152"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“半边有毛半边光，半边有味半边香，半边吃的山上草，半边还在水里藏。”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_153"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“头如刀。尾如钩。中央横广。四角六抽。右面负两刃。左边双属牛”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_154"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“干之一九。 只立无偶。 坤之二六。 宛然双宿”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_155"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“解落三秋叶，能开二月花。过江千尺浪，入竹万竿斜。”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_156"]="一位背着几个箱子的奇怪男人突然拦住了你的去路，低沉着嗓音说道“何人经商出远门，河水奔流不见影。 千柯木材火烧尽，百舸争流舟自沉。”，言罢便把怀中的箱子递到了你面前，每个箱子上都写有不同的字。",
	["tid#MapEncounterEvent_157"]="你路过一处荒郊野岭，突然听到有人呼救，你打算怎么做？",
	["tid#MapEncounterEvent_158"]="你正走在深林中，忽听得耳边一声虎啸，紧接着平地起了一场大风。一阵飞沙走石之后，面前突然窜出了一直吊睛白额大虫！",
	["tid#MapEncounterEvent_159"]="你正走在路上，忽听得前方一阵喧闹声，往前紧走两步后，发现原来有人在举办比武大会，听说获胜者可以得到丰厚的奖励。",
	["tid#MapEncounterEvent_160"]="你穿过一个平平无奇的小镇，却发现小镇最高处的房檐上站着一个负剑而立的剑客。",
	["tid#MapEncounterEvent_161"]="你行走在一处荒郊野岭，突然从路两旁窜出几个黑影将你围了起来，原来是劫道的土匪，你准备怎么做？",
	["tid#MapEncounterEvent_162"]="京城中最近出了个义贼叫“燕云三郎”，专门偷窃朝中权贵，劫富济贫。朝廷颜面尽失，于是发下悬赏令，只要有人能捉拿“燕云三郎”，便可领取丰厚的奖赏。",
	["tid#MapEncounterEvent_163"]="你正坐在一处酒馆中喝酒，忽然推门走进来几个东瀛人，略通东瀛话的你听到他们谈话间似乎有“商船”“突袭”“计划”之类的词语，你打算怎么做？",
	["tid#MapEncounterEvent_164"]="你正走在荒郊野岭中，又渴又累，突然间发现前面有间客栈便推门走了进去，刚一开门立马有热情的店小二迎了上来，正欲坐下吃饭时，你突然味道一股淡淡的血腥味，似乎是从后厨传来的。",
	["tid#MapEncounterEvent_165"]="你正行走在僻静之处，不远处的山林间突然发出冲天红光，一定有异宝出世！",
	["tid#MapEncounterEvent_166"]="你眼尖，发现路边草丛里掉了一个包裹，虽然没有打开看，但是凭入手重量，里面应该装了不少金银之物……",
	["tid#MapEncounterEvent_167"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身华山派的宁不凡大侠,曾三次下山,习得了三式剑法.在座的可有人知道他习得的第三式剑法叫什么?”",
	["tid#MapEncounterEvent_168"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身花间派的苏婉仪侠女,曾与一位得道高僧一起对抗妖僧解救人质,可有人知道那位得道高僧的名字?”",
	["tid#MapEncounterEvent_169"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身恒山派的辛晓风侠女,虽是尼姑出身,却有一头乌黑柔顺的秀发,在座的可有人知道她这一头秀发代表的意义?”",
	["tid#MapEncounterEvent_170"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身少林派的清觉高僧,乃是少林寺建寺以来最年轻的住持,而在其年轻时,曾有过一位一直关照他,但最后却走上邪路的师兄,可有人知是谁?”",
	["tid#MapEncounterEvent_171"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身药王谷的张景琦大侠,乃是世间少有的医中圣手,而在其游历大陆期间,在一处山上遇到过鬼谷先生,可有人知道那座山的名字?”",
	["tid#MapEncounterEvent_172"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身九黎族的筱九侠女,随身相伴着一只通灵的白猫,可有人知道那白猫的名字?”",
	["tid#MapEncounterEvent_173"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身六扇门的李延广大侠,在其二十一生日时,父亲曾送给他一个礼物,可有人知道那礼物是什么?”",
	["tid#MapEncounterEvent_174"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身天师门的张天昊大侠,在其年幼时曾见过一位来龙虎山问道的道人,可有人知道那位道人的道号?”",
	["tid#MapEncounterEvent_175"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身墨家的郑可可侠女,是机关术一道千年一遇的奇才.她的代步工具便是用机关术制成的机关人,而这个机关人的名字,可有人知道?”",
	["tid#MapEncounterEvent_176"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身太极门的周湘君大侠,有一位年幼又能吃的徒弟,可有人知道这位徒弟的名字?”",
	["tid#MapEncounterEvent_177"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身嵩山派的左寒修大侠,虽然其内力高深莫测,但因年轻时被仇人暗算,身体内一直残留着一个隐患,可有人知道这隐患是什么?”",
	["tid#MapEncounterEvent_178"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身明教的陆小贝侠女,是位冷艳无情的刺客,但她的名字,却曾属于另外一位美丽的女孩,那女孩的名字有人知道吗?”",
	["tid#MapEncounterEvent_179"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身唐门的唐明月侠女,乃是如今门主唐傲天的小女儿.在其年幼时曾用机关术制造了一条小蛇,有人知道那条小蛇的名字吗?”",
	["tid#MapEncounterEvent_180"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身五毒教的阿岚侠女,从小便喜欢小兔子和小鹿之类的小动物,还喜欢喂小动物吃东西,有人知道她喂的是什么吗?",
	["tid#MapEncounterEvent_181"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身探花门的刑伯严大侠,他有一个一直以来的对手,你们可知是谁?”",
	["tid#MapEncounterEvent_182"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身纯阳宫的吴清霄大侠,乃是现任纯阳宫的掌教.在其年幼陪同师傅云游四海时,还有一个一同修行的师兄,你们可知道是谁?”",
	["tid#MapEncounterEvent_183"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身丐帮的沈念侠女,曾与一位官家一同追捕采花大盗,你们可知这位官家是谁?”",
	["tid#MapEncounterEvent_184"]="你路过一个茶摊,摊上一位先生正在说书：“话说有一位出身天龙门的周文浩大侠,以其一身浑厚无匹的内力冠绝江湖,但你们可知他这身内力从何而来?”",
	["tid#MapEncounterResult_132"]="那男人摇了摇头，转身离开了，你打开箱子，发现里面空空如也（一无所获）",
	["tid#MapEncounterResult_133"]="那男人摇了摇头，转身离开了，你打开箱子，发现里面空空如也（一无所获）",
