	["tid#MapEncounterResult_140"]="那男人点了点头，大笑一声后离开了，你打开箱子，发现里面放满了金银珠宝（获得奖励）",
	["tid#MapEncounterResult_141"]="那男人摇了摇头，转身离开了，你打开箱子，发现里面空空如也（一无所获）（一无所获）",
	["tid#MapEncounterResult_142"]="你循着呼救声冲去，正装上一群强盗欲对一名少女行不轨，那盗匪有人坏事，不由分说就朝你冲了过来。（战斗）",
	["tid#MapEncounterResult_143"]="那大虫凶狠异常，先发出一声虎啸，震得人心肝俱颤，随后便后足发力，朝你扑了过来。（战斗）",
	["tid#MapEncounterResult_144"]="你刚站上擂台，就看见人群中窜出一个剑客，半空中一个转身，轻飘飘的落上了擂台。剑客冲着你一抱拳，接着便提剑刺了过来。（战斗）",
	["tid#MapEncounterResult_145"]="那剑客大量了你一眼，说道“也罢，那就用两分力吧。”随后便提剑做出了迎战姿态。（战斗）",
	["tid#MapEncounterResult_146"]="你拔剑迎战，土匪们也抽出了刀来。（战斗）",
	["tid#MapEncounterResult_147"]="你依照悬赏提供的信息，成功找到了燕云三郎，燕云三郎见被发现，恼羞成怒向你攻来！（战斗）",
	["tid#MapEncounterResult_148"]="你向官府报告了东瀛人的踪迹，官府给了你一笔赏钱。（少量奖励）",
	["tid#MapEncounterResult_149"]="小二神色一慌，匆匆转身离开了，片刻后，店后冲出来几个五大三粗的汉子，将你围了起来。（战斗）",
	["tid#MapEncounterResult_150"]="你前往宝物地点，正撞上另一个来抢夺的人（战斗）",
	["tid#MapEncounterResult_151"]="你再原地等待了半天，终于等来了失主，失主非常感谢你，给了你一些奖励。（获得奖励）",
	["tid#MapEncounterResult_152"]="那说书先生将惊堂木一拍，喊了一声“正是！”，大笑一声后随手将一个包裹抛给了你。（获得奖励）",
	["tid#MapEncounterResult_153"]="那说书先生将扇子一摇，说道“非也非也”，然后继续开始讲书。（一无所获）",
