	["tid#MapEncounterResult_180"]="几个转念之间你便想好了对策，想着呼救处高呼“衙门办事！闲人退避！”，那群强盗闻声后果然四散而逃。（少量奖励）",
	["tid#MapEncounterResult_181"]="你转身就跑，连头都不敢回，一口气跑出了好几个山头才敢停下来。(一无所获)",
	["tid#MapEncounterResult_182"]="你站在擂台便看了半天，看到许多高手见的打斗，武学得到了精进。（少量奖励）",
	["tid#MapEncounterResult_183"]="那剑客冷哼一声，只伸出两根手指就夹住了你偷袭而来的剑尖，随后一掌就将你击退出去数步，再回过神时，已经消失不见（一无所获）",
	["tid#MapEncounterResult_184"]="你转身就跑，连头都不敢回，一口气跑出了好几个山头才敢停下来。(一无所获)",
	["tid#MapEncounterResult_185"]="你找了个人冒充燕云三郎去衙门领赏，但轻易就被识破了，差点被衙门抓起来（一无所获）",
	["tid#MapEncounterResult_186"]="你尾随东瀛人一路来到海岸边，正看到他们准备劫掠商船！（战斗）",
	["tid#MapEncounterResult_187"]="你走到后厨，发现灶上蒸着一屉包子，一旁的肉馅似乎有些奇怪，正欲仔细观察，一旁已经冲出了一个魁梧大汉，将你围了起来。（战斗）",
	["tid#MapEncounterResult_188"]="你避免了麻烦，绕道而行了。（一无所获）",
	["tid#MapEncounterResult_189"]="你准备自己收下，回到家中拆开包裹一看，才发现里面只有一些石头（一无所获）",
