	["tid#MapEncounterResult_213"]="那男人摇了摇头，转身离开了，你打开箱子，发现里面空空如也（一无所获）",
	["tid#MapEncounterResult_214"]="那男人摇了摇头，转身离开了，你打开箱子，发现里面空空如也（一无所获）",
	["tid#MapEncounterResult_215"]="那男人点了点头，大笑一声后离开了，你打开箱子，发现里面放满了金银珠宝（获得奖励）",
	["tid#MapEncounterResult_216"]="那男人摇了摇头，转身离开了，你打开箱子，发现里面空空如也（一无所获）",
	["tid#MapEncounterResult_217"]="那男人点了点头，大笑一声后离开了，你打开箱子，发现里面放满了金银珠宝（获得奖励）",
	["tid#MapEncounterResult_218"]="你不理会耳边的呼救，转身就离开了。（一无所获）",
	["tid#MapEncounterResult_219"]="你扯开嗓子用力呼喊，千钧一发之际，一位头戴斗笠的神秘侠客一旁的山林中冲出，一挥剑便将那大虫击杀。（少量奖励）",
	["tid#MapEncounterResult_220"]="你转身离开了，无视身后的喧嚣，独自美丽……（一无所获）",
	["tid#MapEncounterResult_221"]="那剑客看了你一眼，点了点头，随手舞了几个招式，你看了之后感觉受益良多（少量奖励）",
	["tid#MapEncounterResult_222"]="你乖乖的付了买路钱，土匪们却仍然不放你走。（战斗）",
	["tid#MapEncounterResult_223"]="你没有理会悬赏，转身离开了（一无所获）",
	["tid#MapEncounterResult_224"]="你一把拉住想要离开的东瀛人，说破了他们的计划，东瀛人恼羞成怒，提刀向你冲来（战斗）",
	["tid#MapEncounterResult_225"]="你察觉到了不对，转身离开了。（一无所获）",
	["tid#MapEncounterResult_226"]="你亲眼看着4波人马杀得天昏地暗，最后成功者也匆匆而去，而你搜捡尸体小赚了一笔……（少量奖励）",
	["tid#MapEncounterResult_227"]="你发现草丛中压出了一条蹒跚的脚印，还有血迹，追踪之下发现了失主的遗体。埋葬了失主后，你将包裹收入囊中。（获得奖励）",
	["tid#MapEncounterResult_228"]="那说书先生将扇子一摇，说道“非也非也”，然后继续开始讲书。（一无所获）",
	["tid#MapEncounterResult_229"]="那说书先生将惊堂木一拍，喊了一声“正是！”，大笑一声后随手将一个包裹抛给了你。（获得奖励）",
