	["tid#MapEncounterChoice_275"]="接受传功",
	["tid#MapEncounterEvent_185"]="你路过一处茶摊，摊上一位先生正在说书。'话说太古时期，火神祝融用榣山之木制成了三张琴，一张唤作凰来，一张唤作凤来，可有人知道最后一张琴的名字？”",
	["tid#MapEncounterEvent_186"]="你路过一处茶摊，摊上一位先生正在说书。'话说有位少侠，不小心撞见了一位少女在湖边洗澡。被当作色狼，狠狠修理了一顿，连焚寂剑都丢了。而这，便是百里屠苏和风晴雪的初见。各位，可有人知道他们第一次相遇是在什么地方？”",
	["tid#MapEncounterEvent_187"]="你遇见一位卖饰品的老伯，他捋了捋胡子，问你：'器能寄灵，少侠你知道吗。有个叫做方兰生的年轻人，幼时得到一件物什，从此便一直带在身边，据说这东西寄宿着灵魂！你知道这物什的是什么嘛？“",
	["tid#MapEncounterEvent_188"]="你路过一处茶摊，摊上一位先生正在说书。'话说有一条黑龙，其名为悭臾。修炼千年，有翻江倒海之能，因戏水触怒天庭。为了逃脱天庭责罚，他打伤仙将，逃入不周山，各位，有谁知道他是去寻求谁的庇护？“",
	["tid#MapEncounterEvent_189"]="你路过一处茶摊，摊上一位先生正在说书。'话说有一条黑龙，其名为悭臾。引发不周山倾塌之劫。于是天降罪责，悭臾被剥夺自由，成为坐骑。谁知道这悭臾被收为了谁的坐骑？“",
	["tid#MapEncounterEvent_190"]="你路过一处茶摊，摊上一位先生正在说书。'话说这太子长琴被贬为凡人，削除仙籍。而太子长琴原身“凤来”的三魂七魄于榣山眷恋不去，被龙渊部族工匠角离所得，用来铸成“焚寂”之剑。有谁知道这焚寂之剑是由太子长琴几魂几魄铸成的？“",
	["tid#MapEncounterEvent_191"]="你路过一处茶摊，摊上一位先生正在说书。'话说这焚寂被列为上古七凶剑之一。被封印在乌蒙灵谷的一个山洞中，有谁知道那个山洞的名字？“",
	["tid#MapEncounterEvent_192"]="你路过一处茶摊，摊上一位先生正在说书。'话说百里屠苏和风晴雪虽然相识不久，但经历了种种冒险，暗生情愫。他们二人之后终于表明了心意，约定白头偕老。有谁知道这百里屠苏和风晴雪约定在何处白头偕老？“",
	["tid#MapEncounterEvent_193"]="你路过一处茶摊，摊上一位先生正在说书。'话说这陵端奉命下山寻找百里屠苏，为了逼出百里屠苏，竟罔顾生灵，不惜放火烧山。有谁知道他烧毁了哪里 ？“",
	["tid#MapEncounterEvent_194"]="你路过一处茶摊，摊上一位先生正在说书。'话说瑾娘一见到阿翔就十分喜欢，只因为阿翔和自己以前养的芦花鸡相似。有谁知道瑾娘养的那只芦花鸡叫什么名字 ？“",
	["tid#MapEncounterEvent_195"]="你路过一处茶摊，摊上一位先生正在说书。'话说这是方兰生和襄铃的初遇，有谁知道这是在什么地方？“",
	["tid#MapEncounterEvent_196"]="你路过一处茶摊，摊上一位先生正在说书。'话说方兰生早就对方兰生襄铃暗生情愫，终于忍耐不住，向襄铃表达了心意，有谁知道这是在什么地方 ？“",
	["tid#MapEncounterEvent_197"]="你路过一处茶摊，摊上一位先生正在说书。'话说这方兰生的前世名为晋磊，他为了报师门之仇，参加了自闲山庄的比武招亲。有谁知道他是与谁比武？“",
	["tid#MapEncounterEvent_198"]="你路过一处茶摊，摊上一位先生正在说书。'话说这百里屠苏最好的伙伴阿翔，长得又肥又壮十分可爱，诸位可知道它最爱吃的食物是什么？“",
	["tid#MapEncounterEvent_199"]="你路过一处茶摊，摊上一位先生正在说书。'众所周知，阿翔是百里屠苏小时候在昆仑山雪地上捡到的一只鸟，之后成为了百里屠苏最好的伙伴。在座的各位，可有人知道？“",
	["tid#MapEncounterEvent_200"]="你路过一处茶摊，摊上一位先生正在说书。'话说百里屠苏煞气爆发，自觉不久于人世，于是向晴雪表白。然而风晴雪却没有直接回应。那么诸位，有谁知道风晴雪是在什么地方才向百里屠苏告白的？“",
	["tid#MapEncounterEvent_201"]="你路过一处茶摊，摊上一位先生正在说书。'话说这方兰生仪表堂堂，又是一介书生。可有一人却总唤他做猴儿，有谁知道是谁这样称呼他？“",
	["tid#MapEncounterEvent_202"]="你路过一处茶摊，摊上一位先生正在说书。'话说欧阳少恭终于暴露真实目的，带走了晴雪，并以万千生灵为要挟，约屠苏到东海蓬莱国决战。有谁知道欧阳少恭与屠苏相约在哪里决战？“",
	["tid#MapEncounterEvent_203"]="你路过一处茶摊，摊上一位先生正在说书。'为了与欧阳少恭决战，百里屠苏决定解除封印，解放煞气。为此他回到天墉城，寻求一人的帮助。可有人知道此人是谁？“",
	["tid#MapEncounterEvent_204"]="你路过一处茶摊，摊上一位先生正在说书。'话说有一个门派名叫天墉城，乃天下清气最为合聚之地，极为利于修仙之人的个人修为，自古流传“尊清抑浊”的修炼之法。有谁知道天墉城位于那座名山之上？“",
	["tid#MapEncounterEvent_205"]="你路过一处茶摊，摊上一位先生正在说书。'话说这风晴雪一直在寻找自己的哥哥风千陌，但她的哥哥早已经改名换姓了，有人知道他哥哥现在的名字吗？“",
	["tid#MapEncounterEvent_206"]="你路过一处茶摊，摊上一位先生正在说书。'话说有一位名叫红玉的大侠，本为上古庆枫族族人，后来成为天墉城紫胤真人的剑灵。她外貌妖娆，身具高深的法术，常被人当成女妖。有谁知道这位大侠使用的是什么武器？“",
	["tid#MapEncounterEvent_207"]="你路过一处茶摊，摊上一位先生正在说书。'话说洛云平本身是妖，被人类养大，对人类心存感激，但不料被奸人所骗，让亲人沦怪物。为了不让亲人死去，只得骗了留宿的旅人去给他们做食物。诸位可知，他将人骗往何处？“",
	["tid#MapEncounterEvent_208"]="你路过一处茶摊，摊上一位先生正在说书。'话说有一名女侠名叫芙蕖，她是百里屠苏的师妹。她与百里屠苏曾有一个约定，百里屠苏答应她必会再见。然而约定到期的那天，百里屠苏并没有出现。有谁知道芙蕖与百里屠苏约定多久之后相聚？“",
	["tid#MapEncounterEvent_209"]="你路过一处茶摊，摊上一位先生正在说书。'话说这欧阳少恭自小就有一家谱寂桐常伴左右，但这寂桐可不简单，在座的各位，可有人知道她的真实身份？“",
